INSERT INTO hsk_vocabulary_examples
    (syllabus, level, entry_number, position, sentence_zh, pinyin, translation_vi)
VALUES
    ('3.0-2025', 1, 1, 1, '我从小就爱打篮球。', 'Wǒ cóngxiǎo jiù ài dǎ lán qiú.', 'Tôi thích chơi bóng rổ từ nhỏ.'),
    ('3.0-2025', 1, 1, 2, '我爱爸爸，也爱妈妈。', 'Wǒ ài bàba, yě ài māma.', 'Tôi yêu cả bố lẫn mẹ.'),
    ('3.0-2025', 1, 2, 1, '检票后在车上见面吧。', 'Jiǎnpiào hòu zài chēshàng jiànmiàn ba.', 'Soát vé xong mình gặp nhau trên tàu nhé.'),
    ('3.0-2025', 1, 2, 2, '关上门吧，我们有个会。', 'Guān shàng mén ba, wǒmen yǒu gè huì.', 'Đóng cửa lại nhé, chúng ta có một cuộc họp.'),
    ('3.0-2025', 1, 3, 1, '爸爸买了八个包子和六个鸡蛋。', 'Bàba mǎi le bā gè bāozi hé liù gè jīdàn.', 'Bố mua tám cái bánh bao và sáu quả trứng gà.'),
    ('3.0-2025', 1, 3, 2, '现在八点一刻，请打开课本读课文。', 'Xiànzài bā diǎn yīkè, qǐng dǎkāi kèběn dú kèwén.', 'Bây giờ là tám giờ mười lăm, hãy mở sách giáo khoa ra đọc bài khóa.'),
    ('3.0-2025', 1, 4, 1, '我爱爸爸，也爱妈妈。', 'Wǒ ài bàba, yě ài māma.', 'Tôi yêu cả bố lẫn mẹ.'),
    ('3.0-2025', 1, 4, 2, '午饭后我喝水，爸爸喝咖啡。', 'Wǔfàn hòu wǒ hē shuǐ, bàba hē kā fēi.', 'Sau bữa trưa tôi uống nước, bố uống cà phê.'),
    ('3.0-2025', 1, 5, 1, '买这幅画花了我三百块钱。', 'Mǎi zhè fú huà huā le wǒ sān bǎi kuài qián.', 'Tôi đã tốn ba trăm đồng để mua bức tranh này.'),
    ('3.0-2025', 1, 5, 2, '这本书一百元，两本书两百元。', 'Zhè běn shū yìbǎiyuán, liǎng běn shū liǎng bǎi yuán.', 'Quyển sách này giá một trăm tệ, hai quyển giá hai trăm tệ.'),
    ('3.0-2025', 1, 6, 1, '白天我在公司工作，晚上回家读书。', 'Báitiān wǒ zài gōngsī gōngzuò, wǎnshang huíjiā dúshū.', 'Ban ngày tôi làm việc ở công ty, buổi tối về nhà đọc sách.'),
    ('3.0-2025', 1, 6, 2, '白天超市卖面包，晚上也卖包子和饺子。', 'Báitiān chāoshì mài miànbāo, wǎnshang yě mài bāozi hé jiǎozi.', 'Ban ngày siêu thị bán bánh mì, buổi tối cũng bán bánh bao và sủi cảo.'),
    ('3.0-2025', 1, 7, 1, '现在是九点半，我们走吧。', 'Xiànzài shì jiǔdiǎnbàn, wǒmen zǒu ba.', 'Bây giờ là chín giờ rưỡi, chúng ta đi thôi.'),
    ('3.0-2025', 1, 7, 2, '我吃了一半，剩下的一半给你。', 'Wǒ chī le yībàn, shèngxià de yībàn gěi nǐ.', 'Tôi ăn một nửa, nửa còn lại cho bạn.'),
    ('3.0-2025', 1, 8, 1, '爸爸买了八个包子和六个鸡蛋。', 'Bàba mǎi le bā gè bāozi hé liù gè jīdàn.', 'Bố mua tám cái bánh bao và sáu quả trứng gà.'),
    ('3.0-2025', 1, 8, 2, '白天超市卖面包，晚上也卖包子和饺子。', 'Báitiān chāoshì mài miànbāo, wǎnshang yě mài bāozi hé jiǎozi.', 'Ban ngày siêu thị bán bánh mì, buổi tối cũng bán bánh bao và sủi cảo.'),
    ('3.0-2025', 1, 9, 1, '我渴了，可是杯子里没有水。', 'Wǒ kě le, kěshì bēizi lǐ méiyǒu shuǐ.', 'Tôi khát rồi nhưng trong cốc không có nước.'),
    ('3.0-2025', 1, 9, 2, '这个杯子十二块，那个杯子十五块。', 'Zhège bēizi shí èr kuài, nàge bēizi shí wǔ kuài.', 'Cái cốc này mười hai đồng, cái kia mười lăm đồng.'),
    ('3.0-2025', 1, 10, 1, '你拿两本，我拿三本。', 'Nǐ ná liǎng běn, wǒ ná sān běn.', 'Bạn lấy hai quyển, tôi lấy ba quyển.'),
    ('3.0-2025', 1, 10, 2, '请给我两本书和一杯茶。', 'Qǐng gěi wǒ liǎng běn shū hé yī bēi chá.', 'Cho tôi hai quyển sách và một cốc trà.'),
    ('3.0-2025', 1, 11, 1, '草地太湿，我们差不多走到草地边就停了。', 'Cǎodì tàishī, wǒmen chàbuduō zǒu dào cǎodì biān jiù tíng le.', 'Bãi cỏ ướt quá, chúng tôi đi gần tới mép bãi thì dừng.'),
    ('3.0-2025', 1, 11, 2, '路边停着三辆自行车。', 'Lùbiān tíngzhe sān liàng zìxíngchē.', 'Ven đường có ba chiếc xe đạp đang đỗ.'),
    ('3.0-2025', 1, 12, 1, '她病了两天，今天觉得好些了。', 'Tā bìng le liǎng tiān, jīntiān juéde hǎoxiē le.', 'Cô ấy ốm hai ngày rồi, hôm nay thấy đỡ hơn chút.'),
    ('3.0-2025', 1, 12, 2, '孩子生病了，今天不要去上学。', 'Háizi shēngbìng le, jīntiān búyào qù shàngxué.', 'Đứa trẻ bị ốm rồi, hôm nay đừng đi học.'),
    ('3.0-2025', 1, 13, 1, '谢谢您！不客气。', 'Xièxienín! Bú kèqi.', 'Cảm ơn bác! Không có gì.'),
    ('3.0-2025', 1, 13, 2, '不用谢，真的不客气。', 'Búyòngxiè, zhēnde bú kèqi.', 'Đừng cảm ơn, thật sự không có gì đâu.'),
    ('3.0-2025', 1, 14, 1, '谢谢您！不客气。', 'Xièxienín! Bú kèqi.', 'Cảm ơn bác! Không có gì.'),
    ('3.0-2025', 1, 14, 2, '不用谢，真的不客气。', 'Búyòngxiè, zhēnde bú kèqi.', 'Đừng cảm ơn, thật sự không có gì đâu.'),
    ('3.0-2025', 1, 15, 1, '地铁快要开了，请不要走动。', 'Dìtiě kuàiyào kāi le, qǐng búyào zǒudòng.', 'Tàu điện ngầm sắp chạy, xin đừng đi lại.'),
    ('3.0-2025', 1, 15, 2, '孩子生病了，今天不要去上学。', 'Háizi shēngbìng le, jīntiān búyào qù shàngxué.', 'Đứa trẻ bị ốm rồi, hôm nay đừng đi học.'),
    ('3.0-2025', 1, 16, 1, '我不知道中午要做什么菜。', 'Wǒ bù zhīdào zhōngwǔ yào zuò shénme cài.', 'Tôi chưa biết trưa nay sẽ nấu món gì.'),
    ('3.0-2025', 1, 16, 2, '这些菜很好吃，大家都喜欢。', 'Zhèxiē cài hěn hǎochī, dàjiā dōu xǐhuan.', 'Những món này rất ngon, mọi người đều thích.'),
    ('3.0-2025', 1, 17, 1, '请给我两本书和一杯茶。', 'Qǐng gěi wǒ liǎng běn shū hé yī bēi chá.', 'Cho tôi hai quyển sách và một cốc trà.'),
    ('3.0-2025', 1, 17, 2, '你要红茶还是绿茶？', 'Nǐ yào hóngchá háishi lǜchá?', 'Bạn muốn uống trà đen hay trà xanh?'),
    ('3.0-2025', 1, 18, 1, '弟弟在大学唱的那首中文歌真好听。', 'Dìdi zài dàxué chàng de nà shǒu zhōngwén gēzhēn hǎotīng.', 'Bài hát tiếng Trung em trai hát ở trường đại học nghe rất hay.'),
    ('3.0-2025', 1, 18, 2, '姐姐喜欢唱中文歌，弟弟喜欢看电视。', 'Jiějie xǐhuan chàng zhōngwén gē, dìdi xǐhuan kàndiànshì.', 'Chị gái thích hát nhạc tiếng Trung, em trai thích xem tivi.'),
    ('3.0-2025', 1, 19, 1, '超市在书店旁边，饭店在电影院那边。', 'Chāoshì zài shūdiàn pángbiān, fàndiàn zài diànyǐngyuàn nàbiān.', 'Siêu thị ở cạnh hiệu sách, nhà hàng ở phía rạp chiếu phim.'),
    ('3.0-2025', 1, 19, 2, '白天超市卖面包，晚上也卖包子和饺子。', 'Báitiān chāoshì mài miànbāo, wǎnshang yě mài bāozi hé jiǎozi.', 'Ban ngày siêu thị bán bánh mì, buổi tối cũng bán bánh bao và sủi cảo.'),
    ('3.0-2025', 1, 20, 1, '站在我这边，别站在车那边。', 'Zhàn zài wǒ zhèbiān, biézhàn zài chē nàbiān.', 'Hãy đứng về phía tôi, đừng đứng bên kia xe.'),
    ('3.0-2025', 1, 20, 2, '第一辆车走了，我们坐第二辆。', 'Dìyīliàng chē zǒu le, wǒmen zuò dì''èrliàng.', 'Chiếc xe đầu tiên đi rồi, chúng ta đi chiếc thứ hai.'),
    ('3.0-2025', 1, 21, 1, '你吃过这种鱼吗？', 'Nǐ chī guo zhè zhǒng yú ma?', 'Bạn từng ăn loại cá này chưa?'),
    ('3.0-2025', 1, 21, 2, '我先去吃早饭，再见！', 'Wǒ xiān qù chī zǎofàn, zàijiàn!', 'Tôi đi ăn sáng trước nhé, tạm biệt!'),
    ('3.0-2025', 1, 22, 1, '我常常穿这件蓝衬衫去上班。', 'Wǒ chángcháng chuān zhè jiàn lán chènshān qù shàngbān.', 'Tôi thường mặc chiếc sơ mi xanh này đi làm.'),
    ('3.0-2025', 1, 22, 2, '外边很冷，穿上大衣再出去吧。', 'Wàibian hěn lěng, chuān shàng dàyī zài chūqù ba.', 'Bên ngoài rất lạnh, mặc áo khoác rồi hãy ra ngoài nhé.'),
    ('3.0-2025', 1, 23, 1, '那几个大学生坐出租车去公司修电脑。', 'Nà jǐ gè dàxuéshēng zuò chūzūchē qù gōngsī xiū diànnǎo.', 'Mấy sinh viên đó đi taxi đến công ty sửa máy tính.'),
    ('3.0-2025', 1, 23, 2, '我坐出租车到机场，然后给家人打电话。', 'Wǒ zuò chūzūchē dào jīchǎng, ránhòu gěi jiārén dǎdiànhuà.', 'Tôi đi taxi đến sân bay rồi gọi điện cho gia đình.'),
    ('3.0-2025', 1, 24, 1, '一百减一百是零，一千比一百大。', 'Yìbǎi jiǎn yìbǎi shì líng, yīqiān bǐ yìbǎi dà.', 'Một trăm trừ một trăm bằng không, một nghìn lớn hơn một trăm.'),
    ('3.0-2025', 1, 24, 2, '这张桌子太大，我们想了半天才想到搬它的办法。', 'Zhè zhāng zhuōzi tài dà, wǒmen xiǎng le bàntiān cái xiǎngdào bān tā de bànfǎ.', 'Cái bàn này lớn quá, chúng tôi nghĩ mãi mới tìm được cách khiêng nó đi.'),
    ('3.0-2025', 1, 25, 1, '我正看电视，儿子突然打电话来。', 'Wǒ zhèng kàndiànshì, érzi tūrán dǎdiànhuà lái.', 'Tôi đang xem tivi thì con trai bất ngờ gọi điện.'),
    ('3.0-2025', 1, 25, 2, '我坐出租车到机场，然后给家人打电话。', 'Wǒ zuò chūzūchē dào jīchǎng, ránhòu gěi jiārén dǎdiànhuà.', 'Tôi đi taxi đến sân bay rồi gọi điện cho gia đình.'),
    ('3.0-2025', 1, 26, 1, '他的画很受大家喜爱。', 'Tā de huà hěn shòu dàjiā xǐ''ài.', 'Tranh của anh ấy rất được mọi người yêu thích.'),
    ('3.0-2025', 1, 26, 2, '这些菜很好吃，大家都喜欢。', 'Zhèxiē cài hěn hǎochī, dàjiā dōu xǐhuan.', 'Những món này rất ngon, mọi người đều thích.'),
    ('3.0-2025', 1, 27, 1, '我怎样才能照到天上的月亮？', 'Wǒ zěnyàngcáinéng zhào dào tiānshàng de yuèliang?', 'Làm sao tôi có thể chụp được mặt trăng trên trời?'),
    ('3.0-2025', 1, 27, 2, '读课文时请把课本翻到第六页。', 'Dú kèwén shíqǐng bǎ kèběn fān dào dìliù yè.', 'Khi đọc bài khóa hãy mở sách giáo khoa ra trang sáu.'),
    ('3.0-2025', 1, 28, 1, '这所大学很大，里面有很多大学生。', 'Zhè suǒ dàxué hěndà, lǐmiàn yǒu hěnduō dàxuéshēng.', 'Trường đại học này rất lớn, bên trong có nhiều sinh viên.'),
    ('3.0-2025', 1, 28, 2, '弟弟在大学唱的那首中文歌真好听。', 'Dìdi zài dàxué chàng de nà shǒu zhōngwén gēzhēn hǎotīng.', 'Bài hát tiếng Trung em trai hát ở trường đại học nghe rất hay.'),
    ('3.0-2025', 1, 29, 1, '这所大学很大，里面有很多大学生。', 'Zhè suǒ dàxué hěndà, lǐmiàn yǒu hěnduō dàxuéshēng.', 'Trường đại học này rất lớn, bên trong có nhiều sinh viên.'),
    ('3.0-2025', 1, 29, 2, '那几个大学生坐出租车去公司修电脑。', 'Nà jǐ gè dàxuéshēng zuò chūzūchē qù gōngsī xiū diànnǎo.', 'Mấy sinh viên đó đi taxi đến công ty sửa máy tính.'),
    ('3.0-2025', 1, 30, 1, '这个答案是对的。', 'Zhège dá''àn shì duì de.', 'Đáp án này đúng.'),
    ('3.0-2025', 1, 30, 2, '这条街的名字好记。', 'Zhè tiáo jiē de míngzi hǎojì.', 'Tên con phố này dễ nhớ.'),
    ('3.0-2025', 1, 31, 1, '这是我第一次用电脑写汉字。', 'Zhè shì wǒ dìyīcì yòng diànnǎo xiě hànzì.', 'Đây là lần đầu tôi dùng máy tính viết chữ Hán.'),
    ('3.0-2025', 1, 31, 2, '第一辆车走了，我们坐第二辆。', 'Dìyīliàng chē zǒu le, wǒmen zuò dì''èrliàng.', 'Chiếc xe đầu tiên đi rồi, chúng ta đi chiếc thứ hai.'),
    ('3.0-2025', 1, 32, 1, '市中心有一家店，可以试穿新鞋。', 'Shìzhōngxīn yǒu yījiā diàn, kěyǐ shìchuān xīnxié.', 'Ở trung tâm thành phố có một cửa hàng cho thử giày mới.'),
    ('3.0-2025', 1, 32, 2, '那家店卖很多帽子。', 'Nà jiā diàn mài hěnduō màozi.', 'Cửa hàng kia bán nhiều mũ.'),
    ('3.0-2025', 1, 33, 1, '先生，您几点下班？', 'Xiānsheng, nín jǐdiǎn xiàbān?', 'Thưa ông, mấy giờ ông tan làm?'),
    ('3.0-2025', 1, 33, 2, '现在是九点半，我们走吧。', 'Xiànzài shì jiǔdiǎnbàn, wǒmen zǒu ba.', 'Bây giờ là chín giờ rưỡi, chúng ta đi thôi.'),
    ('3.0-2025', 1, 34, 1, '请把电话号码写在黑板上。', 'Qǐng bǎ diànhuàhàomǎ xiě zài hēibǎn shàng.', 'Hãy viết số điện thoại lên bảng.'),
    ('3.0-2025', 1, 34, 2, '我正看电视，儿子突然打电话来。', 'Wǒ zhèng kàndiànshì, érzi tūrán dǎdiànhuà lái.', 'Tôi đang xem tivi thì con trai bất ngờ gọi điện.'),
    ('3.0-2025', 1, 35, 1, '这是我第一次用电脑写汉字。', 'Zhè shì wǒ dìyīcì yòng diànnǎo xiě hànzì.', 'Đây là lần đầu tôi dùng máy tính viết chữ Hán.'),
    ('3.0-2025', 1, 35, 2, '为了参加会议，别忘记为电脑充电。', 'Wèile cānjiā huìyì, biéwàngjì wèi diànnǎo chōngdiàn.', 'Để dự họp, đừng quên sạc pin cho máy tính.'),
    ('3.0-2025', 1, 36, 1, '我正看电视，儿子突然打电话来。', 'Wǒ zhèng kàndiànshì, érzi tūrán dǎdiànhuà lái.', 'Tôi đang xem tivi thì con trai bất ngờ gọi điện.'),
    ('3.0-2025', 1, 36, 2, '姐姐喜欢唱中文歌，弟弟喜欢看电视。', 'Jiějie xǐhuan chàng zhōngwén gē, dìdi xǐhuan kàndiànshì.', 'Chị gái thích hát nhạc tiếng Trung, em trai thích xem tivi.'),
    ('3.0-2025', 1, 37, 1, '他们去买书，她们去看电影。', 'Tāmen qù mǎi shū, tāmen qù kàn diànyǐng.', 'Họ đi mua sách, còn các cô ấy đi xem phim.'),
    ('3.0-2025', 1, 37, 2, '这部电影很好看，里面的歌也很好听。', 'Zhè bù diànyǐng hěn hǎokàn, lǐmiàn de gē yě hěn hǎotīng.', 'Bộ phim này rất hay, các bài hát trong phim cũng rất hay.'),
    ('3.0-2025', 1, 38, 1, '对，你说得对，这里就是电影院。', 'Duì, nǐ shuōdéduì, zhèlǐ jiùshì diànyǐngyuàn.', 'Đúng, bạn nói đúng, đây chính là rạp chiếu phim.'),
    ('3.0-2025', 1, 38, 2, '超市在书店旁边，饭店在电影院那边。', 'Chāoshì zài shūdiàn pángbiān, fàndiàn zài diànyǐngyuàn nàbiān.', 'Siêu thị ở cạnh hiệu sách, nhà hàng ở phía rạp chiếu phim.'),
    ('3.0-2025', 1, 39, 1, '我很开心，可是弟弟还在哭。', 'Wǒ hěn kāixīn, kěshì dìdi hái zài kū.', 'Tôi rất vui nhưng em trai vẫn đang khóc.'),
    ('3.0-2025', 1, 39, 2, '孩子长大了，已经会照顾弟弟了。', 'Háizi zhǎngdà le, yǐjīng huì zhàogù dìdi le.', 'Đứa trẻ đã lớn và biết chăm sóc em trai rồi.'),
    ('3.0-2025', 1, 40, 1, '两名学生帮奶奶拿东西。', 'Liǎng míng xuéshēng bāng nǎinai ná dōngxi.', 'Hai học sinh giúp bà xách đồ.'),
    ('3.0-2025', 1, 40, 2, '对不起，我拿错了你的东西。', 'Duìbuqǐ, wǒ ná cuò le nǐ de dōngxi.', 'Xin lỗi, tôi lấy nhầm đồ của bạn rồi.'),
    ('3.0-2025', 1, 41, 1, '春天来了，树都开花了。', 'Chūntiān lái le, shù dōu kāihuā le.', 'Mùa xuân đến rồi, cây cối đều nở hoa.'),
    ('3.0-2025', 1, 41, 2, '天气热得她的脸都红了。', 'Tiānqì rèdé tā de liǎn dōu hóng le.', 'Trời nóng đến mức mặt cô ấy đỏ bừng.'),
    ('3.0-2025', 1, 42, 1, '老师让我们把笔记再读一遍。', 'Lǎoshī ràng wǒmen bǎ bǐjì zài dú yībiàn.', 'Cô giáo bảo chúng tôi đọc lại phần ghi chép một lượt.'),
    ('3.0-2025', 1, 42, 2, '读课文时请把课本翻到第六页。', 'Dú kèwén shíqǐng bǎ kèběn fān dào dìliù yè.', 'Khi đọc bài khóa hãy mở sách giáo khoa ra trang sáu.'),
    ('3.0-2025', 1, 43, 1, '这个答案是对的。', 'Zhège dá''àn shì duì de.', 'Đáp án này đúng.'),
    ('3.0-2025', 1, 43, 2, '对，你说得对，这里就是电影院。', 'Duì, nǐ shuōdéduì, zhèlǐ jiùshì diànyǐngyuàn.', 'Đúng, bạn nói đúng, đây chính là rạp chiếu phim.'),
    ('3.0-2025', 1, 44, 1, '对不起，我拿错了你的东西。', 'Duìbuqǐ, wǒ ná cuò le nǐ de dōngxi.', 'Xin lỗi, tôi lấy nhầm đồ của bạn rồi.'),
    ('3.0-2025', 1, 44, 2, '对不起，您说得对，是我记错时间了。', 'Duìbuqǐ, nín shuōdéduì, shì wǒ jìcuò shíjiān le.', 'Xin lỗi, bác nói đúng, tôi nhớ nhầm giờ rồi.'),
    ('3.0-2025', 1, 45, 1, '医生说我要多休息。', 'Yīshēng shuō wǒ yào duō xiūxi.', 'Bác sĩ nói tôi cần nghỉ ngơi nhiều.'),
    ('3.0-2025', 1, 45, 2, '你游得比我快多了。', 'Nǐ yóude bǐ wǒ kuài duō le.', 'Bạn bơi nhanh hơn tôi nhiều.'),
    ('3.0-2025', 1, 46, 1, '休假需要带多少行李？', 'Xiūjià xūyào dài duōshao xíngli?', 'Đi nghỉ phép cần mang bao nhiêu hành lý?'),
    ('3.0-2025', 1, 46, 2, '请问，一个苹果多少钱？', 'Qǐngwèn, yí gè píngguǒ duōshao qián?', 'Xin hỏi, một quả táo bao nhiêu tiền?'),
    ('3.0-2025', 1, 47, 1, '从今天起，我每天读书。', 'Cóngjīntiānqǐ, wǒ měitiān dúshū.', 'Từ hôm nay tôi sẽ đọc sách mỗi ngày.'),
    ('3.0-2025', 1, 47, 2, '请告诉我，你在哪所高中读书？', 'Qǐng gàosu wǒ, nǐ zài nǎ suǒ gāozhōng dúshū?', 'Bạn cho tôi biết bạn học trường cấp ba nào nhé?'),
    ('3.0-2025', 1, 48, 1, '我们班有二十个人。', 'Wǒmen bānyǒu èr shí gè rén.', 'Lớp chúng tôi có hai mươi người.'),
    ('3.0-2025', 1, 48, 2, '六月二日是我的生日。', 'Liùyuè èrrì shì wǒ de shēngrì.', 'Ngày hai tháng sáu là sinh nhật tôi.'),
    ('3.0-2025', 1, 49, 1, '我正看电视，儿子突然打电话来。', 'Wǒ zhèng kàndiànshì, érzi tūrán dǎdiànhuà lái.', 'Tôi đang xem tivi thì con trai bất ngờ gọi điện.'),
    ('3.0-2025', 1, 49, 2, '儿子在房间里读书，女儿正在做饭。', 'Érzi zài fángjiān lǐ dúshū, nǚ''ér zhèngzài zuòfàn.', 'Con trai đang đọc sách trong phòng, con gái đang nấu cơm.'),
    ('3.0-2025', 1, 50, 1, '饭好了，先吃饭再洗碗。', 'Fàn hǎo le, xiān chīfàn zài xǐwǎn.', 'Cơm chín rồi, ăn cơm trước rồi hãy rửa bát.'),
    ('3.0-2025', 1, 50, 2, '我先去吃早饭，再见！', 'Wǒ xiān qù chī zǎofàn, zàijiàn!', 'Tôi đi ăn sáng trước nhé, tạm biệt!'),
    ('3.0-2025', 1, 51, 1, '超市在书店旁边，饭店在电影院那边。', 'Chāoshì zài shūdiàn pángbiān, fàndiàn zài diànyǐngyuàn nàbiān.', 'Siêu thị ở cạnh hiệu sách, nhà hàng ở phía rạp chiếu phim.'),
    ('3.0-2025', 1, 51, 2, '这家饭店的面条儿好吃吗？一碗多少钱？', 'Zhè jiā fàndiàn de miàntiáo''ér hǎochī ma? Yīwǎn duōshao qián?', 'Mì sợi ở nhà hàng này ngon không? Một bát giá bao nhiêu?'),
    ('3.0-2025', 1, 52, 1, '请打开窗户，让房间凉快一点儿。', 'Qǐng dǎkāi chuānghù, ràng fángjiān liángkuai yìdiǎn''ér.', 'Bạn mở cửa sổ cho phòng mát hơn một chút nhé.'),
    ('3.0-2025', 1, 52, 2, '儿子在房间里读书，女儿正在做饭。', 'Érzi zài fángjiān lǐ dúshū, nǚ''ér zhèngzài zuòfàn.', 'Con trai đang đọc sách trong phòng, con gái đang nấu cơm.'),
    ('3.0-2025', 1, 53, 1, '坐飞机非常快，坐火车也很舒服。', 'Zuòfēijī fēicháng kuài, zuòhuǒchē yě hěn shūfu.', 'Đi máy bay rất nhanh, đi tàu hỏa cũng rất thoải mái.'),
    ('3.0-2025', 1, 53, 2, '我的狗非常小，每天只散步十分钟。', 'Wǒ de gǒu fēicháng xiǎo, měitiān zhǐ sànbù shífēnzhōng.', 'Con chó của tôi rất nhỏ, mỗi ngày chỉ đi dạo mười phút.'),
    ('3.0-2025', 1, 54, 1, '飞机要起飞了，请收起桌板。', 'Fēijī yào qǐfēi le, qǐng shōuqǐ zhuōbǎn.', 'Máy bay sắp cất cánh, xin gấp bàn lại.'),
    ('3.0-2025', 1, 54, 2, '真奇怪，汽车刚到，飞机就起飞了。', 'Zhēn qíguài, qìchē gāngdào, fēijī jiù qǐfēi le.', 'Lạ thật, ô tô vừa tới thì máy bay đã cất cánh.'),
    ('3.0-2025', 1, 55, 1, '现在两点三分，还差七分钟。', 'Xiànzài liǎng diǎn sān fēn, hái chà qīfēnzhōng.', 'Bây giờ là hai giờ ba phút, còn thiếu bảy phút nữa.'),
    ('3.0-2025', 1, 55, 2, '现在九点五分，九点十分再出发。', 'Xiànzài jiǔdiǎn wǔfēn, jiǔdiǎn shífēn zài chūfā.', 'Bây giờ là chín giờ năm, chín giờ mười hãy xuất phát.'),
    ('3.0-2025', 1, 56, 1, '现在两点三分，还差七分钟。', 'Xiànzài liǎng diǎn sān fēn, hái chà qīfēnzhōng.', 'Bây giờ là hai giờ ba phút, còn thiếu bảy phút nữa.'),
    ('3.0-2025', 1, 56, 2, '我的狗非常小，每天只散步十分钟。', 'Wǒ de gǒu fēicháng xiǎo, měitiān zhǐ sànbù shífēnzhōng.', 'Con chó của tôi rất nhỏ, mỗi ngày chỉ đi dạo mười phút.'),
    ('3.0-2025', 1, 57, 1, '很高兴认识你，你叫什么名字？', 'Hěn gāoxìng rènshi nǐ, nǐ jiào shénme míngzi?', 'Rất vui được làm quen với bạn, bạn tên là gì?'),
    ('3.0-2025', 1, 57, 2, '六月一日这天，小朋友们很高兴。', 'Liùyuè yīrì zhè tiān, xiǎopéngyǒu men hěn gāoxìng.', 'Vào ngày một tháng sáu các em nhỏ rất vui.'),
    ('3.0-2025', 1, 58, 1, '我们市有个很大的体育馆。', 'Wǒmen shìyǒu gè hěndà de tǐyùguǎn.', 'Thành phố của chúng tôi có một nhà thi đấu rất lớn.'),
    ('3.0-2025', 1, 58, 2, '校长心里很高兴，给大家讲了个新年故事。', 'Xiàozhǎng xīnlǐ hěn gāoxìng, gěi dàjiā jiǎng le gè xīnnián gùshi.', 'Hiệu trưởng rất vui trong lòng và kể cho mọi người một câu chuyện năm mới.'),
    ('3.0-2025', 1, 59, 1, '姐姐喜欢唱中文歌，弟弟喜欢看电视。', 'Jiějie xǐhuan chàng zhōngwén gē, dìdi xǐhuan kàndiànshì.', 'Chị gái thích hát nhạc tiếng Trung, em trai thích xem tivi.'),
