    ('3.0-2025', 1, 228, 1, '下午下雨了，下课以后我坐车回家。', 'Xiàwǔ xiàyǔ le, xiàkè yǐhòu wǒ zuòchē huíjiā.', 'Chiều trời mưa, sau khi tan học tôi đi xe về nhà.'),
    ('3.0-2025', 1, 228, 2, '下课以后一块儿走吧，我们方向一样。', 'Xiàkè yǐhòu yī kuài ér zǒu ba, wǒmen fāngxiàng yíyàng.', 'Tan học mình đi cùng nhau nhé, chúng ta cùng hướng.'),
    ('3.0-2025', 1, 229, 1, '我想去，可今天没空。', 'Wǒ xiǎng qù, kě jīntiān méikòng.', 'Tôi muốn đi nhưng hôm nay không rảnh.'),
    ('3.0-2025', 1, 229, 2, '这个学期你想选哪门课？', 'Zhège xuéqī nǐ xiǎng xuǎn nǎmén kè?', 'Học kỳ này bạn muốn chọn môn nào?'),
    ('3.0-2025', 1, 230, 1, '先生，您几点下班？', 'Xiānsheng, nín jǐdiǎn xiàbān?', 'Thưa ông, mấy giờ ông tan làm?'),
    ('3.0-2025', 1, 230, 2, '喂，先生，您下班后在外边等我吗？', 'Wèi, xiānsheng, nín xiàbān hòu zài wàibian děng wǒ ma?', 'A lô, thưa ông, tan làm ông đợi tôi ở ngoài nhé?'),
    ('3.0-2025', 1, 231, 1, '现在是九点半，我们走吧。', 'Xiànzài shì jiǔdiǎnbàn, wǒmen zǒu ba.', 'Bây giờ là chín giờ rưỡi, chúng ta đi thôi.'),
    ('3.0-2025', 1, 231, 2, '现在两点三分，还差七分钟。', 'Xiànzài liǎng diǎn sān fēn, hái chà qīfēnzhōng.', 'Bây giờ là hai giờ ba phút, còn thiếu bảy phút nữa.'),
    ('3.0-2025', 1, 232, 1, '我十岁，她比我小三岁。', 'Wǒ shí suì, tā bǐ wǒ xiǎo sān suì.', 'Tôi mười tuổi, cô bé nhỏ hơn tôi ba tuổi.'),
    ('3.0-2025', 1, 232, 2, '勺子就在你身边的小桌上。', 'Sháozi jiù zài nǐ shēnbiān de xiǎo zhuōshàng.', 'Cái thìa ở ngay trên bàn nhỏ cạnh bạn.'),
