    ('3.0-2025', 1, 275, 1, '我的妻子早上起来就去跑步。', 'Wǒ de qīzi zǎoshang qǐlái jiù qù pǎobù.', 'Vợ tôi thức dậy buổi sáng là đi chạy bộ ngay.'),
    ('3.0-2025', 1, 275, 2, '早上在河边练太极拳很凉快。', 'Zǎoshang zài hébiān liàn tàijíquán hěn liángkuai.', 'Buổi sáng tập thái cực quyền bên bờ sông rất mát.'),
    ('3.0-2025', 1, 276, 1, '请问，去中学怎么走？', 'Qǐngwèn, qù zhōngxué zěnme zǒu?', 'Xin hỏi, đến trường trung học thì đi thế nào?'),
    ('3.0-2025', 1, 276, 2, '衣服脏了怎么办？', 'Yīfu zāng le zěnmebàn?', 'Quần áo bẩn rồi thì làm thế nào?'),
    ('3.0-2025', 1, 277, 1, '这个游戏好玩儿吗？你觉得怎么样？', 'Zhège yóuxì hǎowán''ér ma? Nǐ juéde zěnmeyàng?', 'Trò chơi này có vui không? Bạn thấy thế nào?'),
    ('3.0-2025', 1, 277, 2, '医院就在这边，你现在感觉怎么样？', 'Yīyuàn jiù zài zhèbiān, nǐ xiànzài gǎnjué zěnmeyàng?', 'Bệnh viện ở ngay bên này, bây giờ bạn thấy thế nào?'),
    ('3.0-2025', 1, 278, 1, '你找谁？这边都是中学生。', 'Nǐ zhǎo shuí? Zhèbiān dōu shì zhōngxuéshēng.', 'Bạn tìm ai? Bên này toàn là học sinh trung học.'),
    ('3.0-2025', 1, 278, 2, '方向找对了，再选合适的方法。', 'Fāngxiàng zhǎo duì le, zàixuǎn héshì de fāngfǎ.', 'Khi đã xác định đúng hướng, hãy chọn phương pháp phù hợp.'),
    ('3.0-2025', 1, 279, 1, '这只羊跳得挺高。', 'Zhè zhǐ yáng tiào dé tǐng gāo.', 'Con cừu này nhảy khá cao.'),
    ('3.0-2025', 1, 279, 2, '这两座楼离得很近。', 'Zhè liǎng zuò lóulí de hěn jìn.', 'Hai tòa nhà này rất gần nhau.'),
    ('3.0-2025', 1, 280, 1, '你找谁？这边都是中学生。', 'Nǐ zhǎo shuí? Zhèbiān dōu shì zhōngxuéshēng.', 'Bạn tìm ai? Bên này toàn là học sinh trung học.'),
    ('3.0-2025', 1, 280, 2, '站在我这边，别站在车那边。', 'Zhàn zài wǒ zhèbiān, biézhàn zài chē nàbiān.', 'Hãy đứng về phía tôi, đừng đứng bên kia xe.'),
    ('3.0-2025', 1, 281, 1, '这个字有几笔？', 'Zhège zì yǒu jǐbǐ?', 'Chữ này có mấy nét?'),
    ('3.0-2025', 1, 281, 2, '这个答案是对的。', 'Zhège dá''àn shì duì de.', 'Đáp án này đúng.'),
    ('3.0-2025', 1, 282, 1, '这里发生了什么事情？', 'Zhèlǐ fāshēng le shénme shìqing?', 'Ở đây đã xảy ra chuyện gì?'),
    ('3.0-2025', 1, 282, 2, '别着急，车站离这里不远。', 'Biézháojí, chēzhàn lí zhèlǐ bùyuǎn.', 'Đừng sốt ruột, bến xe cách đây không xa.'),
    ('3.0-2025', 1, 283, 1, '这件女式上衣颜色真漂亮。', 'Zhè jiàn nǚshì shàngyī yánsè zhēn piàoliang.', 'Màu của chiếc áo nữ này đẹp thật.'),
    ('3.0-2025', 1, 283, 2, '这些小猫真可爱，我想养一只。', 'Zhèxiē xiǎomāo zhēn kě''ài, wǒ xiǎng yǎng yīzhī.', 'Những con mèo con này đáng yêu thật, tôi muốn nuôi một con.'),
    ('3.0-2025', 1, 284, 1, '三年级的女生正在画一头牛。', 'Sān nián jí de nǚshēng zhèngzài huà yītóu niú.', 'Bạn nữ lớp ba đang vẽ một con bò.'),
    ('3.0-2025', 1, 284, 2, '这所小学的小学生正在学写字。', 'Zhè suǒ xiǎoxué de xiǎoxuéshēng zhèngzài xué xiězì.', 'Học sinh trường tiểu học này đang học viết chữ.'),
    ('3.0-2025', 1, 285, 1, '你要去哪儿？那儿离这儿远吗？', 'Nǐ yào qù nǎ''ér? Nà ér lí zhè ér yuǎn ma?', 'Bạn muốn đi đâu? Chỗ đó có xa đây không?'),
    ('3.0-2025', 1, 285, 2, '这儿有两只猫，一半的猫粮留给小猫。', 'Zhè ér yǒu liǎng zhī māo, yībàn de māo liáng liúgěi xiǎomāo.', 'Ở đây có hai con mèo, hãy để lại nửa phần thức ăn cho mèo con.'),
    ('3.0-2025', 1, 286, 1, '请先洗手，再洗这些盘子。', 'Qǐng xiān xǐshǒu, zài xǐ zhèxiē pánzi.', 'Hãy rửa tay trước rồi rửa những chiếc đĩa này.'),
    ('3.0-2025', 1, 286, 2, '这些菜很好吃，大家都喜欢。', 'Zhèxiē cài hěn hǎochī, dàjiā dōu xǐhuan.', 'Những món này rất ngon, mọi người đều thích.'),
    ('3.0-2025', 1, 287, 1, '这些小猫真可爱，我想养一只。', 'Zhèxiē xiǎomāo zhēn kě''ài, wǒ xiǎng yǎng yīzhī.', 'Những con mèo con này đáng yêu thật, tôi muốn nuôi một con.'),
    ('3.0-2025', 1, 287, 2, '这儿有两只猫，一半的猫粮留给小猫。', 'Zhè ér yǒu liǎng zhī māo, yībàn de māo liáng liúgěi xiǎomāo.', 'Ở đây có hai con mèo, hãy để lại nửa phần thức ăn cho mèo con.'),
    ('3.0-2025', 1, 288, 1, '我不知道中午要做什么菜。', 'Wǒ bù zhīdào zhōngwǔ yào zuò shénme cài.', 'Tôi chưa biết trưa nay sẽ nấu món gì.'),
    ('3.0-2025', 1, 288, 2, '我只能周末去，只是还不知道几点。', 'Wǒ zhǐnéng zhōumò qù, zhǐshì hái bù zhīdào jǐdiǎn.', 'Tôi chỉ có thể đi vào cuối tuần, chỉ là chưa biết mấy giờ.'),
    ('3.0-2025', 1, 289, 1, '我去过中国，还想再去一次。', 'Wǒ qùguo zhōngguó, hái xiǎng zài qù yīcì.', 'Tôi từng đến Trung Quốc và muốn đi thêm một lần nữa.'),
    ('3.0-2025', 1, 289, 2, '你想去哪个国家？我想去中国。', 'Nǐ xiǎng qù nǎge guójiā? Wǒ xiǎng qù zhōngguó.', 'Bạn muốn đi nước nào? Tôi muốn đến Trung Quốc.'),
    ('3.0-2025', 1, 290, 1, '我教中文，她教数学。', 'Wǒ jiāo zhōngwén, tā jiāo shùxué.', 'Tôi dạy tiếng Trung, cô ấy dạy toán.'),
    ('3.0-2025', 1, 290, 2, '我叫小安，我会说中文。', 'Wǒ jiào xiǎo''ān, wǒ huì shuō zhōngwén.', 'Tôi tên là Tiểu An, tôi biết nói tiếng Trung.'),
    ('3.0-2025', 1, 291, 1, '我不知道中午要做什么菜。', 'Wǒ bù zhīdào zhōngwǔ yào zuò shénme cài.', 'Tôi chưa biết trưa nay sẽ nấu món gì.'),
    ('3.0-2025', 1, 291, 2, '我在外地的图书馆学外语，中午点外卖。', 'Wǒ zài wàidì de túshūguǎnxué wàiyǔ, zhōngwǔ diǎn wàimài.', 'Tôi học ngoại ngữ tại thư viện khi xa nhà, buổi trưa đặt đồ ăn giao tới.'),
    ('3.0-2025', 1, 292, 1, '请问，去中学怎么走？', 'Qǐngwèn, qù zhōngxué zěnme zǒu?', 'Xin hỏi, đến trường trung học thì đi thế nào?'),
    ('3.0-2025', 1, 292, 2, '你找谁？这边都是中学生。', 'Nǐ zhǎo shuí? Zhèbiān dōu shì zhōngxuéshēng.', 'Bạn tìm ai? Bên này toàn là học sinh trung học.'),
    ('3.0-2025', 1, 293, 1, '你找谁？这边都是中学生。', 'Nǐ zhǎo shuí? Zhèbiān dōu shì zhōngxuéshēng.', 'Bạn tìm ai? Bên này toàn là học sinh trung học.'),
    ('3.0-2025', 1, 293, 2, '小学门口有一些小学生，椅子上还坐着几个中学生。', 'Xiǎoxué ménkǒu yǒu yìxiē xiǎoxuéshēng, yǐzi shàng hái zuò zhe jǐ gè zhōngxuéshēng.', 'Trước cổng trường tiểu học có vài học sinh tiểu học, trên ghế còn có mấy học sinh trung học đang ngồi.'),
    ('3.0-2025', 1, 294, 1, '这位名人住在城市的南边。', 'Zhè wèi míngrén zhù zài chéngshì de nánbiān.', 'Người nổi tiếng này sống ở phía nam thành phố.'),
    ('3.0-2025', 1, 294, 2, '你住在哪里？我就住在那里。', 'Nǐ zhù zài nǎlǐ? Wǒ jiù zhù zài nàlǐ.', 'Bạn sống ở đâu? Tôi sống ngay ở chỗ đó.'),
    ('3.0-2025', 1, 295, 1, '睡觉的时候，我把手机放在桌子上。', 'Shuìjiào de shíhou, wǒ bǎ shǒujī fàngzài zhuōzi shàng.', 'Lúc đi ngủ, tôi đặt điện thoại lên bàn.'),
    ('3.0-2025', 1, 295, 2, '我们家有四口人，可以坐这张桌子吗？', 'Wǒmen jiāyǒu sìkǒu rén, kěyǐ zuò zhè zhāng zhuōzi ma?', 'Nhà tôi có bốn người, chúng tôi ngồi bàn này được không?'),
    ('3.0-2025', 1, 296, 1, '这个字有几笔？', 'Zhège zì yǒu jǐbǐ?', 'Chữ này có mấy nét?'),
    ('3.0-2025', 1, 296, 2, '你来得真早，这些字都会写了吗？', 'Nǐ láide zhēn zǎo, zhèxiē zì dū huì xiě le ma?', 'Bạn đến sớm thật, bạn viết được hết những chữ này rồi à?'),
    ('3.0-2025', 1, 297, 1, '我以为你一般都坐公交车。', 'Wǒ yǐwèi nǐ yìbān dōu zuò gōngjiāochē.', 'Tôi tưởng bạn thường đi xe buýt.'),
    ('3.0-2025', 1, 297, 2, '第一辆车走了，我们坐第二辆。', 'Dìyīliàng chē zǒu le, wǒmen zuò dì''èrliàng.', 'Chiếc xe đầu tiên đi rồi, chúng ta đi chiếc thứ hai.'),
    ('3.0-2025', 1, 298, 1, '请尝尝我们常常做的鱼。', 'Qǐng chángcháng wǒmen chángcháng zuò de yú.', 'Hãy nếm thử món cá chúng tôi thường làm.'),
    ('3.0-2025', 1, 298, 2, '我不知道中午要做什么菜。', 'Wǒ bù zhīdào zhōngwǔ yào zuò shénme cài.', 'Tôi chưa biết trưa nay sẽ nấu món gì.'),
    ('3.0-2025', 1, 299, 1, '有些人爱做饭，有的人只喜欢吃。', 'Yǒuxiē rén''ài zuòfàn, yǒu de rén zhǐ xǐhuan chī.', 'Một số người thích nấu ăn, có người chỉ thích ăn thôi.'),
    ('3.0-2025', 1, 299, 2, '儿子在房间里读书，女儿正在做饭。', 'Érzi zài fángjiān lǐ dúshū, nǚ''ér zhèngzài zuòfàn.', 'Con trai đang đọc sách trong phòng, con gái đang nấu cơm.'),
    ('3.0-2025', 1, 300, 1, '昨天这里下雪了，今天又下雨了。', 'Zuótiān zhèlǐ xiàxuě le, jīntiān yòu xiàyǔ le.', 'Hôm qua ở đây có tuyết rơi, hôm nay trời lại mưa.'),
    ('3.0-2025', 1, 300, 2, '今天来了好多游客，好像比昨天还多。', 'Jīntiān lái le hǎoduō yóukè, hǎoxiàng bǐ zuótiān hái duō.', 'Hôm nay có rất nhiều du khách, hình như còn đông hơn hôm qua.'),
    ('3.0-2025', 2, 301, 1, '啊，原来你的爱好是跳舞！', 'A, yuánlái nǐ de àihào shì tiàowǔ!', 'À, hóa ra sở thích của bạn là nhảy!'),
    ('3.0-2025', 2, 301, 2, '啊，你也在这儿！你的爱好也是画画吗？', 'A, nǐ yě zài zhè ér! Nǐ de àihào yě shì huàhuà ma?', 'À, bạn cũng ở đây! Sở thích của bạn cũng là vẽ à?'),
    ('3.0-2025', 2, 302, 1, '啊，原来你的爱好是跳舞！', 'A, yuánlái nǐ de àihào shì tiàowǔ!', 'À, hóa ra sở thích của bạn là nhảy!'),
    ('3.0-2025', 2, 302, 2, '啊，你也在这儿！你的爱好也是画画吗？', 'A, nǐ yě zài zhè ér! Nǐ de àihào yě shì huàhuà ma?', 'À, bạn cũng ở đây! Sở thích của bạn cũng là vẽ à?'),
    ('3.0-2025', 2, 303, 1, '白色的包比黑色的包便宜。', 'Báisè de bāobǐ hēisè de bāo piányi.', 'Cái túi trắng rẻ hơn cái túi đen.'),
    ('3.0-2025', 2, 303, 2, '不好意思，请帮忙把白色的球鞋放在后面。', 'Bùhǎoyìsi, qǐng bāngmáng bǎ báisè de qiúxié fàngzài hòumiàn.', 'Xin lỗi, nhờ bạn để đôi giày thể thao màu trắng ra phía sau.'),
    ('3.0-2025', 2, 304, 1, '我们班有二十个人。', 'Wǒmen bānyǒu èr shí gè rén.', 'Lớp chúng tôi có hai mươi người.'),
    ('3.0-2025', 2, 304, 2, '每班出一名学生参加比赛。', 'Měibān chū yīmíng xuéshēng cānjiā bǐsài.', 'Mỗi lớp cử một học sinh tham gia cuộc thi.'),
    ('3.0-2025', 2, 305, 1, '行，我来帮你拿行李。', 'Xíng, wǒ lái bāng nǐ ná xíngli.', 'Được, để tôi giúp bạn xách hành lý.'),
