    ('3.0-2025', 2, 355, 1, '红色的花在屋子后面。', 'Hóngsè de huā zài wūzi hòumiàn.', 'Những bông hoa đỏ ở phía sau nhà.'),
    ('3.0-2025', 2, 355, 2, '黑色的包里有红色的花，都是送给你的。', 'Hēisè de bāolǐ yǒu hóngsè de huā, dōu shì sònggěi nǐ de.', 'Trong túi đen có những bông hoa đỏ, tất cả đều tặng bạn.'),
    ('3.0-2025', 2, 356, 1, '红色的花在屋子后面。', 'Hóngsè de huā zài wūzi hòumiàn.', 'Những bông hoa đỏ ở phía sau nhà.'),
    ('3.0-2025', 2, 356, 2, '不好意思，请帮忙把白色的球鞋放在后面。', 'Bùhǎoyìsi, qǐng bāngmáng bǎ báisè de qiúxié fàngzài hòumiàn.', 'Xin lỗi, nhờ bạn để đôi giày thể thao màu trắng ra phía sau.'),
    ('3.0-2025', 2, 357, 1, '买这幅画花了我三百块钱。', 'Mǎi zhè fú huà huā le wǒ sān bǎi kuài qián.', 'Tôi đã tốn ba trăm đồng để mua bức tranh này.'),
    ('3.0-2025', 2, 357, 2, '花钱以前，先看看还剩多少。', 'Huā qián yǐqián, xiān kànkàn hái shèng duōshao.', 'Trước khi tiêu tiền hãy xem còn lại bao nhiêu.'),
    ('3.0-2025', 2, 358, 1, '红色的花在屋子后面。', 'Hóngsè de huā zài wūzi hòumiàn.', 'Những bông hoa đỏ ở phía sau nhà.'),
    ('3.0-2025', 2, 358, 2, '黑色的包里有红色的花，都是送给你的。', 'Hēisè de bāolǐ yǒu hóngsè de huā, dōu shì sònggěi nǐ de.', 'Trong túi đen có những bông hoa đỏ, tất cả đều tặng bạn.'),
    ('3.0-2025', 2, 359, 1, '他的画很受大家喜爱。', 'Tā de huà hěn shòu dàjiā xǐ''ài.', 'Tranh của anh ấy rất được mọi người yêu thích.'),
    ('3.0-2025', 2, 359, 2, '三年级的女生正在画一头牛。', 'Sān nián jí de nǚshēng zhèngzài huà yītóu niú.', 'Bạn nữ lớp ba đang vẽ một con bò.'),
    ('3.0-2025', 2, 360, 1, '空调坏了，宝宝热得哭了。', 'Kōngtiáo huài le, bǎobǎo rèdé kū le.', 'Điều hòa hỏng rồi, em bé nóng đến phát khóc.'),
    ('3.0-2025', 2, 360, 2, '手表坏了，我打算拿回去换。', 'Shǒubiǎo huài le, wǒ dǎsuàn náhuíqù huàn.', 'Đồng hồ hỏng rồi, tôi định mang về đổi.'),
    ('3.0-2025', 2, 361, 1, '等我从机场回来，再一起买机票。', 'Děng wǒ cóng jīchǎng huílái, zài yìqǐ mǎi jīpiào.', 'Đợi tôi từ sân bay về rồi chúng ta cùng mua vé máy bay.'),
    ('3.0-2025', 2, 361, 2, '我们打算去看大熊猫，大概下午三点回来。', 'Wǒmen dǎsuàn qù kàn dàxióngmāo, dàgài xiàwǔ sān diǎn huílái.', 'Chúng tôi định đi xem gấu trúc, khoảng ba giờ chiều sẽ về.'),
