    ('3.0-2025', 2, 382, 1, '门外有雪，晚上可能还有雨。', 'Ménwài yǒuxuě, wǎnshang kěnéng háiyǒu yǔ.', 'Ngoài cửa có tuyết, buổi tối có thể còn mưa.'),
    ('3.0-2025', 2, 382, 2, '考试快开始了，今天可能考数学。', 'Kǎoshì kuài kāishǐ le, jīntiān kěnéng kǎo shùxué.', 'Kỳ thi sắp bắt đầu, hôm nay có thể thi toán.'),
    ('3.0-2025', 2, 383, 1, '祝你生日快乐！这条裤子送给你。', 'Zhù nǐ shēngrìkuàilè! Zhè tiáo kùzi sònggěi nǐ.', 'Chúc bạn sinh nhật vui vẻ! Tặng bạn chiếc quần này.'),
    ('3.0-2025', 2, 383, 2, '出去旅游要带长裤子，不然腿会冷。', 'Chūqù lǚyóu yào dàicháng kùzi, bùrán tuǐ huì lěng.', 'Đi du lịch phải mang quần dài, nếu không chân sẽ lạnh.'),
    ('3.0-2025', 2, 384, 1, '你游得比我快多了。', 'Nǐ yóude bǐ wǒ kuài duō le.', 'Bạn bơi nhanh hơn tôi nhiều.'),
    ('3.0-2025', 2, 384, 2, '快从教室出来，老师在等你。', 'Kuài cóng jiàoshì chūlái, lǎoshī zài děng nǐ.', 'Mau ra khỏi lớp đi, cô giáo đang đợi bạn.'),
    ('3.0-2025', 2, 385, 1, '这次旅行快乐极了，我会一直记着。', 'Zhè cì lǚxíng kuàilè jíle, wǒ huì yìzhí jìzhe.', 'Chuyến đi này vui vô cùng, tôi sẽ nhớ mãi.'),
    ('3.0-2025', 2, 385, 2, '祝你生日快乐！这条裤子送给你。', 'Zhù nǐ shēngrìkuàilè! Zhè tiáo kùzi sònggěi nǐ.', 'Chúc bạn sinh nhật vui vẻ! Tặng bạn chiếc quần này.'),
    ('3.0-2025', 2, 386, 1, '地铁快要开了，请不要走动。', 'Dìtiě kuàiyào kāi le, qǐng búyào zǒudòng.', 'Tàu điện ngầm sắp chạy, xin đừng đi lại.'),
    ('3.0-2025', 2, 386, 2, '快要开学了，第一次考试考哪些课？', 'Kuàiyào kāixué le, dìyīcì kǎoshì kǎo nǎxiē kè?', 'Sắp khai giảng rồi, kỳ thi đầu tiên thi những môn nào?'),
    ('3.0-2025', 2, 387, 1, '高中时他的个子不高，但是篮球打得不错。', 'Gāozhōng shí tā de gèzi bùgāo, dànshì lánqiú dǎ dé búcuò.', 'Hồi cấp ba cậu ấy không cao nhưng chơi bóng rổ khá tốt.'),
    ('3.0-2025', 2, 387, 2, '我从小就爱打篮球。', 'Wǒ cóngxiǎo jiù ài dǎ lán qiú.', 'Tôi thích chơi bóng rổ từ nhỏ.'),
    ('3.0-2025', 2, 388, 1, '她跑累了，就坐下来喝绿茶。', 'Tā pǎo lèi le, jiù zuòxià lái hē lǜchá.', 'Cô ấy chạy mệt rồi nên ngồi xuống uống trà xanh.'),
    ('3.0-2025', 2, 388, 2, '没关系，我没事，只是有点儿累。', 'Méiguānxi, wǒ méishì, zhǐshì yǒudiǎn''ér lèi.', 'Không sao, tôi vẫn ổn, chỉ hơi mệt một chút.'),
    ('3.0-2025', 2, 389, 1, '别着急，车站离这里不远。', 'Biézháojí, chēzhàn lí zhèlǐ bùyuǎn.', 'Đừng sốt ruột, bến xe cách đây không xa.'),
    ('3.0-2025', 2, 389, 2, '你要去哪儿？那儿离这儿远吗？', 'Nǐ yào qù nǎ''ér? Nà ér lí zhè ér yuǎn ma?', 'Bạn muốn đi đâu? Chỗ đó có xa đây không?'),
    ('3.0-2025', 2, 390, 1, '这所大学很大，里面有很多大学生。', 'Zhè suǒ dàxué hěndà, lǐmiàn yǒu hěnduō dàxuéshēng.', 'Trường đại học này rất lớn, bên trong có nhiều sinh viên.'),
    ('3.0-2025', 2, 390, 2, '这部电影很好看，里面的歌也很好听。', 'Zhè bù diànyǐng hěn hǎokàn, lǐmiàn de gē yě hěn hǎotīng.', 'Bộ phim này rất hay, các bài hát trong phim cũng rất hay.'),
    ('3.0-2025', 2, 391, 1, '这栋楼里面有一家旅行社，我们去问问旅游的事吧。', 'Zhè dòng lóu lǐmiàn yǒu yījiā lǚxíngshè, wǒmen qù wènwèn lǚyóu de shì ba.', 'Trong tòa nhà này có một công ty lữ hành, mình đến hỏi chuyện du lịch nhé.'),
    ('3.0-2025', 2, 391, 2, '这两座楼离得很近。', 'Zhè liǎng zuò lóulí de hěn jìn.', 'Hai tòa nhà này rất gần nhau.'),
    ('3.0-2025', 2, 392, 1, '从东往西走，哪条路最短？', 'Cóngdōng wǎngxī zǒu, nǎtiáo lù zuì duǎn?', 'Đi từ đông sang tây thì đường nào ngắn nhất?'),
    ('3.0-2025', 2, 392, 2, '每周走这段路，我都觉得很开心。', 'Měizhōu zǒu zhè duàn lù, wǒ dōu juéde hěn kāixīn.', 'Mỗi tuần đi đoạn đường này tôi đều thấy rất vui.'),
    ('3.0-2025', 2, 393, 1, '一万人往体育馆走，路上很热闹。', 'Yīwàn rénwǎng tǐyùguǎn zǒu, lùshang hěn rènào.', 'Mười nghìn người đi về phía nhà thi đấu, trên đường rất nhộn nhịp.'),
    ('3.0-2025', 2, 393, 2, '这条路很长，不过路上的风景不错。', 'Zhè tiáo lù hěnzhǎng, bùguò lùshang de fēngjǐng búcuò.', 'Con đường này dài nhưng phong cảnh dọc đường khá đẹp.'),
    ('3.0-2025', 2, 394, 1, '明年你和男朋友想去哪儿旅游呢？', 'Míngnián nǐ hé nánpéngyou xiǎng qù nǎ''ér lǚyóu ne?', 'Năm sau bạn và bạn trai muốn đi du lịch ở đâu vậy?'),
    ('3.0-2025', 2, 394, 2, '出去旅游要带长裤子，不然腿会冷。', 'Chūqù lǚyóu yào dàicháng kùzi, bùrán tuǐ huì lěng.', 'Đi du lịch phải mang quần dài, nếu không chân sẽ lạnh.'),
    ('3.0-2025', 2, 395, 1, '你要红茶还是绿茶？', 'Nǐ yào hóngchá háishi lǜchá?', 'Bạn muốn uống trà đen hay trà xanh?'),
    ('3.0-2025', 2, 395, 2, '她跑累了，就坐下来喝绿茶。', 'Tā pǎo lèi le, jiù zuòxià lái hē lǜchá.', 'Cô ấy chạy mệt rồi nên ngồi xuống uống trà xanh.'),
    ('3.0-2025', 2, 396, 1, '绿色的门在左边，右边是洗手间。', 'Lǜsè de mén zài zuǒbian, yòubian shì xǐshǒujiān.', 'Cánh cửa xanh lá ở bên trái, bên phải là nhà vệ sinh.'),
    ('3.0-2025', 2, 396, 2, '绿色的门票那么贵，我觉得没意思。', 'Lǜsè de ménpiào nàme guì, wǒ juéde méiyìsi.', 'Cái vé màu xanh lá đắt thế, tôi thấy chẳng thú vị.'),
    ('3.0-2025', 2, 397, 1, '这匹老马跑得比那辆车慢。', 'Zhè pǐ lǎomǎ pǎo de bǐ nà liàng chē màn.', 'Con ngựa già này chạy chậm hơn chiếc xe kia.'),
    ('3.0-2025', 2, 397, 2, '我慢慢地说，你能听懂吗？', 'Wǒ mànmàn deshuō, nǐ néng tīngdǒng ma?', 'Tôi nói chậm thôi, bạn có nghe hiểu được không?'),
    ('3.0-2025', 2, 398, 1, '这个节目没意思，我们出去跑步吧。', 'Zhège jiémù méiyìsi, wǒmen chūqù pǎobù ba.', 'Chương trình này chán quá, mình ra ngoài chạy bộ nhé.'),
    ('3.0-2025', 2, 398, 2, '绿色的门票那么贵，我觉得没意思。', 'Lǜsè de ménpiào nàme guì, wǒ juéde méiyìsi.', 'Cái vé màu xanh lá đắt thế, tôi thấy chẳng thú vị.'),
    ('3.0-2025', 2, 399, 1, '每一季都有新花，不同季节看到的花也不同。', 'Měi yījì dōu yǒu xīn huā, bùtóng jìjié kàndào de huā yě bùtóng.', 'Mỗi mùa đều có hoa mới, mỗi mùa lại thấy những loài hoa khác nhau.'),
    ('3.0-2025', 2, 399, 2, '我每次都记不住这个词。', 'Wǒ měicì dōu jìbúzhù zhège cí.', 'Lần nào tôi cũng không nhớ được từ này.'),
    ('3.0-2025', 2, 400, 1, '球飞进了门，大家都站起来了。', 'Qiúfēijìn le mén, dàjiā dōu zhàn qǐlái le.', 'Bóng bay vào gôn, mọi người đều đứng dậy.'),
    ('3.0-2025', 2, 400, 2, '绿色的门在左边，右边是洗手间。', 'Lǜsè de mén zài zuǒbian, yòubian shì xǐshǒujiān.', 'Cánh cửa xanh lá ở bên trái, bên phải là nhà vệ sinh.'),
    ('3.0-2025', 2, 401, 1, '小区门口车多，出门小心。', 'Xiǎoqū ménkǒu chēduō, chūmén xiǎoxīn.', 'Cổng khu dân cư đông xe, ra ngoài hãy cẩn thận.'),
    ('3.0-2025', 2, 401, 2, '请在门口买门票，每人一张。', 'Qǐng zài ménkǒu mǎi ménpiào, měirén yīzhāng.', 'Xin mua vé vào cửa ở cổng, mỗi người một vé.'),
