-- Character readings and glosses adapted from Kai Hanzi HSK × Sino-Vietnamese (CC BY 4.0).
-- https://github.com/binhbuithithanh/hanzi-sino-vietnamese | https://creativecommons.org/licenses/by/4.0/
-- Parts of speech: November 2025 HSK examination syllabus, entry-level uses.
-- https://github.com/uranbekanarbaev/hsk-3.0-vocabulary-dataset/tree/main/word-lists
-- V22 already supplies the details and both examples for entry 147.
UPDATE hsk_vocabulary AS v
SET han_viet = d.reading, han_viet_note_vi = d.breakdown,
    word_type_vi = d.word_type, usage_note_vi = d.usage_note
FROM (VALUES
    (1, 1, 'ái', '爱 (ái): yêu, yêu thương; thích.', 'Động từ', 'Trong cách nói “我从小就爱打篮球”, 爱 mang nghĩa “yêu”.'),
    (1, 2, 'ba', '吧 (ba): trợ từ ngữ khí (nhé, đi).', 'Trợ từ', 'Đặt cuối câu để lời rủ rê hoặc đề nghị nhẹ nhàng hơn.'),
    (1, 3, 'bát', '八 (bát): tám, số 8.', 'Số từ', 'Trong cách nói “爸爸买了八个包子和六个鸡蛋”, 八 mang nghĩa “tám”.'),
    (1, 4, 'ba ba', '爸 (ba): bố, ba.', 'Danh từ', 'Trong cách nói “我爱爸爸”, 爸爸 mang nghĩa “bố”.'),
    (1, 5, 'bách', '百 (bách): trăm.', 'Số từ', 'Trong cách nói “买这幅画花了我三百块钱”, 百 mang nghĩa “trăm”.'),
    (1, 6, 'bạch thiên', '白 (bạch): trắng; rõ ràng. 天 (thiên): trời, bầu trời; ngày.', 'Danh từ', 'Trong cách nói “白天我在公司工作”, 白天 mang nghĩa “ban ngày”.'),
    (1, 7, 'bán', '半 (bán): nửa, một nửa.', 'Số từ', 'Trong cách nói “现在是九点半”, 半 mang nghĩa “nửa”.'),
    (1, 8, 'bao tử', '包 (bao): túi, cặp; bao bọc. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “爸爸买了八个包子和六个鸡蛋”, 包子 mang nghĩa “bánh bao”.'),
    (1, 9, 'bôi tử', '杯 (bôi): cái chén, cái cốc. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “可是杯子里没有水”, 杯子 mang nghĩa “cốc, ly”.'),
    (1, 10, 'bản', '本 (bản): gốc; quyển (sách).', 'Lượng từ', 'Đặt giữa số và danh từ chỉ sách, vở.'),
    (1, 11, 'biên', '边 (biên): bên, cạnh, rìa.', 'Danh từ, Hậu tố', 'Trong cách nói “我们差不多走到草地边就停了”, 边 mang nghĩa “bên, phía”.'),
    (1, 12, 'bệnh', '病 (bệnh): bệnh, ốm đau.', 'Danh từ, Động từ', 'Trong cách nói “她病了两天”, 病 mang nghĩa “bệnh”.'),
    (1, 13, 'bất', '不 (bất): không (phủ định).', 'Phó từ', 'Trong cách nói “不客气”, 不 mang nghĩa “không”.'),
    (1, 14, 'bất khách khí', '不 (bất): không (phủ định). 客 (khách): khách, người ghé thăm. 气 (khí): hơi, khí; giận.', 'Cụm từ', 'Trong cách nói “不客气”, 不客气 mang nghĩa “không có gì (đáp lời cảm ơn)”.'),
    (1, 15, 'bất yếu', '不 (bất): không (phủ định). 要 (yếu): cần, muốn; quan trọng.', 'Phó từ', 'Trong cách nói “请不要走动”, 不要 mang nghĩa “đừng”.'),
    (1, 16, 'thái', '菜 (thái): rau; món ăn.', 'Danh từ', 'Trong cách nói “我不知道中午要做什么菜”, 菜 mang nghĩa “món ăn”.'),
    (1, 17, 'trà', '茶 (trà): trà, chè.', 'Danh từ', 'Trong cách nói “请给我两本书和一杯茶”, 茶 mang nghĩa “trà”.'),
    (1, 18, 'xướng', '唱 (xướng): hát, xướng lên.', 'Động từ', 'Trong cách nói “弟弟在大学唱的那首中文歌真好听”, 唱 mang nghĩa “hát”.'),
    (1, 19, 'siêu thị', '超 (siêu): vượt qua, siêu, hơn. 市 (thị): chợ; thành phố.', 'Danh từ', 'Trong cách nói “超市在书店旁边”, 超市 mang nghĩa “siêu thị”.'),
    (1, 20, 'xa', '车 (xa): xe, xe cộ.', 'Danh từ', 'Trong cách nói “别站在车那边”, 车 mang nghĩa “xe”.'),
    (1, 21, 'ngật', '吃 (ngật): ăn.', 'Động từ', 'Trong cách nói “你吃过这种鱼吗”, 吃 mang nghĩa “ăn”.'),
    (1, 22, 'xuyên', '穿 (xuyên): mặc, xỏ vào; xuyên qua.', 'Động từ', 'Trong cách nói “我常常穿这件蓝衬衫去上班”, 穿 mang nghĩa “mặc, mang”.'),
    (1, 23, 'xuất tô xa', '出 (xuất): ra, đi ra. 租 (tô): thuê, cho thuê. 车 (xa): xe, xe cộ.', 'Danh từ', 'Trong cách nói “那几个大学生坐出租车去公司修电脑”, 出租车 mang nghĩa “taxi”.'),
    (1, 24, 'đại', '大 (đại): to, lớn.', 'Tính từ', 'Trong cách nói “一千比一百大”, 大 mang nghĩa “to, lớn”.'),
    (1, 25, 'đả điện thoại', '打 (đả): đánh, làm, gọi (điện). 电 (điện): điện; điện lực. 话 (thoại): lời nói, câu nói.', 'Cụm động từ', 'Trong cách nói “儿子突然打电话来”, 打电话 mang nghĩa “gọi điện thoại”.'),
    (1, 26, 'đại gia', '大 (đại): to, lớn. 家 (gia): nhà, gia đình.', 'Đại từ', 'Trong cách nói “他的画很受大家喜爱”, 大家 mang nghĩa “mọi người”.'),
    (1, 27, 'đáo', '到 (đáo): đến, tới.', 'Động từ', 'Trong cách nói “我怎样才能照到天上的月亮”, 到 mang nghĩa “đến”.'),
    (1, 28, 'đại học', '大 (đại): to, lớn. 学 (học): học.', 'Danh từ', 'Trong cách nói “这所大学很大”, 大学 mang nghĩa “trường đại học”.'),
    (1, 29, 'đại học sinh', '大 (đại): to, lớn. 学 (học): học. 生 (sinh): sinh ra, nảy sinh; sống.', 'Danh từ', 'Trong cách nói “里面有很多大学生”, 大学生 mang nghĩa “sinh viên đại học”.'),
    (1, 30, 'đích', '的 (đích): của; trợ từ định ngữ.', 'Trợ từ', 'Đặt giữa thành phần bổ nghĩa và danh từ, hoặc sau người sở hữu.'),
    (1, 31, 'đệ', '第 (đệ): thứ (đánh số thứ tự).', 'Tiền tố', 'Đặt trước số đếm để tạo số thứ tự.'),
    (1, 32, 'điếm', '店 (điếm): cửa hàng, tiệm.', 'Danh từ', 'Trong cách nói “市中心有一家店”, 店 mang nghĩa “cửa hàng”.'),
    (1, 33, 'điểm', '点 (điểm): giờ; chấm điểm.', 'Lượng từ', 'Đặt sau số đếm để nói giờ trong ngày.'),
    (1, 34, 'điện thoại', '电 (điện): điện; điện lực. 话 (thoại): lời nói, câu nói.', 'Danh từ', 'Trong cách nói “请把电话号码写在黑板上”, 电话 mang nghĩa “điện thoại”.'),
    (1, 35, 'điện não', '电 (điện): điện; điện lực. 脑 (não): bộ não.', 'Danh từ', 'Trong cách nói “这是我第一次用电脑写汉字”, 电脑 mang nghĩa “máy tính”.'),
    (1, 36, 'điện thị', '电 (điện): điện; điện lực. 视 (thị): nhìn, xem; coi như, đối xử.', 'Danh từ', 'Trong cách nói “我正看电视”, 电视 mang nghĩa “truyền hình, tivi”.'),
    (1, 37, 'điện ảnh', '电 (điện): điện; điện lực. 影 (ảnh): bóng, hình bóng.', 'Danh từ', 'Trong cách nói “她们去看电影”, 电影 mang nghĩa “phim điện ảnh”.'),
    (1, 38, 'điện ảnh viện', '电 (điện): điện; điện lực. 影 (ảnh): bóng, hình bóng. 院 (viện): viện, sân; toà nhà công.', 'Danh từ', 'Trong cách nói “这里就是电影院”, 电影院 mang nghĩa “rạp chiếu phim”.'),
    (1, 39, 'đệ đệ', '弟 (đệ): em trai, em.', 'Danh từ', 'Trong cách nói “可是弟弟还在哭”, 弟弟 mang nghĩa “em trai”.'),
    (1, 40, 'đông tây', '东 (đông): phía đông. 西 (tây): phía tây.', 'Danh từ', 'Trong cách nói “两名学生帮奶奶拿东西”, 东西 mang nghĩa “đồ vật”.'),
    (1, 41, 'đô', '都 (đô): đều, tất cả; thủ đô.', 'Phó từ', 'Trong cách nói “树都开花了”, 都 mang nghĩa “đều”.'),
    (1, 42, 'độc', '读 (độc): đọc.', 'Động từ', 'Trong cách nói “老师让我们把笔记再读一遍”, 读 mang nghĩa “đọc”.'),
    (1, 43, 'đối', '对 (đối): đúng; đối với, đối diện.', 'Tính từ, Giới từ', 'Trong cách nói “这个答案是对的”, 对 mang nghĩa “đúng”.'),
    (1, 44, 'đối bất khởi', '对 (đối): đúng; đối với, đối diện. 不 (bất): không (phủ định). 起 (khởi): đứng dậy, nổi lên, khởi đầu.', 'Động từ', 'Trong cách nói “对不起”, 对不起 mang nghĩa “xin lỗi”.'),
    (1, 45, 'đa', '多 (đa): nhiều.', 'Tính từ, Động từ, Đại từ', 'Trong cách nói “医生说我要多休息”, 多 mang nghĩa “nhiều”.'),
    (1, 46, 'đa thiểu', '多 (đa): nhiều. 少 (thiểu): ít.', 'Đại từ', 'Trong cách nói “休假需要带多少行李”, 多少 mang nghĩa “bao nhiêu”.'),
    (1, 47, 'độc thư', '读 (độc): đọc. 书 (thư): sách, viết.', 'Động từ', 'Trong cách nói “我每天读书”, 读书 mang nghĩa “đọc sách”.'),
    (1, 48, 'nhị', '二 (nhị): hai, số 2.', 'Số từ', 'Trong cách nói “我们班有二十个人”, 二 mang nghĩa “hai”.'),
    (1, 49, 'nhi tử', '儿 (nhi): con trẻ; âm đuôi ''r''. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “儿子突然打电话来”, 儿子 mang nghĩa “con trai”.'),
    (1, 50, 'phạn', '饭 (phạn): cơm, bữa cơm.', 'Danh từ', 'Trong cách nói “饭好了”, 饭 mang nghĩa “cơm”.'),
    (1, 51, 'phạn điếm', '饭 (phạn): cơm, bữa cơm. 店 (điếm): cửa hàng, tiệm.', 'Danh từ', 'Trong cách nói “饭店在电影院那边”, 饭店 mang nghĩa “nhà hàng”.'),
    (1, 52, 'phòng gian', '房 (phòng): phòng, nhà. 间 (gian): gian, phòng; khoảng giữa.', 'Danh từ', 'Trong cách nói “让房间凉快一点儿”, 房间 mang nghĩa “phòng”.'),
    (1, 53, 'phi thường', '非 (phi): không phải; trái. 常 (thường): thường, hay; bình thường.', 'Phó từ', 'Trong cách nói “坐飞机非常快”, 非常 mang nghĩa “rất, vô cùng”.'),
    (1, 54, 'phi cơ', '飞 (phi): bay. 机 (cơ): máy móc; cơ hội.', 'Danh từ', 'Trong cách nói “飞机要起飞了”, 飞机 mang nghĩa “máy bay”.'),
    (1, 55, 'phân', '分 (phân): phút; chia ra.', 'Lượng từ', 'Khi nói giờ, đặt sau số phút và sau phần chỉ giờ.'),
    (1, 56, 'phân chung', '分 (phân): phút; chia ra. 钟 (chung): chuông; đồng hồ.', 'Lượng từ', 'Trong cách nói “还差七分钟”, 分钟 mang nghĩa “phút (khoảng thời gian)”.'),
    (1, 57, 'cao hứng', '高 (cao): cao. 兴 (hứng): hứng thú.', 'Tính từ', 'Trong cách nói “很高兴认识你”, 高兴 mang nghĩa “vui, vui mừng”.'),
    (1, 58, 'cá', '个 (cá): cái, chiếc (lượng từ).', 'Lượng từ', 'Đặt sau số hoặc từ chỉ định và trước danh từ.'),
    (1, 59, 'ca', '歌 (ca): bài hát, ca khúc.', 'Danh từ', 'Trong cách nói “姐姐喜欢唱中文歌”, 歌 mang nghĩa “bài hát”.'),
    (1, 60, 'ca ca', '哥 (ca): anh trai.', 'Danh từ', 'Trong cách nói “我的个子跟哥哥一样高”, 哥哥 mang nghĩa “anh trai”.'),
    (1, 61, 'cấp', '给 (cấp): cho, đưa cho.', 'Động từ', 'Trong cách nói “请给孩子讲一个故事”, 给 mang nghĩa “cho, đưa cho”.'),
    (1, 62, 'công ty', '公 (công): chung, công cộng. 司 (ty): cai quản, điều hành; cơ quan.', 'Danh từ', 'Trong cách nói “白天我在公司工作”, 公司 mang nghĩa “công ty”.'),
    (1, 63, 'công tác', '工 (công): công việc; thợ. 作 (tác): làm, tạo ra.', 'Động từ, Danh từ', 'Trong cách nói “你干什么工作”, 工作 mang nghĩa “làm việc”.'),
    (1, 64, 'cẩu', '狗 (cẩu): con chó.', 'Danh từ', 'Trong cách nói “我家的狗今年三岁了”, 狗 mang nghĩa “chó”.'),
    (1, 65, 'quý', '贵 (quý): đắt, mắc; quý giá.', 'Tính từ', 'Trong cách nói “这件比那件贵三块”, 贵 mang nghĩa “đắt”.'),
    (1, 66, 'quốc', '国 (quốc): nước, quốc gia.', 'Danh từ', 'Trong cách nói “你从哪国来”, 国 mang nghĩa “nước, quốc gia”.'),
    (1, 67, 'hoàn', '还 (hoàn): vẫn, còn; tạm được.', 'Phó từ', 'Trong cách nói “谁还没到”, 还 mang nghĩa “vẫn”.'),
    (1, 68, 'hài tử', '孩 (hài): trẻ con, đứa bé. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “请给孩子讲一个故事”, 孩子 mang nghĩa “trẻ em”.'),
    (1, 69, 'hán ngữ', '汉 (hán): Hán (tộc/sông Hán). 语 (ngữ): lời nói, ngôn ngữ.', 'Danh từ', 'Trong cách nói “假期里我也坚持每天练习汉语”, 汉语 mang nghĩa “tiếng Hán”.'),
    (1, 70, 'hán tự', '汉 (hán): Hán (tộc/sông Hán). 字 (tự): chữ, văn tự.', 'Danh từ', 'Trong cách nói “这是我第一次用电脑写汉字”, 汉字 mang nghĩa “chữ Hán”.'),
    (1, 71, 'hiệu', '号 (hiệu): số hiệu; hô gọi; ngày.', 'Danh từ, Lượng từ', 'Trong cách nói “星期天是几月几号”, 号 mang nghĩa “số”.'),
    (1, 72, 'hảo', '好 (hảo): tốt, đẹp, hay.', 'Tính từ', 'Trong cách nói “饭好了”, 好 mang nghĩa “tốt, khỏe”.'),
    (1, 73, 'hảo ngật', '好 (hảo): tốt, đẹp, hay. 吃 (ngật): ăn.', 'Tính từ', 'Trong cách nói “这些菜很好吃”, 好吃 mang nghĩa “ngon”.'),
    (1, 74, 'hảo khán', '好 (hảo): tốt, đẹp, hay. 看 (khán): nhìn, xem, coi.', 'Tính từ', 'Trong cách nói “这个汉字很好看”, 好看 mang nghĩa “đẹp”.'),
    (1, 75, 'hảo thính', '好 (hảo): tốt, đẹp, hay. 听 (thính): nghe.', 'Tính từ', 'Trong cách nói “弟弟在大学唱的那首中文歌真好听”, 好听 mang nghĩa “êm tai, nghe hay”.'),
    (1, 76, 'hảo ngoạn nhi', '好 (hảo): tốt, đẹp, hay. 玩 (ngoạn): chơi, đùa, thưởng ngoạn. 儿 (nhi): con trẻ; âm đuôi ''r''.', 'Tính từ', 'Trong cách nói “这个游戏好玩儿吗”, 好玩儿 mang nghĩa “thú vị, chơi vui”.'),
    (1, 77, 'hoà', '和 (hoà): và, với; hoà thuận.', 'Giới từ, Liên từ', 'Nối hai danh từ hoặc hai cụm danh từ ngang hàng.'),
    (1, 78, 'hát', '喝 (hát): uống.', 'Động từ', 'Trong cách nói “请坐下喝点儿水”, 喝 mang nghĩa “uống”.'),
    (1, 79, 'ngận', '很 (ngận): rất.', 'Phó từ', 'Trong cách nói “这瓶酒放了很久了”, 很 mang nghĩa “rất”.'),
    (1, 80, 'hậu', '后 (hậu): sau, phía sau.', 'Danh từ', 'Trong cách nói “检票后在车上见面吧”, 后 mang nghĩa “sau, phía sau”.'),
    (1, 81, 'hồi', '回 (hồi): quay lại, trở về.', 'Động từ', 'Trong cách nói “他出院后不久就回办公室上班了”, 回 mang nghĩa “trở về”.'),
    (1, 82, 'hội', '会 (hội): biết; họp; chốc lát.', 'Động từ', 'Đứng trước động từ khi nói về kỹ năng đã học.'),
    (1, 83, 'hoả xa', '火 (hoả): lửa. 车 (xa): xe, xe cộ.', 'Danh từ', 'Trong cách nói “火车晚点了”, 火车 mang nghĩa “tàu hỏa”.'),
    (1, 84, 'kỷ', '几 (kỷ): mấy, bao nhiêu.', 'Đại từ, Số từ', 'Trong cách nói “五月七号是星期几”, 几 mang nghĩa “mấy, bao nhiêu”.'),
    (1, 85, 'gia', '家 (gia): nhà, gia đình.', 'Danh từ, Lượng từ', 'Trong cách nói “去别人家做客”, 家 mang nghĩa “nhà, gia đình”.'),
    (1, 86, 'kiến', '见 (kiến): thấy, gặp.', 'Động từ', 'Trong cách nói “我们晚上七点见”, 见 mang nghĩa “gặp”.'),
    (1, 87, 'kiện', '件 (kiện): cái, chiếc; kiện (vật, việc).', 'Lượng từ', 'Đặt giữa số hoặc từ chỉ định và danh từ chỉ quần áo, sự việc.'),
    (1, 88, 'khiếu', '叫 (khiếu): gọi, kêu.', 'Động từ', 'Trong cách nói “我叫小安”, 叫 mang nghĩa “gọi”.'),
    (1, 89, 'giảo tử', '饺 (giảo): bánh nhân thịt hoặc rau. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “晚上也卖包子和饺子”, 饺子 mang nghĩa “há cảo, sủi cảo”.'),
    (1, 90, 'gia nhân', '家 (gia): nhà, gia đình. 人 (nhân): người.', 'Danh từ', 'Trong cách nói “而且认得我的家人”, 家人 mang nghĩa “người nhà”.'),
    (1, 91, 'kê đản', '鸡 (kê): con gà. 蛋 (đản): trứng.', 'Danh từ', 'Trong cách nói “爸爸买了八个包子和六个鸡蛋”, 鸡蛋 mang nghĩa “trứng gà”.'),
    (1, 92, 'tỉ tỉ', '姐 (tỉ): chị, chị gái.', 'Danh từ', 'Trong cách nói “我姐姐家有五口人”, 姐姐 mang nghĩa “chị gái”.'),
    (1, 93, 'kim niên', '今 (kim): nay, hiện tại. 年 (niên): năm.', 'Danh từ', 'Trong cách nói “我家的狗今年三岁了”, 今年 mang nghĩa “năm nay”.'),
    (1, 94, 'kim thiên', '今 (kim): nay, hiện tại. 天 (thiên): trời, bầu trời; ngày.', 'Danh từ', 'Trong cách nói “今天几月几日”, 今天 mang nghĩa “hôm nay”.'),
    (1, 95, 'cửu', '九 (cửu): chín, số 9.', 'Số từ', 'Trong cách nói “现在是九点半”, 九 mang nghĩa “chín”.'),
    (1, 96, 'giác đắc', '觉 (giác): cảm thấy. 得 (đắc): được, đạt được; (trợ từ bổ ngữ).', 'Động từ', 'Trong cách nói “今天觉得好些了”, 觉得 mang nghĩa “cảm thấy, cho rằng”.'),
    (1, 97, 'khai', '开 (khai): mở, khai mở; lái xe.', 'Động từ', 'Trong cách nói “我开门”, 开 mang nghĩa “mở”.'),
    (1, 98, 'khai xa', '开 (khai): mở, khai mở; lái xe. 车 (xa): xe, xe cộ.', 'Động từ', 'Trong cách nói “我会开车”, 开车 mang nghĩa “lái xe”.'),
    (1, 99, 'khán', '看 (khán): nhìn, xem, coi.', 'Động từ', 'Trong cách nói “你愿意陪我去看月亮吗”, 看 mang nghĩa “nhìn, xem, đọc”.'),
    (1, 100, 'khán bệnh', '看 (khán): nhìn, xem, coi. 病 (bệnh): bệnh, ốm đau.', 'Động từ', 'Trong cách nói “明天再去看病吧”, 看病 mang nghĩa “khám bệnh, đi khám”.'),
    (1, 101, 'khán kiến', '看 (khán): nhìn, xem, coi. 见 (kiến): thấy, gặp.', 'Động từ', 'Trong cách nói “我一出门就看见了她”, 看见 mang nghĩa “nhìn thấy”.'),
    (1, 102, 'khoá', '课 (khoá): bài học, tiết học.', 'Danh từ', 'Trong cách nói “这个学期你想选哪门课”, 课 mang nghĩa “bài học”.'),
    (1, 103, 'khả dĩ', '可 (khả): có thể, được; đáng. 以 (dĩ): lấy, dùng; theo.', 'Động từ, Tính từ', 'Trong cách nói “可以请你帮忙吗”, 可以 mang nghĩa “có thể, được phép”.'),
    (1, 104, 'khẩu', '口 (khẩu): miệng; cửa, lối ra vào.', 'Danh từ, Lượng từ', 'Đứng sau số đếm để nói số thành viên trong gia đình.'),
    (1, 105, 'khối', '块 (khối): cục, miếng, đồng.', 'Lượng từ', 'Trong cách nói “这件比那件贵三块”, 块 mang nghĩa “miếng”.'),
    (1, 106, 'lai', '来 (lai): đến, tới.', 'Động từ', 'Trong cách nói “春天来了”, 来 mang nghĩa “đến, tới”.'),
    (1, 107, 'lão sư', '老 (lão): già, lớn tuổi; kính ngữ. 师 (sư): thầy, bậc thầy.', 'Danh từ', 'Trong cách nói “老师在等你”, 老师 mang nghĩa “giáo viên”.'),
    (1, 108, 'liễu', '了 (liễu): thông suốt, xong; (trợ từ: le).', 'Trợ từ', 'Đứng sau động từ để biểu thị việc hoàn tất hoặc cuối câu để báo một tình huống mới.'),
    (1, 109, 'lãnh', '冷 (lãnh): lạnh, rét.', 'Tính từ', 'Trong cách nói “外边很冷”, 冷 mang nghĩa “lạnh”.'),
    (1, 110, 'lý', '里 (lý): bên trong; làng, dặm.', 'Danh từ', 'Trong cách nói “我相信箱子里还有香蕉”, 里 mang nghĩa “trong, bên trong”.'),
    (1, 111, 'lưỡng', '两 (lưỡng): hai.', 'Số từ', 'Trong cách nói “刚才我根据价格选了两公斤苹果”, 两 mang nghĩa “hai (thường dùng trước lượng từ)”.'),
    (1, 112, 'linh', '零 (linh): số không; lẻ, vụn.', 'Số từ', 'Trong cách nói “一百减一百是零”, 零 mang nghĩa “số không”.'),
    (1, 113, 'lục', '六 (lục): sáu, số 6.', 'Số từ', 'Trong cách nói “六月二日是我的生日”, 六 mang nghĩa “sáu”.'),
    (1, 114, 'mạ', '吗 (mạ): trợ từ nghi vấn.', 'Trợ từ', 'Đặt cuối câu trần thuật để tạo câu hỏi có hoặc không.'),
    (1, 115, 'mại', '卖 (mại): bán.', 'Động từ', 'Trong cách nói “那家店卖很多帽子”, 卖 mang nghĩa “bán”.'),
    (1, 116, 'mãi', '买 (mãi): mua.', 'Động từ', 'Trong cách nói “这个星期我买了一些新书”, 买 mang nghĩa “mua”.'),
    (1, 117, 'ma ma', '妈 (ma): mẹ.', 'Danh từ', 'Trong cách nói “也爱妈妈”, 妈妈 mang nghĩa “mẹ”.'),
    (1, 118, 'mang', '忙 (mang): bận, bận rộn.', 'Tính từ, Động từ', 'Trong cách nói “每天都很忙”, 忙 mang nghĩa “bận”.'),
    (1, 119, 'miêu', '猫 (miêu): con mèo.', 'Danh từ', 'Trong cách nói “它是我家的猫”, 猫 mang nghĩa “mèo”.'),
    (1, 120, 'một quan hệ', '没 (một): không có; chìm mất. 关 (quan): đóng (cửa); liên quan. 系 (hệ): buộc, cột; hệ thống; quan hệ.', 'Cụm từ', 'Trong cách nói “没关系”, 没关系 mang nghĩa “không sao (đáp lời xin lỗi)”.'),
    (1, 121, 'muội muội', '妹 (muội): em gái.', 'Danh từ', 'Trong cách nói “妹妹想吃米饭”, 妹妹 mang nghĩa “em gái”.'),
    (1, 122, 'một sự', '没 (một): không có; chìm mất. 事 (sự): việc, sự việc.', 'Động từ', 'Trong cách nói “医生说我已经没事了”, 没事 mang nghĩa “không có việc gì”.'),
    (1, 123, 'một hữu', '没 (một): không có; chìm mất. 有 (hữu): có, sở hữu.', 'Động từ, phó từ', 'Dùng 没 hoặc 没有 trước động từ để phủ định việc đã xảy ra. 没有 cũng có nghĩa là không có.'),
    (1, 124, 'môn', '们 (môn): (đuôi số nhiều).', 'Hậu tố', 'Gắn sau đại từ hoặc danh từ chỉ người để tạo số nhiều.'),
    (1, 125, 'diện bao', '面 (diện): mặt, bề mặt. 包 (bao): túi, cặp; bao bọc.', 'Danh từ', 'Trong cách nói “不想吃面包和面条儿”, 面包 mang nghĩa “bánh mì”.'),
    (1, 126, 'diện điều nhi', '面 (diện): mặt, bề mặt. 条 (điều): nhánh, dải dài; điều khoản; lượng từ vật dài. 儿 (nhi): con trẻ; âm đuôi ''r''.', 'Danh từ', 'Trong cách nói “不想吃面包和面条儿”, 面条儿 mang nghĩa “mì sợi”.'),
    (1, 127, 'mễ phạn', '米 (mễ): gạo; mét. 饭 (phạn): cơm, bữa cơm.', 'Danh từ', 'Trong cách nói “我想点一份米饭”, 米饭 mang nghĩa “cơm trắng”.'),
    (1, 128, 'minh niên', '明 (minh): sáng, rõ ràng, thông suốt. 年 (niên): năm.', 'Danh từ', 'Trong cách nói “明年想去上海”, 明年 mang nghĩa “năm sau”.'),
    (1, 129, 'minh thiên', '明 (minh): sáng, rõ ràng, thông suốt. 天 (thiên): trời, bầu trời; ngày.', 'Danh từ', 'Trong cách nói “明天我把信带来”, 明天 mang nghĩa “ngày mai”.'),
    (1, 130, 'danh tự', '名 (danh): tên gọi, danh tiếng. 字 (tự): chữ, văn tự.', 'Danh từ', 'Trong cách nói “这条街的名字好记”, 名字 mang nghĩa “tên”.'),
    (1, 131, 'na', '那 (na): kia, đó.', 'Đại từ', 'Trong cách nói “这封信是那对夫妻写给邻居的”, 那 mang nghĩa “kia, đó”.'),
    (1, 132, 'na', '哪 (na): nào, đâu (nghi vấn).', 'Đại từ', 'Trong cách nói “你在哪所高中读书”, 哪 mang nghĩa “nào”.'),
    (1, 133, 'na biên', '那 (na): kia, đó. 边 (biên): bên, cạnh, rìa.', 'Đại từ', 'Trong cách nói “别站在车那边”, 那边 mang nghĩa “bên kia”.'),
    (1, 134, 'na cá', '那 (na): kia, đó. 个 (cá): cái, chiếc (lượng từ).', 'Đại từ', 'Trong cách nói “那个男的是我的男朋友”, 那个 mang nghĩa “cái kia”.'),
    (1, 135, 'na cá', '哪 (na): nào, đâu (nghi vấn). 个 (cá): cái, chiếc (lượng từ).', 'Đại từ', 'Trong cách nói “你想看哪个”, 哪个 mang nghĩa “cái nào”.'),
    (1, 136, 'na lý', '那 (na): kia, đó. 里 (lý): bên trong; làng, dặm.', 'Đại từ', 'Trong cách nói “我就住在那里”, 那里 mang nghĩa “chỗ đó”.'),
    (1, 137, 'na lý', '哪 (na): nào, đâu (nghi vấn). 里 (lý): bên trong; làng, dặm.', 'Đại từ', 'Trong cách nói “你住在哪里”, 哪里 mang nghĩa “ở đâu”.'),
    (1, 138, 'nam', '男 (nam): nam giới, con trai.', 'Tính từ', 'Trong cách nói “那个男的是我的男朋友”, 男 mang nghĩa “nam, đàn ông”.'),
    (1, 139, 'nam bằng hữu', '男 (nam): nam giới, con trai. 朋 (bằng): bạn bè, bè bạn. 友 (hữu): bạn, thân thiết.', 'Danh từ', 'Trong cách nói “那个男的是我的男朋友”, 男朋友 mang nghĩa “bạn trai”.'),
    (1, 140, 'na nhi', '那 (na): kia, đó. 儿 (nhi): con trẻ; âm đuôi ''r''.', 'Đại từ', 'Trong cách nói “那儿离这儿远吗”, 那儿 mang nghĩa “chỗ kia”.'),
    (1, 141, 'na nhi', '哪 (na): nào, đâu (nghi vấn). 儿 (nhi): con trẻ; âm đuôi ''r''.', 'Đại từ', 'Trong cách nói “你要去哪儿”, 哪儿 mang nghĩa “chỗ nào, ở đâu”.'),
    (1, 142, 'na ta', '那 (na): kia, đó. 些 (ta): vài, một ít.', 'Đại từ', 'Trong cách nói “那些人是你们的同学吗”, 那些 mang nghĩa “những cái kia”.'),
    (1, 143, 'na ta', '哪 (na): nào, đâu (nghi vấn). 些 (ta): vài, một ít.', 'Đại từ', 'Trong cách nói “哪些书是你的”, 哪些 mang nghĩa “những cái nào”.'),
    (1, 144, 'ni', '呢 (ni): trợ từ ngữ khí (hỏi lại / tiếp diễn).', 'Trợ từ', 'Đặt cuối một câu hỏi rút gọn khi hỏi lại về người hoặc sự vật khác.'),
    (1, 145, 'năng', '能 (năng): có thể, được; năng lực.', 'Động từ', 'Trong cách nói “你能听见我说话吗”, 能 mang nghĩa “có thể, có khả năng”.'),
    (1, 146, 'nhĩ', '你 (nhĩ): bạn (ngôi thứ hai).', 'Đại từ', 'Trong cách nói “你从哪国来”, 你 mang nghĩa “bạn (ngôi thứ hai)”.'),
    (1, 148, 'niên', '年 (niên): năm.', 'Danh từ, Lượng từ', 'Trong cách nói “后年还要办画展”, 年 mang nghĩa “năm”.'),
    (1, 149, 'nhĩ môn', '你 (nhĩ): bạn (ngôi thứ hai). 们 (môn): (đuôi số nhiều).', 'Đại từ', 'Trong cách nói “那些人是你们的同学吗”, 你们 mang nghĩa “các bạn”.'),
    (1, 150, 'nâm', '您 (nâm): ngài (bạn - kính ngữ).', 'Đại từ', 'Trong cách nói “您几点下班”, 您 mang nghĩa “ông, bà, anh, chị (cách gọi lịch sự)”.'),
    (1, 151, 'ngưu nãi', '牛 (ngưu): con bò, con trâu. 奶 (nãi): sữa; bà.', 'Danh từ', 'Trong cách nói “牛奶要放在哪里”, 牛奶 mang nghĩa “sữa bò”.'),
    (1, 152, 'nữ', '女 (nữ): nữ, phụ nữ, con gái.', 'Tính từ', 'Trong cách nói “那个女人怕高”, 女 mang nghĩa “nữ, phụ nữ”.'),
    (1, 153, 'nữ nhi', '女 (nữ): nữ, phụ nữ, con gái. 儿 (nhi): con trẻ; âm đuôi ''r''.', 'Danh từ', 'Trong cách nói “女儿正在做饭”, 女儿 mang nghĩa “con gái”.'),
    (1, 154, 'nữ bằng hữu', '女 (nữ): nữ, phụ nữ, con gái. 朋 (bằng): bạn bè, bè bạn. 友 (hữu): bạn, thân thiết.', 'Danh từ', 'Trong cách nói “那位女士是我朋友的女朋友”, 女朋友 mang nghĩa “bạn gái”.'),
    (1, 155, 'nữ sĩ', '女 (nữ): nữ, phụ nữ, con gái. 士 (sĩ): người có học; người.', 'Danh từ', 'Trong cách nói “那位女士是我朋友的女朋友”, 女士 mang nghĩa “quý bà, quý cô”.'),
    (1, 156, 'bằng hữu', '朋 (bằng): bạn bè, bè bạn. 友 (hữu): bạn, thân thiết.', 'Danh từ', 'Trong cách nói “那位女士是我朋友的女朋友”, 朋友 mang nghĩa “bạn bè”.'),
    (1, 157, 'tiện nghi', '便 (tiện): trong 便宜: rẻ. 宜 (nghi): thích hợp, nên.', 'Tính từ', 'Trong cách nói “白色的包比黑色的包便宜”, 便宜 mang nghĩa “rẻ”.'),
    (1, 158, 'phiêu lượng', '漂 (phiêu): trôi nổi; (trong 漂亮 - đẹp). 亮 (lượng): sáng, sáng sủa.', 'Tính từ', 'Trong cách nói “这件女式上衣颜色真漂亮”, 漂亮 mang nghĩa “xinh đẹp”.'),
    (1, 159, 'bình quả', '苹 (bình): (trong 苹果 - táo). 果 (quả): quả, trái cây; kết quả.', 'Danh từ', 'Trong cách nói “一个苹果多少钱”, 苹果 mang nghĩa “quả táo”.'),
    (1, 160, 'thất', '七 (thất): bảy, số 7.', 'Số từ', 'Trong cách nói “五月七号是星期几”, 七 mang nghĩa “bảy”.'),
    (1, 161, 'tiền', '前 (tiền): phía trước; trước đây.', 'Danh từ', 'Trong cách nói “早上起床前”, 前 mang nghĩa “trước, phía trước”.'),
    (1, 162, 'tiền', '钱 (tiền): tiền.', 'Danh từ', 'Trong cách nói “一个苹果多少钱”, 钱 mang nghĩa “tiền”.'),
    (1, 163, 'thiên', '千 (thiên): nghìn.', 'Số từ', 'Trong cách nói “一千比一百大”, 千 mang nghĩa “nghìn”.'),
    (1, 164, 'khởi sàng', '起 (khởi): đứng dậy, nổi lên, khởi đầu. 床 (sàng): cái giường.', 'Động từ', 'Trong cách nói “早上起床前”, 起床 mang nghĩa “thức dậy, ra khỏi giường”.'),
    (1, 165, 'thỉnh', '请 (thỉnh): mời, xin (lịch sự).', 'Động từ', 'Trong cách nói “请坐在椅子上等一下”, 请 mang nghĩa “mời”.'),
    (1, 166, 'thỉnh vấn', '请 (thỉnh): mời, xin (lịch sự). 问 (vấn): hỏi, hỏi han.', 'Động từ', 'Trong cách nói “请问”, 请问 mang nghĩa “xin hỏi”.'),
    (1, 167, 'khứ', '去 (khứ): đi, đi đến.', 'Động từ', 'Trong cách nói “我先去吃早饭”, 去 mang nghĩa “đi”.'),
    (1, 168, 'khứ niên', '去 (khứ): đi, đi đến. 年 (niên): năm.', 'Danh từ', 'Trong cách nói “去年我住在北京”, 去年 mang nghĩa “năm ngoái”.'),
    (1, 169, 'nhiệt', '热 (nhiệt): nóng, nhiệt.', 'Tính từ', 'Trong cách nói “天气很热”, 热 mang nghĩa “nóng”.'),
    (1, 170, 'nhân', '人 (nhân): người.', 'Danh từ', 'Trong cách nói “我姐姐家有五口人”, 人 mang nghĩa “người”.'),
    (1, 171, 'nhận thức', '认 (nhận): nhận ra, nhận biết; thừa nhận. 识 (thức): biết, hiểu rõ.', 'Động từ', 'Trong cách nói “很高兴认识你”, 认识 mang nghĩa “quen biết, nhận biết”.'),
    (1, 172, 'nhật', '日 (nhật): ngày; mặt trời.', 'Lượng từ', 'Trong cách nói “今天几月几日”, 日 mang nghĩa “ngày”.'),
    (1, 173, 'tam', '三 (tam): ba (số 3).', 'Số từ', 'Trong cách nói “这件比那件贵三块”, 三 mang nghĩa “ba”.'),
    (1, 174, 'thượng', '上 (thượng): trên; lên.', 'Danh từ, Động từ', 'Trong cách nói “请坐在椅子上等一下”, 上 mang nghĩa “trên”.'),
    (1, 175, 'thượng ban', '上 (thượng): trên; lên. 班 (ban): tổ, lớp; ca làm.', 'Động từ', 'Trong cách nói “上午妈妈去上班”, 上班 mang nghĩa “đi làm”.'),
    (1, 176, 'thương điếm', '商 (thương): buôn bán, thương mại. 店 (điếm): cửa hàng, tiệm.', 'Danh từ', 'Trong cách nói “妈妈在商店卖水果”, 商店 mang nghĩa “cửa hàng”.'),
    (1, 177, 'thượng khoá', '上 (thượng): trên; lên. 课 (khoá): bài học, tiết học.', 'Động từ', 'Trong cách nói “我去上课”, 上课 mang nghĩa “vào học”.'),
    (1, 178, 'thượng ngọ', '上 (thượng): trên; lên. 午 (ngọ): giờ Ngọ, buổi trưa.', 'Danh từ', 'Trong cách nói “上午妈妈去上班”, 上午 mang nghĩa “buổi sáng”.'),
    (1, 179, 'thượng học', '上 (thượng): trên; lên. 学 (học): học.', 'Động từ', 'Trong cách nói “今天不要去上学”, 上学 mang nghĩa “đi học”.'),
    (1, 180, 'thiểu', '少 (thiểu): ít.', 'Tính từ, Động từ', 'Trong cách nói “少吃一点儿”, 少 mang nghĩa “ít”.'),
    (1, 181, 'thuỳ', '谁 (thuỳ): ai (nghi vấn).', 'Đại từ', 'Trong cách nói “你找谁”, 谁 mang nghĩa “ai”.'),
    (1, 182, 'sinh bệnh', '生 (sinh): sinh ra, nảy sinh; sống. 病 (bệnh): bệnh, ốm đau.', 'Động từ', 'Trong cách nói “孩子生病了”, 生病 mang nghĩa “bị ốm”.'),
    (1, 183, 'thập ma', '什 (thập): cái gì (trong 什么). 么 (ma): trợ từ (trong 怎么, 什么).', 'Đại từ', 'Trong cách nói “你姓什么”, 什么 mang nghĩa “cái gì”.'),
    (1, 184, 'thập', '十 (thập): mười; trọn vẹn.', 'Số từ', 'Trong cách nói “我们班有二十个人”, 十 mang nghĩa “mười”.'),
    (1, 185, 'sự', '事 (sự): việc, sự việc.', 'Danh từ', 'Trong cách nói “其实其他人都知道这件事”, 事 mang nghĩa “việc, chuyện”.'),
    (1, 186, 'thị', '是 (thị): là, đúng, phải.', 'Động từ', 'Trong cách nói “这个答案是对的”, 是 mang nghĩa “là”.'),
    (1, 187, 'thời hậu', '时 (thời): thời gian, giờ, khi. 候 (hậu): chờ đợi; thời tiết.', 'Danh từ', 'Trong cách nói “头疼的时候”, 时候 mang nghĩa “lúc, khi”.'),
    (1, 188, 'thời gian', '时 (thời): thời gian, giờ, khi. 间 (gian): gian, phòng; khoảng giữa.', 'Danh từ', 'Trong cách nói “请记好时间”, 时间 mang nghĩa “thời gian”.'),
    (1, 189, 'thủ cơ', '手 (thủ): tay, bàn tay. 机 (cơ): máy móc; cơ hội.', 'Danh từ', 'Trong cách nói “别一直看手机”, 手机 mang nghĩa “điện thoại di động”.'),
    (1, 190, 'thư', '书 (thư): sách, viết.', 'Danh từ', 'Trong cách nói “请把借来的书还给同学”, 书 mang nghĩa “sách”.'),
    (1, 191, 'thư điếm', '书 (thư): sách, viết. 店 (điếm): cửa hàng, tiệm.', 'Danh từ', 'Trong cách nói “超市在书店旁边”, 书店 mang nghĩa “hiệu sách”.'),
    (1, 192, 'thuỵ', '睡 (thuỵ): ngủ.', 'Động từ', 'Dùng độc lập hoặc kèm bổ ngữ thời lượng để nói về việc ngủ.'),
    (1, 193, 'thuỷ', '水 (thuỷ): nước.', 'Danh từ', 'Trong cách nói “请坐下喝点儿水”, 水 mang nghĩa “nước”.'),
    (1, 194, 'thuỷ quả', '水 (thuỷ): nước. 果 (quả): quả, trái cây; kết quả.', 'Danh từ', 'Trong cách nói “妈妈在商店卖水果”, 水果 mang nghĩa “trái cây”.'),
    (1, 195, 'thuỵ giác', '睡 (thuỵ): ngủ. 觉 (giác): giấc ngủ.', 'Động từ', 'Trong cách nói “睡觉的时候”, 睡觉 mang nghĩa “ngủ, đi ngủ”.'),
    (1, 196, 'thuyết', '说 (thuyết): nói, nói chuyện.', 'Động từ', 'Trong cách nói “医生说我要多休息”, 说 mang nghĩa “nói”.'),
    (1, 197, 'thuyết thoại', '说 (thuyết): nói, nói chuyện. 话 (thoại): lời nói, câu nói.', 'Động từ', 'Trong cách nói “你能听见我说话吗”, 说话 mang nghĩa “nói chuyện”.'),
    (1, 198, 'tứ', '四 (tứ): bốn, số 4.', 'Số từ', 'Trong cách nói “四千米是四公里”, 四 mang nghĩa “bốn”.'),
    (1, 199, 'tuế', '岁 (tuế): tuổi, năm tuổi.', 'Lượng từ', 'Đặt sau số để nói tuổi.'),
    (1, 200, 'tha', '他 (tha): anh ấy; cái khác.', 'Đại từ', 'Trong cách nói “他比我差两分”, 他 mang nghĩa “anh ấy, ông ấy”.'),
    (1, 201, 'tha', '它 (tha): nó (chỉ vật/con vật).', 'Đại từ', 'Trong cách nói “它是我家的猫”, 它 mang nghĩa “nó (đồ vật, con vật)”.'),
    (1, 202, 'tha', '她 (tha): cô ấy (ngôi thứ ba, nữ).', 'Đại từ', 'Trong cách nói “我一出门就看见了她”, 她 mang nghĩa “cô ấy, bà ấy”.'),
    (1, 203, 'thái', '太 (thái): quá, rất; to lớn.', 'Phó từ', 'Trong cách nói “这张桌子太大”, 太 mang nghĩa “quá, quá mức”.'),
    (1, 204, 'tha môn', '他 (tha): anh ấy; cái khác. 们 (môn): (đuôi số nhiều).', 'Đại từ', 'Trong cách nói “他们去买书”, 他们 mang nghĩa “họ”.'),
    (1, 205, 'tha môn', '它 (tha): nó (chỉ vật/con vật). 们 (môn): (đuôi số nhiều).', 'Đại từ', 'Trong cách nói “要求我们别吓着它们”, 它们 mang nghĩa “chúng (đồ vật, con vật)”.'),
    (1, 206, 'tha môn', '她 (tha): cô ấy (ngôi thứ ba, nữ). 们 (môn): (đuôi số nhiều).', 'Đại từ', 'Trong cách nói “她们去看电影”, 她们 mang nghĩa “họ (nhóm nữ)”.'),
    (1, 207, 'thiên', '天 (thiên): trời, bầu trời; ngày.', 'Danh từ, Lượng từ', 'Trong cách nói “她病了两天”, 天 mang nghĩa “ngày”.'),
    (1, 208, 'thiên khí', '天 (thiên): trời, bầu trời; ngày. 气 (khí): hơi, khí; giận.', 'Danh từ', 'Trong cách nói “天气热得她的脸都红了”, 天气 mang nghĩa “thời tiết”.'),
    (1, 209, 'thính', '听 (thính): nghe.', 'Động từ', 'Trong cách nói “听完解释”, 听 mang nghĩa “nghe”.'),
    (1, 210, 'thính kiến', '听 (thính): nghe. 见 (kiến): thấy, gặp.', 'Động từ', 'Trong cách nói “你能听见我说话吗”, 听见 mang nghĩa “nghe thấy”.'),
    (1, 211, 'đồng học', '同 (đồng): cùng, giống nhau. 学 (học): học.', 'Danh từ', 'Trong cách nói “那些人是你们的同学吗”, 同学 mang nghĩa “bạn học”.'),
    (1, 212, 'ngoại', '外 (ngoại): ngoài, bên ngoài.', 'Danh từ', 'Trong cách nói “外面在刮风”, 外 mang nghĩa “ngoài”.'),
    (1, 213, 'ngoại biên', '外 (ngoại): ngoài, bên ngoài. 边 (biên): bên, cạnh, rìa.', 'Danh từ', 'Trong cách nói “外边很冷”, 外边 mang nghĩa “bên ngoài”.'),
    (1, 214, 'ngoạn', '玩 (ngoạn): chơi, đùa, thưởng ngoạn.', 'Động từ', 'Trong cách nói “我们可以在门外玩一会儿”, 玩 mang nghĩa “chơi”.'),
    (1, 215, 'vãn', '晚 (vãn): muộn, tối; buổi tối.', 'Tính từ', 'Trong cách nói “别来晚了”, 晚 mang nghĩa “muộn”.'),
    (1, 216, 'vãn phạn', '晚 (vãn): muộn, tối; buổi tối. 饭 (phạn): cơm, bữa cơm.', 'Danh từ', 'Trong cách nói “晚饭吃得太晚了”, 晚饭 mang nghĩa “bữa tối”.'),
    (1, 217, 'vãn thượng', '晚 (vãn): muộn, tối; buổi tối. 上 (thượng): trên; lên.', 'Danh từ', 'Trong cách nói “晚上上网太久对身体不好”, 晚上 mang nghĩa “buổi tối”.'),
    (1, 218, 'uý', '喂 (uý): a-lô; này.', 'Thán từ', 'Dùng khi nhấc điện thoại hoặc gọi để thu hút sự chú ý.'),
    (1, 219, 'vấn', '问 (vấn): hỏi, hỏi han.', 'Động từ', 'Trong cách nói “我有事想问你”, 问 mang nghĩa “hỏi”.'),
    (1, 220, 'vấn đề', '问 (vấn): hỏi, hỏi han. 题 (đề): đề bài, câu hỏi.', 'Danh từ', 'Trong cách nói “请问您有什么问题”, 问题 mang nghĩa “câu hỏi”.'),
    (1, 221, 'ngã', '我 (ngã): tôi.', 'Đại từ', 'Trong cách nói “他比我差两分”, 我 mang nghĩa “tôi”.'),
    (1, 222, 'ngã môn', '我 (ngã): tôi. 们 (môn): (đuôi số nhiều).', 'Đại từ', 'Trong cách nói “我们决定周五开会”, 我们 mang nghĩa “chúng tôi, chúng ta”.'),
    (1, 223, 'ngũ', '五 (ngũ): năm, số 5.', 'Số từ', 'Trong cách nói “我们决定周五开会”, 五 mang nghĩa “năm (số đếm)”.'),
    (1, 224, 'ngọ phạn', '午 (ngọ): giờ Ngọ, buổi trưa. 饭 (phạn): cơm, bữa cơm.', 'Danh từ', 'Trong cách nói “午饭后我喝水”, 午饭 mang nghĩa “bữa trưa”.'),
    (1, 225, 'hạ', '下 (hạ): dưới, xuống.', 'Danh từ, Động từ, Lượng từ', 'Trong cách nói “在下一站停”, 下 mang nghĩa “dưới”.'),
    (1, 226, 'hạ vũ', '下 (hạ): dưới, xuống. 雨 (vũ): mưa.', 'Cụm từ', 'Trong cách nói “下雨了”, 下雨 mang nghĩa “mưa (trời mưa)”.'),
    (1, 227, 'hạ ban', '下 (hạ): dưới, xuống. 班 (ban): tổ, lớp; ca làm.', 'Động từ', 'Trong cách nói “您几点下班”, 下班 mang nghĩa “tan làm”.'),
    (1, 228, 'hạ khoá', '下 (hạ): dưới, xuống. 课 (khoá): bài học, tiết học.', 'Động từ', 'Trong cách nói “下课以后我坐车回家”, 下课 mang nghĩa “tan học, hết tiết”.'),
    (1, 229, 'tưởng', '想 (tưởng): muốn, nghĩ, nhớ.', 'Động từ', 'Trong cách nói “我想去”, 想 mang nghĩa “muốn”.'),
    (1, 230, 'tiên sinh', '先 (tiên): trước, đầu tiên. 生 (sinh): sinh ra, nảy sinh; sống.', 'Danh từ', 'Trong cách nói “先生”, 先生 mang nghĩa “ông, ngài”.'),
    (1, 231, 'hiện tại', '现 (hiện): hiện ra; hiện tại. 在 (tại): ở, tại; đang.', 'Danh từ', 'Trong cách nói “现在是九点半”, 现在 mang nghĩa “bây giờ”.'),
    (1, 232, 'tiểu', '小 (tiểu): nhỏ, bé.', 'Tính từ, Tiền tố', 'Trong cách nói “她比我小三岁”, 小 mang nghĩa “nhỏ, bé”.'),
    (1, 233, 'tiểu bằng hữu', '小 (tiểu): nhỏ, bé. 朋 (bằng): bạn bè, bè bạn. 友 (hữu): bạn, thân thiết.', 'Danh từ', 'Trong cách nói “小朋友每天学习两个小时”, 小朋友 mang nghĩa “bạn nhỏ, trẻ nhỏ”.'),
    (1, 234, 'tiểu thời', '小 (tiểu): nhỏ, bé. 时 (thời): thời gian, giờ, khi.', 'Danh từ', 'Trong cách nói “小朋友每天学习两个小时”, 小时 mang nghĩa “giờ (khoảng thời gian)”.'),
    (1, 235, 'tiểu học', '小 (tiểu): nhỏ, bé. 学 (học): học.', 'Danh từ', 'Trong cách nói “这所小学的小学生正在学写字”, 小学 mang nghĩa “trường tiểu học”.'),
    (1, 236, 'tiểu học sinh', '小 (tiểu): nhỏ, bé. 学 (học): học. 生 (sinh): sinh ra, nảy sinh; sống.', 'Danh từ', 'Trong cách nói “这所小学的小学生正在学写字”, 小学生 mang nghĩa “học sinh tiểu học”.'),
    (1, 237, 'hạ ngọ', '下 (hạ): dưới, xuống. 午 (ngọ): giờ Ngọ, buổi trưa.', 'Danh từ', 'Trong cách nói “下午有个会”, 下午 mang nghĩa “buổi chiều”.'),
    (1, 238, 'tả', '写 (tả): viết.', 'Động từ', 'Trong cách nói “请把电话号码写在黑板上”, 写 mang nghĩa “viết”.'),
    (1, 239, 'ta', '些 (ta): vài, một ít.', 'Lượng từ', 'Trong cách nói “那些人是你们的同学吗”, 些 mang nghĩa “một số, vài”.'),
    (1, 240, 'tạ tạ', '谢 (tạ): cảm tạ, cảm ơn.', 'Động từ', 'Trong cách nói “谢谢”, 谢谢 mang nghĩa “cảm ơn”.'),
    (1, 241, 'hỉ hoan', '喜 (hỉ): vui mừng, thích. 欢 (hoan): vui mừng, hân hoan.', 'Động từ', 'Trong cách nói “我喜欢看海”, 喜欢 mang nghĩa “thích”.'),
    (1, 242, 'tân', '新 (tân): mới, mới mẻ.', 'Tính từ', 'Trong cách nói “我给你介绍一下新同事”, 新 mang nghĩa “mới”.'),
    (1, 243, 'tinh kỳ', '星 (tinh): ngôi sao. 期 (kỳ): kỳ hạn, thời kỳ.', 'Danh từ', 'Trong cách nói “五月七号是星期几”, 星期 mang nghĩa “tuần”.'),
    (1, 244, 'tinh kỳ nhật', '星 (tinh): ngôi sao. 期 (kỳ): kỳ hạn, thời kỳ. 日 (nhật): ngày; mặt trời.', 'Danh từ', 'Trong cách nói “星期日学校放假”, 星期日 mang nghĩa “Chủ nhật”.'),
    (1, 245, 'tinh kỳ thiên', '星 (tinh): ngôi sao. 期 (kỳ): kỳ hạn, thời kỳ. 天 (thiên): trời, bầu trời; ngày.', 'Danh từ', 'Trong cách nói “星期天是几月几号”, 星期天 mang nghĩa “Chủ nhật”.'),
    (1, 246, 'hưu tức', '休 (hưu): nghỉ, ngừng. 息 (tức): thở; ngừng nghỉ; tin tức.', 'Động từ', 'Trong cách nói “医生说我要多休息”, 休息 mang nghĩa “nghỉ ngơi”.'),
    (1, 247, 'học', '学 (học): học.', 'Động từ', 'Trong cách nói “这所小学的小学生正在学写字”, 学 mang nghĩa “học”.'),
    (1, 248, 'tuyết', '雪 (tuyết): tuyết.', 'Danh từ', 'Trong cách nói “门外有雪”, 雪 mang nghĩa “tuyết”.'),
    (1, 249, 'học sinh', '学 (học): học. 生 (sinh): sinh ra, nảy sinh; sống.', 'Danh từ', 'Trong cách nói “两名学生帮奶奶拿东西”, 学生 mang nghĩa “học sinh, sinh viên”.'),
    (1, 250, 'học tập', '学 (học): học. 习 (tập): luyện tập, quen.', 'Động từ', 'Trong cách nói “睡得太少会影响学习”, 学习 mang nghĩa “học tập”.'),
    (1, 251, 'học hiệu', '学 (học): học. 校 (hiệu): trường học.', 'Danh từ', 'Trong cách nói “学校附近的房子有一个小花园”, 学校 mang nghĩa “trường học”.'),
    (1, 252, 'yếu', '要 (yếu): cần, muốn; quan trọng.', 'Động từ', 'Trong cách nói “医生说我要多休息”, 要 mang nghĩa “muốn”.'),
    (1, 253, 'dã', '也 (dã): cũng.', 'Phó từ', 'Trong cách nói “也爱妈妈”, 也 mang nghĩa “cũng”.'),
    (1, 254, 'nhất', '一 (nhất): một, số một.', 'Số từ', 'Trong cách nói “我一出门就看见了她”, 一 mang nghĩa “một”.'),
    (1, 255, 'nhất bán', '一 (nhất): một, số một. 半 (bán): nửa, một nửa.', 'Cụm số lượng', 'Trong cách nói “我吃了一半”, 一半 mang nghĩa “một nửa”.'),
    (1, 256, 'nhất điểm nhi', '一 (nhất): một, số một. 点 (điểm): giờ; chấm điểm. 儿 (nhi): con trẻ; âm đuôi ''r''.', 'Cụm số lượng', 'Trong cách nói “让鸟飞近一点儿”, 一点儿 mang nghĩa “một chút”.'),
    (1, 257, 'y phục', '衣 (y): áo, quần áo. 服 (phục): mặc; phục tùng; (trong 衣服).', 'Danh từ', 'Trong cách nói “衣服脏了怎么办”, 衣服 mang nghĩa “quần áo”.'),
    (1, 258, 'y sinh', '医 (y): y học; chữa bệnh. 生 (sinh): sinh ra, nảy sinh; sống.', 'Danh từ', 'Trong cách nói “医生说我要多休息”, 医生 mang nghĩa “bác sĩ”.'),
    (1, 259, 'nhất hạ', '一 (nhất): một, số một. 下 (hạ): dưới, xuống.', 'Cụm số lượng', 'Trong cách nói “请坐在椅子上等一下”, 一下 mang nghĩa “một lát”.'),
    (1, 260, 'nhất ta', '一 (nhất): một, số một. 些 (ta): vài, một ít.', 'Cụm số lượng', 'Trong cách nói “这个星期我买了一些新书”, 一些 mang nghĩa “một số, một vài”.'),
    (1, 261, 'y viện', '医 (y): y học; chữa bệnh. 院 (viện): viện, sân; toà nhà công.', 'Danh từ', 'Trong cách nói “这周得去医院”, 医院 mang nghĩa “bệnh viện”.'),
    (1, 262, 'ỷ tử', '椅 (ỷ): cái ghế tựa. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “请坐在椅子上等一下”, 椅子 mang nghĩa “ghế”.'),
    (1, 263, 'hữu', '有 (hữu): có, sở hữu.', 'Động từ', 'Trong cách nói “这个字有几笔”, 有 mang nghĩa “có”.'),
    (1, 264, 'hữu đích', '有 (hữu): có, sở hữu. 的 (đích): của; trợ từ định ngữ.', 'Đại từ', 'Trong cách nói “有的人只喜欢吃”, 有的 mang nghĩa “một số (người hoặc vật)”.'),
    (1, 265, 'hữu ta', '有 (hữu): có, sở hữu. 些 (ta): vài, một ít.', 'Đại từ', 'Trong cách nói “有些人爱做饭”, 有些 mang nghĩa “một số”.'),
    (1, 266, 'hữu nhất điểm nhi', '有 (hữu): có, sở hữu. 一 (nhất): một, số một. 点 (điểm): giờ; chấm điểm. 儿 (nhi): con trẻ; âm đuôi ''r''.', 'Cụm phó từ', 'Trong cách nói “最近我的嘴有点儿疼”, 有（一）点儿 mang nghĩa “hơi, có chút”.'),
    (1, 267, 'vũ', '雨 (vũ): mưa.', 'Danh từ', 'Trong cách nói “晚上可能还有雨”, 雨 mang nghĩa “mưa”.'),
    (1, 268, 'nguyên', '元 (nguyên): đồng tiền; khởi đầu, gốc.', 'Lượng từ', 'Trong cách nói “一斤苹果五元”, 元 mang nghĩa “nhân dân tệ (đơn vị tiền)”.'),
    (1, 269, 'nguyệt', '月 (nguyệt): trăng; tháng.', 'Danh từ', 'Trong cách nói “今天几月几日”, 月 mang nghĩa “tháng”.'),
    (1, 270, 'tái', '再 (tái): lại, lần nữa.', 'Phó từ', 'Trong cách nói “再往右走”, 再 mang nghĩa “lại, lần nữa”.'),
    (1, 271, 'tại', '在 (tại): ở, tại; đang.', 'Động từ, Giới từ, Phó từ', 'Trong cách nói “红色的花在屋子后面”, 在 mang nghĩa “ở”.'),
    (1, 272, 'tái kiến', '再 (tái): lại, lần nữa. 见 (kiến): thấy, gặp.', 'Động từ', 'Trong cách nói “再见”, 再见 mang nghĩa “tạm biệt”.'),
    (1, 273, 'tảo', '早 (tảo): sớm, buổi sáng.', 'Tính từ', 'Trong cách nói “你来得真早”, 早 mang nghĩa “sớm”.'),
    (1, 274, 'tảo phạn', '早 (tảo): sớm, buổi sáng. 饭 (phạn): cơm, bữa cơm.', 'Danh từ', 'Trong cách nói “我先去吃早饭”, 早饭 mang nghĩa “bữa sáng”.'),
    (1, 275, 'tảo thượng', '早 (tảo): sớm, buổi sáng. 上 (thượng): trên; lên.', 'Danh từ', 'Trong cách nói “我的妻子早上起来就去跑步”, 早上 mang nghĩa “buổi sáng”.'),
    (1, 276, 'chẩm ma', '怎 (chẩm): sao, thế nào. 么 (ma): trợ từ (trong 怎么, 什么).', 'Đại từ', 'Trong cách nói “去中学怎么走”, 怎么 mang nghĩa “thế nào, làm sao”.'),
    (1, 277, 'chẩm ma dạng', '怎 (chẩm): sao, thế nào. 么 (ma): trợ từ (trong 怎么, 什么). 样 (dạng): dáng vẻ, kiểu, loại.', 'Đại từ', 'Trong cách nói “你觉得怎么样”, 怎么样 mang nghĩa “như thế nào”.'),
    (1, 278, 'trảo', '找 (trảo): tìm, tìm kiếm.', 'Động từ', 'Trong cách nói “你找谁”, 找 mang nghĩa “tìm”.'),
    (1, 279, 'giá', '这 (giá): này, cái này.', 'Đại từ', 'Trong cách nói “这只羊跳得挺高”, 这 mang nghĩa “này, đây”.'),
    (1, 280, 'giá biên', '这 (giá): này, cái này. 边 (biên): bên, cạnh, rìa.', 'Đại từ', 'Trong cách nói “这边都是中学生”, 这边 mang nghĩa “bên này”.'),
    (1, 281, 'giá cá', '这 (giá): này, cái này. 个 (cá): cái, chiếc (lượng từ).', 'Đại từ', 'Trong cách nói “这个字有几笔”, 这个 mang nghĩa “cái này”.'),
    (1, 282, 'giá lý', '这 (giá): này, cái này. 里 (lý): bên trong; làng, dặm.', 'Đại từ', 'Trong cách nói “这里发生了什么事情”, 这里 mang nghĩa “chỗ này”.'),
    (1, 283, 'chân', '真 (chân): thật, chân thật.', 'Phó từ', 'Trong cách nói “这件女式上衣颜色真漂亮”, 真 mang nghĩa “thật, thật sự”.'),
    (1, 284, 'chính tại', '正 (chính): ngay thẳng, chính, đúng. 在 (tại): ở, tại; đang.', 'Phó từ', 'Trong cách nói “三年级的女生正在画一头牛”, 正在 mang nghĩa “đang”.'),
    (1, 285, 'giá nhi', '这 (giá): này, cái này. 儿 (nhi): con trẻ; âm đuôi ''r''.', 'Đại từ', 'Trong cách nói “那儿离这儿远吗”, 这儿 mang nghĩa “ở đây”.'),
    (1, 286, 'giá ta', '这 (giá): này, cái này. 些 (ta): vài, một ít.', 'Đại từ', 'Trong cách nói “再洗这些盘子”, 这些 mang nghĩa “những cái này”.'),
    (1, 287, 'chỉ', '只 (chỉ): chỉ, chỉ có.', 'Lượng từ', 'Đặt giữa số và danh từ khi đếm một số loài vật.'),
    (1, 288, 'tri đạo', '知 (tri): biết, hiểu. 道 (đạo): con đường; đạo lý.', 'Động từ', 'Trong cách nói “我不知道中午要做什么菜”, 知道 mang nghĩa “biết”.'),
    (1, 289, 'trung quốc', '中 (trung): giữa, trung tâm; trung học. 国 (quốc): nước, quốc gia.', 'Danh từ', 'Trong cách nói “我去过中国”, 中国 mang nghĩa “Trung Quốc”.'),
    (1, 290, 'trung văn', '中 (trung): giữa, trung tâm; trung học. 文 (văn): văn, chữ viết, văn vẻ.', 'Danh từ', 'Trong cách nói “我教中文”, 中文 mang nghĩa “tiếng Trung”.'),
    (1, 291, 'trung ngọ', '中 (trung): giữa, trung tâm; trung học. 午 (ngọ): giờ Ngọ, buổi trưa.', 'Danh từ', 'Trong cách nói “我不知道中午要做什么菜”, 中午 mang nghĩa “buổi trưa”.'),
    (1, 292, 'trung học', '中 (trung): giữa, trung tâm; trung học. 学 (học): học.', 'Danh từ', 'Trong cách nói “去中学怎么走”, 中学 mang nghĩa “trường trung học”.'),
    (1, 293, 'trung học sinh', '中 (trung): giữa, trung tâm; trung học. 学 (học): học. 生 (sinh): sinh ra, nảy sinh; sống.', 'Danh từ', 'Trong cách nói “这边都是中学生”, 中学生 mang nghĩa “học sinh trung học”.'),
    (1, 294, 'trú', '住 (trú): ở, cư trú.', 'Động từ', 'Trong cách nói “这位名人住在城市的南边”, 住 mang nghĩa “ở, cư trú”.'),
    (1, 295, 'trác tử', '桌 (trác): cái bàn. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “我把手机放在桌子上”, 桌子 mang nghĩa “cái bàn”.'),
    (1, 296, 'tự', '字 (tự): chữ, văn tự.', 'Danh từ', 'Trong cách nói “这个字有几笔”, 字 mang nghĩa “chữ”.'),
    (1, 297, 'toạ', '坐 (toạ): ngồi.', 'Động từ', 'Trong cách nói “我以为你一般都坐公交车”, 坐 mang nghĩa “ngồi”.'),
    (1, 298, 'tố', '做 (tố): làm, chế biến.', 'Động từ', 'Trong cách nói “请尝尝我们常常做的鱼”, 做 mang nghĩa “làm”.'),
    (1, 299, 'tố phạn', '做 (tố): làm, chế biến. 饭 (phạn): cơm, bữa cơm.', 'Cụm động từ', 'Trong cách nói “有些人爱做饭”, 做饭 mang nghĩa “nấu cơm”.'),
    (1, 300, 'tạc thiên', '昨 (tạc): hôm qua, đã qua. 天 (thiên): trời, bầu trời; ngày.', 'Danh từ', 'Trong cách nói “昨天这里下雪了”, 昨天 mang nghĩa “hôm qua”.'),
    (2, 301, 'a', '啊 (a): trợ từ cảm thán (à, a, nhé).', 'Trợ từ', 'Trong cách nói “啊”, 啊 mang nghĩa “à, nhé (trợ từ cuối câu)”.'),
    (2, 302, 'ái hảo', '爱 (ái): yêu, yêu thương; thích. 好 (hảo): tốt, đẹp, hay.', 'Động từ, Danh từ', 'Trong cách nói “原来你的爱好是跳舞”, 爱好 mang nghĩa “sở thích”.'),
    (2, 303, 'bạch sắc', '白 (bạch): trắng; rõ ràng. 色 (sắc): màu, sắc; sắc thái.', 'Danh từ', 'Trong cách nói “白色的包比黑色的包便宜”, 白色 mang nghĩa “màu trắng”.'),
    (2, 304, 'ban', '班 (ban): tổ, lớp; ca làm.', 'Danh từ', 'Trong cách nói “我们班有二十个人”, 班 mang nghĩa “lớp học”.'),
    (2, 305, 'bang', '帮 (bang): giúp; nhóm, bang hội.', 'Động từ', 'Trong cách nói “我来帮你拿行李”, 帮 mang nghĩa “giúp”.'),
    (2, 306, 'bang mang', '帮 (bang): giúp; nhóm, bang hội. 忙 (mang): bận, bận rộn.', 'Động từ', 'Trong cách nói “可以请你帮忙吗”, 帮忙 mang nghĩa “giúp đỡ”.'),
    (2, 307, 'bao', '包 (bao): túi, cặp; bao bọc.', 'Động từ, Danh từ, Lượng từ', 'Trong cách nói “白色的包比黑色的包便宜”, 包 mang nghĩa “túi, bao”.'),
    (2, 308, 'bản tử', '本 (bản): gốc; quyển (sách). 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “用这个旧本子写两句话吧”, 本子 mang nghĩa “quyển vở”.'),
    (2, 309, 'tỉ', '比 (tỉ): so sánh, so với.', 'Động từ, Giới từ', 'Trong cách nói “他比我差两分”, 比 mang nghĩa “so với”.'),
    (2, 310, 'bút', '笔 (bút): bút, cây bút.', 'Danh từ', 'Trong cách nói “请帮我把笔和本子放进书包”, 笔 mang nghĩa “bút”.'),
    (2, 311, 'biệt', '别 (biệt): khác; chia tách; chớ, đừng.', 'Phó từ', 'Trong cách nói “别出海”, 别 mang nghĩa “đừng”.'),
    (2, 312, 'bất thác', '不 (bất): không (phủ định). 错 (thác): sai, nhầm lẫn.', 'Tính từ', 'Trong cách nói “这家饭馆不错”, 不错 mang nghĩa “khá tốt”.'),
    (2, 313, 'bất hảo ý tư', '不 (bất): không (phủ định). 好 (hảo): tốt, đẹp, hay. 意 (ý): ý nghĩ, ý muốn. 思 (tư): nghĩ, suy nghĩ.', 'Cụm từ', 'Trong cách nói “不好意思”, 不好意思 mang nghĩa “ngại”.'),
    (2, 314, 'trường', '长 (trường): dài.', 'Tính từ', 'Trong cách nói “她的头发很长”, 长 mang nghĩa “dài”.'),
    (2, 315, 'xa trạm', '车 (xa): xe, xe cộ. 站 (trạm): đứng; trạm, bến.', 'Danh từ', 'Trong cách nói “车要开出车站了”, 车站 mang nghĩa “bến xe, nhà ga”.'),
    (2, 316, 'xuất', '出 (xuất): ra, đi ra.', 'Động từ', 'Trong cách nói “车要开出车站了”, 出 mang nghĩa “ra”.'),
    (2, 317, 'xuất quốc', '出 (xuất): ra, đi ra. 国 (quốc): nước, quốc gia.', 'Động từ', 'Trong cách nói “后天出国”, 出国 mang nghĩa “ra nước ngoài”.'),
    (2, 318, 'xuất lai', '出 (xuất): ra, đi ra. 来 (lai): đến, tới.', 'Động từ', 'Trong cách nói “快从教室出来”, 出来 mang nghĩa “đi ra (về phía người nói)”.'),
    (2, 319, 'xuất môn', '出 (xuất): ra, đi ra. 门 (môn): cửa, cổng.', 'Động từ', 'Trong cách nói “我一出门就看见了她”, 出门 mang nghĩa “ra khỏi nhà”.'),
    (2, 320, 'xuất khứ', '出 (xuất): ra, đi ra. 去 (khứ): đi, đi đến.', 'Động từ', 'Trong cách nói “穿上大衣再出去吧”, 出去 mang nghĩa “đi ra ngoài”.'),
    (2, 321, 'sàng', '床 (sàng): cái giường.', 'Danh từ', 'Trong cách nói “最后在床下发现了它”, 床 mang nghĩa “giường”.'),
    (2, 322, 'từ', '词 (từ): từ, lời, ngôn từ.', 'Danh từ', 'Trong cách nói “我每次都记不住这个词”, 词 mang nghĩa “từ, từ ngữ”.'),
    (2, 323, 'thứ', '次 (thứ): lần, lượt; thứ tự.', 'Lượng từ', 'Trong cách nói “我每次都记不住这个词”, 次 mang nghĩa “lần”.'),
    (2, 324, 'tòng', '从 (tòng): từ; theo, đi theo.', 'Giới từ', 'Trong cách nói “你从哪国来”, 从 mang nghĩa “từ (một nơi hoặc thời điểm)”.'),
    (2, 325, 'tòng tiểu', '从 (tòng): từ; theo, đi theo. 小 (tiểu): nhỏ, bé.', 'Phó từ', 'Trong cách nói “我从小就爱打篮球”, 从小 mang nghĩa “từ nhỏ”.'),
    (2, 326, 'thác', '错 (thác): sai, nhầm lẫn.', 'Tính từ', 'Trong cách nói “我拿错了你的东西”, 错 mang nghĩa “sai”.'),
    (2, 327, 'đả', '打 (đả): đánh, làm, gọi (điện).', 'Động từ', 'Trong cách nói “但是篮球打得不错”, 打 mang nghĩa “đánh, chơi (một số môn thể thao)”.'),
    (2, 328, 'đả xa', '打 (đả): đánh, làm, gọi (điện). 车 (xa): xe, xe cộ.', 'Động từ', 'Trong cách nói “我从小就跟爸爸打车去车站”, 打车 mang nghĩa “đi taxi”.'),
    (2, 329, 'đả khai', '打 (đả): đánh, làm, gọi (điện). 开 (khai): mở, khai mở; lái xe.', 'Động từ', 'Trong cách nói “请打开灯”, 打开 mang nghĩa “mở ra, bật lên”.'),
    (2, 330, 'đãn', '但 (đãn): nhưng, chỉ, song.', 'Liên từ', 'Trong cách nói “但不想点肉”, 但 mang nghĩa “nhưng”.'),
    (2, 331, 'đãn thị', '但 (đãn): nhưng, chỉ, song. 是 (thị): là, đúng, phải.', 'Liên từ', 'Trong cách nói “但是不会骑马”, 但是 mang nghĩa “nhưng”.'),
    (2, 332, 'đắc', '得 (đắc): được, đạt được; (trợ từ bổ ngữ).', 'Trợ từ', 'Đặt sau động từ và trước phần mô tả mức độ hoặc cách thực hiện.'),
    (2, 333, 'địa', '地 (địa): đất, mặt đất; nơi.', 'Trợ từ', 'Đặt sau trạng ngữ và trước động từ, như 慢慢地说.'),
    (2, 334, 'đẳng', '等 (đẳng): đợi, chờ; hạng, bằng nhau.', 'Động từ', 'Trong cách nói “请坐在椅子上等一下”, 等 mang nghĩa “đợi, chờ”.'),
    (2, 335, 'địa thiết', '地 (địa): đất, mặt đất; nơi. 铁 (thiết): sắt, thép.', 'Danh từ', 'Trong cách nói “地铁快要开了”, 地铁 mang nghĩa “tàu điện ngầm”.'),
    (2, 336, 'điểm', '点 (điểm): giờ; chấm điểm.', 'Động từ', 'Đứng trước tên món ăn khi gọi món.'),
    (2, 337, 'đổng', '懂 (đổng): hiểu, thông hiểu.', 'Động từ', 'Trong cách nói “我不懂这道题”, 懂 mang nghĩa “hiểu”.'),
    (2, 338, 'động', '动 (động): chuyển động, làm; cử động.', 'Động từ', 'Trong cách nói “别动”, 动 mang nghĩa “cử động, di chuyển”.'),
    (2, 339, 'phạn quán', '饭 (phạn): cơm, bữa cơm. 馆 (quán): toà nhà lớn (quán, viện, sảnh).', 'Danh từ', 'Trong cách nói “从这里打车去饭馆吧”, 饭馆 mang nghĩa “quán ăn”.'),
    (2, 340, 'phi', '飞 (phi): bay.', 'Động từ', 'Trong cách nói “让鸟飞近一点儿”, 飞 mang nghĩa “bay”.'),
    (2, 341, 'cao', '高 (cao): cao.', 'Tính từ, Danh từ', 'Trong cách nói “这只羊跳得挺高”, 高 mang nghĩa “cao”.'),
    (2, 342, 'cao trung', '高 (cao): cao. 中 (trung): giữa, trung tâm; trung học.', 'Danh từ', 'Trong cách nói “你在哪所高中读书”, 高中 mang nghĩa “trường trung học phổ thông”.'),
    (2, 343, 'cáo tố', '告 (cáo): báo, thưa, nói cho biết. 诉 (tố): kể, trình bày, kiện cáo.', 'Động từ', 'Trong cách nói “请告诉我”, 告诉 mang nghĩa “nói cho biết”.'),
    (2, 344, 'cá tử', '个 (cá): cái, chiếc (lượng từ). 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “我的个子跟哥哥一样高”, 个子 mang nghĩa “vóc người, chiều cao”.'),
    (2, 345, 'cân', '跟 (cân): gót chân; theo, cùng với.', 'Giới từ, Liên từ', 'Trong cách nói “我的个子跟哥哥一样高”, 跟 mang nghĩa “với, cùng”.'),
    (2, 346, 'công giao xa', '公 (công): chung, công cộng. 交 (giao): giao, trao. 车 (xa): xe, xe cộ.', 'Danh từ', 'Trong cách nói “我以为你一般都坐公交车”, 公交车 mang nghĩa “xe buýt”.'),
    (2, 347, 'quá', '过 (quá): qua, vượt qua, trải qua.', 'Động từ', 'Dùng như động từ, thường đi với địa điểm được đi qua.'),
    (2, 348, 'quá lai', '过 (quá): qua, vượt qua, trải qua. 来 (lai): đến, tới.', 'Động từ', 'Trong cách nói “你过来一下”, 过来 mang nghĩa “đi qua đây”.'),
    (2, 349, 'quá niên', '过 (quá): qua, vượt qua, trải qua. 年 (niên): năm.', 'Động từ', 'Trong cách nói “我们一起准备过年”, 过年 mang nghĩa “đón Tết”.'),
    (2, 350, 'quá khứ', '过 (quá): qua, vượt qua, trải qua. 去 (khứ): đi, đi đến.', 'Động từ', 'Diễn tả chuyển động sang phía xa người nói.'),
    (2, 351, 'quá', '过 (quá): qua, vượt qua, trải qua.', 'Trợ từ', 'Đứng sau động từ để nói về một trải nghiệm đã từng có.'),
    (2, 352, 'hoàn thị', '还 (hoàn): vẫn, còn; tạm được. 是 (thị): là, đúng, phải.', 'Phó từ, Liên từ', 'Trong cách nói “你要红茶还是绿茶”, 还是 mang nghĩa “hay là”.'),
    (2, 353, 'hắc sắc', '黑 (hắc): đen, màu đen; tối. 色 (sắc): màu, sắc; sắc thái.', 'Danh từ', 'Trong cách nói “白色的包比黑色的包便宜”, 黑色 mang nghĩa “màu đen”.'),
    (2, 354, 'hồng trà', '红 (hồng): màu đỏ; hồng. 茶 (trà): trà, chè.', 'Danh từ', 'Trong cách nói “你要红茶还是绿茶”, 红茶 mang nghĩa “trà đen, hồng trà”.'),
    (2, 355, 'hồng sắc', '红 (hồng): màu đỏ; hồng. 色 (sắc): màu, sắc; sắc thái.', 'Danh từ', 'Trong cách nói “红色的花在屋子后面”, 红色 mang nghĩa “màu đỏ”.'),
    (2, 356, 'hậu diện', '后 (hậu): sau, phía sau. 面 (diện): mặt, bề mặt.', 'Danh từ', 'Trong cách nói “红色的花在屋子后面”, 后面 mang nghĩa “phía sau”.'),
    (2, 357, 'hoa', '花 (hoa): hoa; tiêu xài; hoa mắt.', 'Danh từ', 'Đi với số tiền hoặc thời gian đã bỏ ra để làm việc gì.'),
    (2, 358, 'hoa', '花 (hoa): hoa; tiêu xài; hoa mắt.', 'Danh từ', 'Dùng như danh từ khi nói về hoa, có thể đi sau lượng từ 朵.'),
    (2, 359, 'hoạ', '画 (hoạ): vẽ; tranh, bức hoạ.', 'Động từ, Danh từ', 'Trong cách nói “他的画很受大家喜爱”, 画 mang nghĩa “vẽ”.'),
    (2, 360, 'hoại', '坏 (hoại): hỏng, xấu, hư.', 'Tính từ', 'Trong cách nói “空调坏了”, 坏 mang nghĩa “hỏng, xấu”.'),
    (2, 361, 'hồi lai', '回 (hồi): quay lại, trở về. 来 (lai): đến, tới.', 'Động từ', 'Trong cách nói “等我从机场回来”, 回来 mang nghĩa “trở về đây”.'),
    (2, 362, 'hồi khứ', '回 (hồi): quay lại, trở về. 去 (khứ): đi, đi đến.', 'Động từ', 'Trong cách nói “喝完红茶再回去”, 回去 mang nghĩa “quay về đó”.'),
    (2, 363, 'cơ trường', '机 (cơ): máy móc; cơ hội. 场 (trường): bãi, sân, nơi rộng.', 'Danh từ', 'Trong cách nói “等我从机场回来”, 机场 mang nghĩa “sân bay”.'),
    (2, 364, 'cơ phiếu', '机 (cơ): máy móc; cơ hội. 票 (phiếu): vé, phiếu.', 'Danh từ', 'Trong cách nói “再一起买机票”, 机票 mang nghĩa “vé máy bay”.'),
    (2, 365, 'ký đắc', '记 (ký): ghi, nhớ, ghi chép. 得 (đắc): được, đạt được; (trợ từ bổ ngữ).', 'Động từ', 'Trong cách nói “记得检查护照”, 记得 mang nghĩa “nhớ”.'),
    (2, 366, 'gian', '间 (gian): gian, phòng; khoảng giữa.', 'Lượng từ', 'Đặt sau số đếm và trước danh từ chỉ phòng.'),
    (2, 367, 'giáo', '教 (giáo): dạy, giảng dạy.', 'Động từ', 'Trong cách nói “我教中文”, 教 mang nghĩa “dạy”.'),
    (2, 368, 'giáo thất', '教 (giáo): dạy, giảng dạy. 室 (thất): phòng, gian phòng.', 'Danh từ', 'Trong cách nói “快从教室出来”, 教室 mang nghĩa “phòng học”.'),
    (2, 369, 'giới thiệu', '介 (giới): ở giữa, làm trung gian. 绍 (thiệu): nối tiếp, giới thiệu.', 'Động từ', 'Trong cách nói “我给你介绍一下新同事”, 介绍 mang nghĩa “giới thiệu”.'),
    (2, 370, 'tiến', '进 (tiến): vào, tiến vào.', 'Động từ', 'Trong cách nói “请帮我把笔和本子放进书包”, 进 mang nghĩa “vào”.'),
    (2, 371, 'cận', '近 (cận): gần.', 'Tính từ', 'Trong cách nói “这两座楼离得很近”, 近 mang nghĩa “gần”.'),
    (2, 372, 'tiến lai', '进 (tiến): vào, tiến vào. 来 (lai): đến, tới.', 'Động từ', 'Trong cách nói “请进来”, 进来 mang nghĩa “đi vào đây”.'),
    (2, 373, 'tiến khứ', '进 (tiến): vào, tiến vào. 去 (khứ): đi, đi đến.', 'Động từ', 'Trong cách nói “我想进去喝咖啡”, 进去 mang nghĩa “đi vào trong”.'),
    (2, 374, 'kinh thường', '经 (kinh): trải qua; sợi dọc; kinh điển. 常 (thường): thường, hay; bình thường.', 'Phó từ', 'Trong cách nói “开学以后我们经常一起复习”, 经常 mang nghĩa “thường xuyên”.'),
    (2, 375, 'tửu điếm', '酒 (tửu): rượu. 店 (điếm): cửa hàng, tiệm.', 'Danh từ', 'Trong cách nói “酒店里有咖啡店吗”, 酒店 mang nghĩa “khách sạn”.'),
    (2, 376, 'tựu', '就 (tựu): liền, ngay, thì; thành tựu.', 'Phó từ', 'Trong cách nói “我从小就爱打篮球”, 就 mang nghĩa “liền, ngay”.'),
    (2, 377, 'ca phê', '咖 (ca): ca (phiên âm, trong 咖啡). 啡 (phê): phê (phiên âm, trong 咖啡).', 'Danh từ', 'Trong cách nói “这里都卖咖啡”, 咖啡 mang nghĩa “cà phê”.'),
    (2, 378, 'khai thuỷ', '开 (khai): mở, khai mở; lái xe. 始 (thuỷ): bắt đầu, khởi đầu.', 'Động từ, Danh từ', 'Trong cách nói “我刚干完活就开始刮风了”, 开始 mang nghĩa “bắt đầu”.'),
    (2, 379, 'khai học', '开 (khai): mở, khai mở; lái xe. 学 (học): học.', 'Động từ', 'Trong cách nói “开学以后我们经常一起复习”, 开学 mang nghĩa “khai giảng, bắt đầu đi học”.'),
    (2, 380, 'khảo', '考 (khảo): thi, khảo sát; kiểm tra.', 'Động từ', 'Trong cách nói “考试快开始了”, 考 mang nghĩa “thi, kiểm tra”.'),
    (2, 381, 'khảo thí', '考 (khảo): thi, khảo sát; kiểm tra. 试 (thí): thử, kiểm tra.', 'Động từ, Danh từ', 'Trong cách nói “考试快开始了”, 考试 mang nghĩa “kỳ thi”.'),
    (2, 382, 'khả năng', '可 (khả): có thể, được; đáng. 能 (năng): có thể, được; năng lực.', 'Tính từ, Danh từ, Động từ', 'Trong cách nói “晚上可能还有雨”, 可能 mang nghĩa “có thể, có khả năng”.'),
    (2, 383, 'khố tử', '裤 (khố): quần. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “这条裤子送给你”, 裤子 mang nghĩa “quần dài”.'),
    (2, 384, 'khoái', '快 (khoái): nhanh; vui sướng.', 'Tính từ, Phó từ', 'Trong cách nói “你游得比我快多了”, 快 mang nghĩa “nhanh”.'),
    (2, 385, 'khoái lạc', '快 (khoái): nhanh; vui sướng. 乐 (lạc): vui vẻ.', 'Tính từ', 'Trong cách nói “这次旅行快乐极了”, 快乐 mang nghĩa “vui vẻ”.'),
    (2, 386, 'khoái yếu', '快 (khoái): nhanh; vui sướng. 要 (yếu): cần, muốn; quan trọng.', 'Phó từ', 'Trong cách nói “地铁快要开了”, 快要 mang nghĩa “sắp, sắp sửa”.'),
    (2, 387, 'lam cầu', '篮 (lam): cái giỏ, cái rổ. 球 (cầu): quả bóng; quả cầu.', 'Danh từ', 'Trong cách nói “但是篮球打得不错”, 篮球 mang nghĩa “bóng rổ”.'),
    (2, 388, 'luỹ', '累 (luỹ): chồng chất, tích dồn (lěi); mệt (lèi).', 'Tính từ, Động từ', 'Trong cách nói “她跑累了”, 累 mang nghĩa “mệt”.'),
    (2, 389, 'ly', '离 (ly): rời, lìa, cách xa.', 'Động từ', 'Trong cách nói “车站离这里不远”, 离 mang nghĩa “cách (một khoảng)”.'),
    (2, 390, 'lý diện', '里 (lý): bên trong; làng, dặm. 面 (diện): mặt, bề mặt.', 'Danh từ', 'Trong cách nói “里面有很多大学生”, 里面 mang nghĩa “bên trong”.'),
    (2, 391, 'lâu', '楼 (lâu): toà nhà, lầu, tầng.', 'Danh từ', 'Trong cách nói “这栋楼里面有一家旅行社”, 楼 mang nghĩa “tòa nhà”.'),
    (2, 392, 'lộ', '路 (lộ): đường, con đường, lối đi.', 'Danh từ', 'Trong cách nói “哪条路最短”, 路 mang nghĩa “đường”.'),
    (2, 393, 'lộ thượng', '路 (lộ): đường, con đường, lối đi. 上 (thượng): trên; lên.', 'Danh từ', 'Trong cách nói “路上很热闹”, 路上 mang nghĩa “trên đường”.'),
    (2, 394, 'lữ du', '旅 (lữ): đi xa, lữ hành; đoàn quân. 游 (du): bơi; rong chơi, du ngoạn.', 'Động từ', 'Trong cách nói “明年你和男朋友想去哪儿旅游呢”, 旅游 mang nghĩa “du lịch”.'),
    (2, 395, 'lục trà', '绿 (lục): màu xanh lá cây. 茶 (trà): trà, chè.', 'Danh từ', 'Trong cách nói “你要红茶还是绿茶”, 绿茶 mang nghĩa “trà xanh”.'),
    (2, 396, 'lục sắc', '绿 (lục): màu xanh lá cây. 色 (sắc): màu, sắc; sắc thái.', 'Danh từ', 'Trong cách nói “绿色的门在左边”, 绿色 mang nghĩa “màu xanh lá cây”.'),
    (2, 397, 'mạn', '慢 (mạn): chậm, chậm chạp.', 'Tính từ', 'Trong cách nói “这匹老马跑得比那辆车慢”, 慢 mang nghĩa “chậm”.'),
    (2, 398, 'một ý tư', '没 (một): không có; chìm mất. 意 (ý): ý nghĩ, ý muốn. 思 (tư): nghĩ, suy nghĩ.', 'Cụm từ', 'Trong cách nói “这个节目没意思”, 没意思 mang nghĩa “chán, không thú vị”.'),
    (2, 399, 'mỗi', '每 (mỗi): mỗi, từng cái.', 'Đại từ', 'Trong cách nói “每一季都有新花”, 每 mang nghĩa “mỗi”.'),
    (2, 400, 'môn', '门 (môn): cửa, cổng.', 'Danh từ', 'Trong cách nói “球飞进了门”, 门 mang nghĩa “cửa”.'),
    (2, 401, 'môn khẩu', '门 (môn): cửa, cổng. 口 (khẩu): miệng; cửa, lối ra vào.', 'Danh từ', 'Trong cách nói “小区门口车多”, 门口 mang nghĩa “cửa ra vào”.'),
    (2, 402, 'môn phiếu', '门 (môn): cửa, cổng. 票 (phiếu): vé, phiếu.', 'Danh từ', 'Trong cách nói “请在门口买门票”, 门票 mang nghĩa “vé vào cửa”.'),
    (2, 403, 'diện', '面 (diện): mặt, bề mặt.', 'Hậu tố', 'Gắn sau từ chỉ phương hướng để tạo từ chỉ vị trí.'),
    (2, 404, 'danh', '名 (danh): tên gọi, danh tiếng.', 'Danh từ, Lượng từ', 'Trong cách nói “这条街的名字好记”, 名 mang nghĩa “tên”.'),
    (2, 405, 'nã', '拿 (nã): cầm, lấy, mang.', 'Động từ', 'Trong cách nói “我来帮你拿行李”, 拿 mang nghĩa “cầm, lấy”.'),
    (2, 406, 'na ma', '那 (na): kia, đó. 么 (ma): trợ từ (trong 怎么, 什么).', 'Đại từ, Liên từ', 'Trong cách nói “奶茶没有你说的那么甜”, 那么 mang nghĩa “như thế, đến thế”.'),
    (2, 407, 'na dạng', '那 (na): kia, đó. 样 (dạng): dáng vẻ, kiểu, loại.', 'Đại từ', 'Trong cách nói “别像他那样跑”, 那样 mang nghĩa “như vậy”.'),
    (2, 408, 'nãi trà', '奶 (nãi): sữa; bà. 茶 (trà): trà, chè.', 'Danh từ', 'Trong cách nói “奶茶没有你说的那么甜”, 奶茶 mang nghĩa “trà sữa”.'),
    (2, 409, 'nãi nãi', '奶 (nãi): sữa; bà.', 'Danh từ', 'Trong cách nói “两名学生帮奶奶拿东西”, 奶奶 mang nghĩa “bà nội”.'),
    (2, 410, 'nam hài nhi', '男 (nam): nam giới, con trai. 孩 (hài): trẻ con, đứa bé. 儿 (nhi): con trẻ; âm đuôi ''r''.', 'Danh từ', 'Trong cách nói “男孩儿和女孩儿在公园里踢球”, 男孩儿 mang nghĩa “bé trai”.'),
    (2, 411, 'điểu', '鸟 (điểu): con chim.', 'Danh từ', 'Trong cách nói “让鸟飞近一点儿”, 鸟 mang nghĩa “chim”.'),
    (2, 412, 'nữ hài nhi', '女 (nữ): nữ, phụ nữ, con gái. 孩 (hài): trẻ con, đứa bé. 儿 (nhi): con trẻ; âm đuôi ''r''.', 'Danh từ', 'Trong cách nói “男孩儿和女孩儿在公园里踢球”, 女孩儿 mang nghĩa “bé gái”.'),
    (2, 413, 'bàng biên', '旁 (bàng): bên, cạnh; phía bên. 边 (biên): bên, cạnh, rìa.', 'Danh từ', 'Trong cách nói “旁边还留着一行”, 旁边 mang nghĩa “bên cạnh”.'),
    (2, 414, 'bào', '跑 (bào): chạy.', 'Động từ', 'Trong cách nói “他正向我们跑来”, 跑 mang nghĩa “chạy”.'),
    (2, 415, 'bào bộ', '跑 (bào): chạy. 步 (bộ): bước, bước chân.', 'Động từ', 'Trong cách nói “我的妻子早上起来就去跑步”, 跑步 mang nghĩa “chạy bộ”.'),
    (2, 416, 'phiếu', '票 (phiếu): vé, phiếu.', 'Danh từ', 'Trong cách nói “这位客人订了一万张票”, 票 mang nghĩa “vé”.'),
    (2, 417, 'thê tử', '妻 (thê): vợ. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “我的妻子早上起来就去跑步”, 妻子 mang nghĩa “vợ”.'),
    (2, 418, 'khởi lai', '起 (khởi): đứng dậy, nổi lên, khởi đầu. 来 (lai): đến, tới.', 'Động từ', 'Trong cách nói “我的妻子早上起来就去跑步”, 起来 mang nghĩa “đứng dậy”.'),
    (2, 419, 'tiền diện', '前 (tiền): phía trước; trước đây. 面 (diện): mặt, bề mặt.', 'Danh từ', 'Trong cách nói “前面那个商场很大”, 前面 mang nghĩa “phía trước”.'),
    (2, 420, 'tình', '晴 (tình): trời quang, nắng đẹp.', 'Tính từ', 'Trong cách nói “明天天气晴的话”, 晴 mang nghĩa “trời quang”.'),
    (2, 421, 'cầu', '球 (cầu): quả bóng; quả cầu.', 'Danh từ', 'Trong cách nói “我踢了两次球”, 球 mang nghĩa “quả bóng”.'),
    (2, 422, 'nhượng', '让 (nhượng): để cho, bảo, nhường.', 'Động từ', 'Trong cách nói “让鸟飞近一点儿”, 让 mang nghĩa “để, cho phép”.'),
    (2, 423, 'nhục', '肉 (nhục): thịt.', 'Danh từ', 'Trong cách nói “别忘了送两斤肉到我家”, 肉 mang nghĩa “thịt”.'),
    (2, 424, 'thương trường', '商 (thương): buôn bán, thương mại. 场 (trường): bãi, sân, nơi rộng.', 'Danh từ', 'Trong cách nói “商场上面还有一家书店”, 商场 mang nghĩa “trung tâm mua sắm”.'),
    (2, 425, 'thượng lai', '上 (thượng): trên; lên. 来 (lai): đến, tới.', 'Động từ', 'Trong cách nói “你上来帮我把箱子放在柜子上面吧”, 上来 mang nghĩa “lên đây”.'),
    (2, 426, 'thượng diện', '上 (thượng): trên; lên. 面 (diện): mặt, bề mặt.', 'Danh từ', 'Trong cách nói “你上来帮我把箱子放在柜子上面吧”, 上面 mang nghĩa “phía trên”.'),
    (2, 427, 'thượng khứ', '上 (thượng): trên; lên. 去 (khứ): đi, đi đến.', 'Động từ', 'Trong cách nói “我就上去看看”, 上去 mang nghĩa “lên đó”.'),
    (2, 428, 'thượng võng', '上 (thượng): trên; lên. 网 (võng): lưới; mạng internet.', 'Động từ', 'Trong cách nói “晚上上网太久对身体不好”, 上网 mang nghĩa “lên mạng”.'),
    (2, 429, 'thân thể', '身 (thân): thân thể, mình. 体 (thể): thân thể, cơ thể.', 'Danh từ', 'Trong cách nói “晚上上网太久对身体不好”, 身体 mang nghĩa “cơ thể”.'),
    (2, 430, 'sinh nhật', '生 (sinh): sinh ra, nảy sinh; sống. 日 (nhật): ngày; mặt trời.', 'Danh từ', 'Trong cách nói “六月二日是我的生日”, 生日 mang nghĩa “sinh nhật”.'),
    (2, 431, 'thời', '时 (thời): thời gian, giờ, khi.', 'Danh từ', 'Trong cách nói “照相时只能站在中间吗”, 时 mang nghĩa “giờ”.'),
    (2, 432, 'sự tình', '事 (sự): việc, sự việc. 情 (tình): tình cảm, cảm xúc.', 'Danh từ', 'Trong cách nói “这里发生了什么事情”, 事情 mang nghĩa “sự việc”.'),
    (2, 433, 'thủ', '手 (thủ): tay, bàn tay.', 'Danh từ', 'Trong cách nói “我的手有点儿疼”, 手 mang nghĩa “bàn tay”.'),
    (2, 434, 'thủ biểu', '手 (thủ): tay, bàn tay. 表 (biểu): bày tỏ, mặt ngoài; cái đồng hồ.', 'Danh từ', 'Trong cách nói “手表坏了”, 手表 mang nghĩa “đồng hồ đeo tay”.'),
    (2, 435, 'thư bao', '书 (thư): sách, viết. 包 (bao): túi, cặp; bao bọc.', 'Danh từ', 'Trong cách nói “请帮我把笔和本子放进书包”, 书包 mang nghĩa “cặp sách”.'),
    (2, 436, 'thư phục', '舒 (thư): duỗi ra, thư thái; thong thả. 服 (phục): mặc; phục tùng; (trong 衣服).', 'Tính từ', 'Trong cách nói “这双鞋舒服吗”, 舒服 mang nghĩa “thoải mái, dễ chịu”.'),
    (2, 437, 'tống', '送 (tống): giao, tặng, tiễn.', 'Động từ', 'Trong cách nói “别忘了送两斤肉到我家”, 送 mang nghĩa “tặng”.'),
    (2, 438, 'tuy nhiên', '虽 (tuy): tuy, mặc dù. 然 (nhiên): như vậy; đúng vậy.', 'Liên từ', 'Trong cách nói “虽然事情很多”, 虽然 mang nghĩa “mặc dù”.'),
    (2, 439, 'sở dĩ', '所 (sở): nơi, chỗ; (cái) mà. 以 (dĩ): lấy, dùng; theo.', 'Liên từ', 'Trong cách nói “所以今天不打球”, 所以 mang nghĩa “vì vậy”.'),
    (2, 440, 'đông', '疼 (đông): đau, đau nhức.', 'Tính từ', 'Trong cách nói “最近我的嘴有点儿疼”, 疼 mang nghĩa “đau”.'),
    (2, 441, 'thích', '踢 (thích): đá (bằng chân).', 'Động từ', 'Trong cách nói “我踢了两次球”, 踢 mang nghĩa “đá (bằng chân)”.'),
    (2, 442, 'đề', '题 (đề): đề bài, câu hỏi.', 'Danh từ', 'Trong cách nói “简单的题也可能错”, 题 mang nghĩa “đề bài, câu hỏi”.'),
    (2, 443, 'điều', '条 (điều): nhánh, dải dài; điều khoản; lượng từ vật dài.', 'Lượng từ', 'Trong cách nói “这条短裤太短”, 条 mang nghĩa “lượng từ cho vật dài, mảnh”.'),
    (2, 444, 'khiêu vũ', '跳 (khiêu): nhảy, bật lên. 舞 (vũ): múa, vũ điệu.', 'Động từ', 'Trong cách nói “原来你的爱好是跳舞”, 跳舞 mang nghĩa “nhảy múa”.'),
    (2, 445, 'đầu', '头 (đầu): đầu; cái đầu; đứng đầu.', 'Danh từ', 'Trong cách nói “头就开始疼了”, 头 mang nghĩa “đầu”.'),
    (2, 446, 'ngoại quốc', '外 (ngoại): ngoài, bên ngoài. 国 (quốc): nước, quốc gia.', 'Danh từ', 'Trong cách nói “这间教室是用来教外国学生汉语的”, 外国 mang nghĩa “nước ngoài”.'),
    (2, 447, 'ngoại diện', '外 (ngoại): ngoài, bên ngoài. 面 (diện): mặt, bề mặt.', 'Danh từ', 'Trong cách nói “外面在刮风”, 外面 mang nghĩa “bên ngoài”.'),
    (2, 448, 'hoàn', '完 (hoàn): xong, trọn vẹn, hoàn tất.', 'Động từ', 'Trong cách nói “听完解释”, 完 mang nghĩa “xong, hết”.'),
    (2, 449, 'vạn', '万 (vạn): vạn, mười nghìn.', 'Số từ', 'Trong cách nói “这位客人订了一万张票”, 万 mang nghĩa “vạn, mười nghìn”.'),
    (2, 450, 'vãng', '往 (vãng): về phía, hướng tới; đã qua.', 'Động từ, Giới từ', 'Trong cách nói “往左走十米”, 往 mang nghĩa “về phía”.'),
    (2, 451, 'võng thượng', '网 (võng): lưới; mạng internet. 上 (thượng): trên; lên.', 'Danh từ', 'Trong cách nói “所以在网上学汉语”, 网上 mang nghĩa “trên mạng”.'),
    (2, 452, 'vong', '忘 (vong): quên.', 'Động từ', 'Trong cách nói “别忘了送两斤肉到我家”, 忘 mang nghĩa “quên”.'),
    (2, 453, 'vị', '位 (vị): vị trí; vị (kính ngữ đếm người).', 'Lượng từ', 'Trong cách nói “这位客人订了一万张票”, 位 mang nghĩa “vị (lượng từ kính trọng)”.'),
    (2, 454, 'vị thập ma', '为 (vị): vì, cho. 什 (thập): cái gì (trong 什么). 么 (ma): trợ từ (trong 怎么, 什么).', 'Cụm từ', 'Trong cách nói “你为什么不洗手就吃饭”, 为什么 mang nghĩa “tại sao”.'),
    (2, 455, 'hi vọng', '希 (hi): hiếm, mong mỏi. 望 (vọng): ngóng trông, kì vọng.', 'Động từ', 'Trong cách nói “小时候我希望别人记得我的姓名”, 希望 mang nghĩa “hy vọng”.'),
    (2, 456, 'tẩy', '洗 (tẩy): rửa, giặt, tắm rửa.', 'Động từ', 'Trong cách nói “请先洗手”, 洗 mang nghĩa “rửa, giặt”.'),
    (2, 457, 'tẩy thủ gian', '洗 (tẩy): rửa, giặt, tắm rửa. 手 (thủ): tay, bàn tay. 间 (gian): gian, phòng; khoảng giữa.', 'Danh từ', 'Trong cách nói “右边是洗手间”, 洗手间 mang nghĩa “nhà vệ sinh”.'),
    (2, 458, 'hạ lai', '下 (hạ): dưới, xuống. 来 (lai): đến, tới.', 'Động từ', 'Trong cách nói “你先下来”, 下来 mang nghĩa “xuống đây”.'),
    (2, 459, 'hạ diện', '下 (hạ): dưới, xuống. 面 (diện): mặt, bề mặt.', 'Danh từ', 'Trong cách nói “我在下面等”, 下面 mang nghĩa “phía dưới”.'),
    (2, 460, 'hạ khứ', '下 (hạ): dưới, xuống. 去 (khứ): đi, đi đến.', 'Động từ', 'Trong cách nói “我们一起走下去”, 下去 mang nghĩa “xuống đó”.'),
    (2, 461, 'tiểu hài nhi', '小 (tiểu): nhỏ, bé. 孩 (hài): trẻ con, đứa bé. 儿 (nhi): con trẻ; âm đuôi ''r''.', 'Danh từ', 'Trong cách nói “小孩儿听爷爷讲小时候的故事”, 小孩儿 mang nghĩa “trẻ nhỏ”.'),
    (2, 462, 'tiểu thời hậu', '小 (tiểu): nhỏ, bé. 时 (thời): thời gian, giờ, khi. 候 (hậu): chờ đợi; thời tiết.', 'Danh từ', 'Trong cách nói “小时候我希望别人记得我的姓名”, 小时候 mang nghĩa “lúc nhỏ”.'),
    (2, 463, 'tiếu', '笑 (tiếu): cười.', 'Động từ', 'Trong cách nói “她笑着收下礼物”, 笑 mang nghĩa “cười”.'),
    (2, 464, 'tính', '姓 (tính): họ, tên họ.', 'Danh từ, Động từ', 'Trong cách nói “我姓陈”, 姓 mang nghĩa “mang họ”.'),
    (2, 465, 'tính danh', '姓 (tính): họ, tên họ. 名 (danh): tên gọi, danh tiếng.', 'Danh từ', 'Trong cách nói “小时候我希望别人记得我的姓名”, 姓名 mang nghĩa “họ tên”.'),
    (2, 466, 'nhan sắc', '颜 (nhan): sắc mặt, dung nhan; màu. 色 (sắc): màu, sắc; sắc thái.', 'Danh từ', 'Trong cách nói “她的眼睛是什么颜色的”, 颜色 mang nghĩa “màu sắc”.'),
    (2, 467, 'nhãn tinh', '眼 (nhãn): mắt; con mắt. 睛 (tinh): con ngươi mắt (trong 眼睛).', 'Danh từ', 'Trong cách nói “她的眼睛是什么颜色的”, 眼睛 mang nghĩa “mắt”.'),
    (2, 468, 'dược', '药 (dược): thuốc, dược phẩm.', 'Danh từ', 'Trong cách nói “这两种药的主要作用是什么”, 药 mang nghĩa “thuốc”.'),
    (2, 469, 'dược điếm', '药 (dược): thuốc, dược phẩm. 店 (điếm): cửa hàng, tiệm.', 'Danh từ', 'Trong cách nói “右边有家药店”, 药店 mang nghĩa “hiệu thuốc”.'),
    (2, 470, 'gia gia', '爷 (gia): ông; bậc cha chú lớn tuổi.', 'Danh từ', 'Trong cách nói “爷爷养羊”, 爷爷 mang nghĩa “ông nội”.'),
    (2, 471, 'nhất hội nhi', '一 (nhất): một, số một. 会 (hội): biết; họp; chốc lát. 儿 (nhi): con trẻ; âm đuôi ''r''.', 'Cụm số lượng', 'Trong cách nói “我想再睡一会儿”, 一会儿 mang nghĩa “một lát”.'),
    (2, 472, 'dĩ kinh', '已 (dĩ): đã, rồi; thôi, dừng. 经 (kinh): trải qua; sợi dọc; kinh điển.', 'Phó từ', 'Trong cách nói “这匹马已经老了”, 已经 mang nghĩa “đã”.'),
    (2, 473, 'nhất khởi', '一 (nhất): một, số một. 起 (khởi): đứng dậy, nổi lên, khởi đầu.', 'Phó từ', 'Trong cách nói “开学以后我们经常一起复习”, 一起 mang nghĩa “cùng nhau”.'),
    (2, 474, 'ý tư', '意 (ý): ý nghĩ, ý muốn. 思 (tư): nghĩ, suy nghĩ.', 'Danh từ', 'Trong cách nói “我坐在床上查这个词的意思”, 意思 mang nghĩa “ý nghĩa, ý”.'),
    (2, 475, 'âm', '阴 (âm): (trời) âm u, nhiều mây; âm.', 'Tính từ', 'Trong cách nói “天阴了”, 阴 mang nghĩa “âm u, nhiều mây”.'),
    (2, 476, 'nhân vị', '因 (nhân): nguyên nhân, lý do. 为 (vị): vì, cho.', 'Giới từ, Liên từ', 'Trong cách nói “因为别人说她的衣服难看”, 因为 mang nghĩa “bởi vì”.'),
    (2, 477, 'du', '游 (du): bơi; rong chơi, du ngoạn.', 'Động từ', 'Trong cách nói “你游得比我快多了”, 游 mang nghĩa “bơi”.'),
    (2, 478, 'du vịnh', '游 (du): bơi; rong chơi, du ngoạn. 泳 (vịnh): bơi, lội.', 'Động từ', 'Trong cách nói “游泳后就去洗澡”, 游泳 mang nghĩa “bơi lội”.'),
    (2, 479, 'hữu ý tư', '有 (hữu): có, sở hữu. 意 (ý): ý nghĩ, ý muốn. 思 (tư): nghĩ, suy nghĩ.', 'Cụm từ', 'Trong cách nói “这个故事很有意思”, 有意思 mang nghĩa “thú vị”.'),
    (2, 480, 'hữu thời', '有 (hữu): có, sở hữu. 时 (thời): thời gian, giờ, khi.', 'Phó từ', 'Trong cách nói “有时还跳出水面”, 有时 mang nghĩa “đôi khi”.'),
    (2, 481, 'hữu', '右 (hữu): bên phải, phía phải.', 'Danh từ', 'Trong cách nói “再往右走”, 右 mang nghĩa “phải, bên phải”.'),
    (2, 482, 'hữu biên', '右 (hữu): bên phải, phía phải. 边 (biên): bên, cạnh, rìa.', 'Danh từ', 'Trong cách nói “右边是洗手间”, 右边 mang nghĩa “bên phải”.'),
    (2, 483, 'ngư', '鱼 (ngư): con cá.', 'Danh từ', 'Trong cách nói “你吃过这种鱼吗”, 鱼 mang nghĩa “cá”.'),
    (2, 484, 'viễn', '远 (viễn): xa, xa xôi.', 'Tính từ', 'Trong cách nói “那儿离这儿远吗”, 远 mang nghĩa “xa”.'),
    (2, 485, 'vận động', '运 (vận): chở, vận chuyển; vận may. 动 (động): chuyển động, làm; cử động.', 'Động từ, Danh từ', 'Trong cách nói “有些同学喜欢运动”, 运动 mang nghĩa “vận động”.'),
    (2, 486, 'trạm', '站 (trạm): đứng; trạm, bến.', 'Danh từ', 'Dùng khi nói về trạm dừng hoặc đếm số chặng đi xe.'),
    (2, 487, 'trượng phu', '丈 (trượng): trượng (đơn vị đo); bậc nam giới lớn. 夫 (phu): người đàn ông, chồng.', 'Danh từ', 'Trong cách nói “我的丈夫也爱听”, 丈夫 mang nghĩa “chồng”.'),
    (2, 488, 'giá ma', '这 (giá): này, cái này. 么 (ma): trợ từ (trong 怎么, 什么).', 'Đại từ', 'Trong cách nói “下一站这么近”, 这么 mang nghĩa “thế này, đến vậy”.'),
    (2, 489, 'giá dạng', '这 (giá): này, cái này. 样 (dạng): dáng vẻ, kiểu, loại.', 'Đại từ', 'Trong cách nói “这样踢足球最安全”, 这样 mang nghĩa “như thế này”.'),
    (2, 490, 'trước', '着 (trước): dính, chạm tới; (trợ từ tiếp diễn).', 'Trợ từ', 'Đặt sau động từ khi miêu tả một tư thế hoặc trạng thái đang được duy trì.'),
    (2, 491, 'chính', '正 (chính): ngay thẳng, chính, đúng.', 'Phó từ', 'Trong cách nói “我正看电视”, 正 mang nghĩa “đang, đúng lúc”.'),
    (2, 492, 'chu', '周 (chu): vòng quanh, chu kỳ; tuần.', 'Danh từ', 'Trong cách nói “这周我在家”, 周 mang nghĩa “tuần”.'),
    (2, 493, 'chuẩn bị', '准 (chuẩn): chuẩn, đúng; cho phép. 备 (bị): chuẩn bị, sắm sẵn; đủ.', 'Động từ', 'Trong cách nói “请准备好资料”, 准备 mang nghĩa “chuẩn bị”.'),
    (2, 494, 'tự kỷ', '自 (tự): tự, mình; từ. 己 (kỷ): bản thân mình; can thứ 6.', 'Đại từ', 'Trong cách nói “你还自己走路回家吗”, 自己 mang nghĩa “bản thân, tự mình”.'),
    (2, 495, 'tẩu', '走 (tẩu): đi, đi bộ, bước đi.', 'Động từ', 'Trong cách nói “去中学怎么走”, 走 mang nghĩa “đi, rời đi”.'),
    (2, 496, 'tẩu lộ', '走 (tẩu): đi, đi bộ, bước đi. 路 (lộ): đường, con đường, lối đi.', 'Động từ', 'Trong cách nói “你还自己走路回家吗”, 走路 mang nghĩa “đi bộ”.'),
    (2, 497, 'túc cầu', '足 (túc): chân; đủ, đầy đủ. 球 (cầu): quả bóng; quả cầu.', 'Danh từ', 'Trong cách nói “他最爱足球”, 足球 mang nghĩa “bóng đá”.'),
    (2, 498, 'tối', '最 (tối): nhất, cực nhất.', 'Phó từ', 'Trong cách nói “这样踢足球最安全”, 最 mang nghĩa “nhất”.'),
    (2, 499, 'tả', '左 (tả): bên trái.', 'Danh từ', 'Trong cách nói “往左走十米”, 左 mang nghĩa “trái, bên trái”.'),
    (2, 500, 'tả biên', '左 (tả): bên trái. 边 (biên): bên, cạnh, rìa.', 'Danh từ', 'Trong cách nói “绿色的门在左边”, 左边 mang nghĩa “bên trái”.'),
    (3, 501, 'a di', '阿 (a): tiền tố thân mật (a-). 姨 (di): dì (chị/em gái của mẹ).', 'Danh từ', 'Trong cách nói “阿姨的爱人比她矮一点儿”, 阿姨 mang nghĩa “dì, cô”.'),
    (3, 502, 'ải', '矮 (ải): thấp, lùn.', 'Tính từ', 'Trong cách nói “阿姨的爱人比她矮一点儿”, 矮 mang nghĩa “thấp, lùn”.'),
    (3, 503, 'ái nhân', '爱 (ái): yêu, yêu thương; thích. 人 (nhân): người.', 'Danh từ', 'Trong cách nói “阿姨的爱人比她矮一点儿”, 爱人 mang nghĩa “vợ hoặc chồng”.'),
    (3, 504, 'an tĩnh', '安 (an): yên, an ổn. 静 (tĩnh): tĩnh, lặng.', 'Tính từ', 'Trong cách nói “请安静”, 安静 mang nghĩa “yên tĩnh”.'),
    (3, 505, 'an toàn', '安 (an): yên, an ổn. 全 (toàn): toàn vẹn, đầy đủ.', 'Tính từ', 'Trong cách nói “这样踢足球最安全”, 安全 mang nghĩa “an toàn”.'),
    (3, 506, 'bả', '把 (bả): lượng từ (vật có cán); cầm, đem.', 'Lượng từ, Giới từ', 'Có thể đặt trước tân ngữ để nói hành động tác động lên đối tượng đó như thế nào.'),
    (3, 507, 'ban', '搬 (ban): khiêng, dời, chuyển.', 'Động từ', 'Trong cách nói “画家后来搬到花园附近”, 搬 mang nghĩa “khuân, dọn chuyển”.'),
    (3, 508, 'ban cấp', '班 (ban): tổ, lớp; ca làm. 级 (cấp): cấp bậc, bậc, lớp.', 'Danh từ', 'Trong cách nói “我们班级的学生都来帮助老师搬家”, 班级 mang nghĩa “lớp học”.'),
    (3, 509, 'ban gia', '搬 (ban): khiêng, dời, chuyển. 家 (gia): nhà, gia đình.', 'Động từ', 'Trong cách nói “我们班级的学生都来帮助老师搬家”, 搬家 mang nghĩa “chuyển nhà”.'),
    (3, 510, 'biện', '办 (biện): làm, lo liệu, xử lý.', 'Động từ', 'Trong cách nói “这样办不行”, 办 mang nghĩa “làm, xử lý”.'),
    (3, 511, 'biện pháp', '办 (biện): làm, lo liệu, xử lý. 法 (pháp): phép, cách thức, luật.', 'Danh từ', 'Trong cách nói “还有别的办法过河吗”, 办法 mang nghĩa “cách, biện pháp”.'),
    (3, 512, 'biện công thất', '办 (biện): làm, lo liệu, xử lý. 公 (công): chung, công cộng. 室 (thất): phòng, gian phòng.', 'Danh từ', 'Trong cách nói “他出院后不久就回办公室上班了”, 办公室 mang nghĩa “văn phòng”.'),
    (3, 513, 'bán thiên', '半 (bán): nửa, một nửa. 天 (thiên): trời, bầu trời; ngày.', 'Cụm số lượng', 'Trong cách nói “我等了半天”, 半天 mang nghĩa “nửa ngày”.'),
    (3, 514, 'bang trợ', '帮 (bang): giúp; nhóm, bang hội. 助 (trợ): giúp đỡ, hỗ trợ.', 'Động từ', 'Trong cách nói “我们班级的学生都来帮助老师搬家”, 帮助 mang nghĩa “giúp đỡ”.'),
    (3, 515, 'bão', '饱 (bão): no, đầy bụng.', 'Tính từ', 'Trong cách nói “我已经饱了”, 饱 mang nghĩa “no”.'),
    (3, 516, 'báo chỉ', '报 (báo): báo tin, tờ báo; đáp lại. 纸 (chỉ): giấy.', 'Danh từ', 'Trong cách nói “你看看报纸上有什么新闻”, 报纸 mang nghĩa “báo giấy”.'),
    (3, 517, 'bắc', '北 (bắc): hướng Bắc.', 'Danh từ', 'Trong cách nói “他向北走”, 北 mang nghĩa “bắc”.'),
    (3, 518, 'bắc phương', '北 (bắc): hướng Bắc. 方 (phương): phương, vuông; cách thức.', 'Danh từ', 'Trong cách nói “在北方读完初中”, 北方 mang nghĩa “miền Bắc”.'),
    (3, 519, 'bị', '被 (bị): bị, được (bị động).', 'Giới từ', 'Trong cách nói “我的笔记本被别人拿走了”, 被 mang nghĩa “bị, được (chỉ thể bị động)”.'),
    (3, 520, 'bút ký', '笔 (bút): bút, cây bút. 记 (ký): ghi, nhớ, ghi chép.', 'Danh từ', 'Trong cách nói “下节课我想借你的笔记”, 笔记 mang nghĩa “ghi chép, vở ghi”.'),
    (3, 521, 'tỉ giảo', '比 (tỉ): so sánh, so với. 较 (giảo): so đo, đối chiếu.', 'Động từ, Giới từ, Phó từ', 'Trong cách nói “这次成绩比较差”, 比较 mang nghĩa “so sánh”.'),
    (3, 522, 'bút ký bản', '笔 (bút): bút, cây bút. 记 (ký): ghi, nhớ, ghi chép. 本 (bản): gốc; quyển (sách).', 'Danh từ', 'Trong cách nói “我的笔记本被别人拿走了”, 笔记本 mang nghĩa “sổ tay, vở ghi”.'),
    (3, 523, 'tỉ như', '比 (tỉ): so sánh, so với. 如 (như): như, giống như; nếu.', 'Động từ', 'Trong cách nói “比如冰变成水”, 比如 mang nghĩa “ví dụ như”.'),
    (3, 524, 'tỉ tái', '比 (tỉ): so sánh, so với. 赛 (tái): thi đấu, cuộc đua.', 'Động từ, Danh từ', 'Trong cách nói “每班出一名学生参加比赛”, 比赛 mang nghĩa “thi đấu”.'),
    (3, 525, 'tất tu', '必 (tất): ắt, tất nhiên, nhất định. 须 (tu): cần, phải; râu.', 'Phó từ', 'Trong cách nói “就必须先吸热”, 必须 mang nghĩa “phải, bắt buộc”.'),
    (3, 526, 'biến', '变 (biến): biến, thay đổi.', 'Động từ', 'Trong cách nói “他的身高和声音都变了”, 变 mang nghĩa “thay đổi”.'),
    (3, 527, 'biến', '遍 (biến): khắp; lượt.', 'Lượng từ', 'Trong cách nói “老师让我们把笔记再读一遍”, 遍 mang nghĩa “lần, lượt (từ đầu đến cuối)”.'),
    (3, 528, 'biến thành', '变 (biến): biến, thay đổi. 成 (thành): thành, nên, trở thành.', 'Động từ', 'Trong cách nói “水变成冰的时候”, 变成 mang nghĩa “trở thành”.'),
    (3, 529, 'biến hoá', '变 (biến): biến, thay đổi. 化 (hoá): biến đổi, giáo hoá.', 'Động từ, Danh từ', 'Trong cách nói “有什么变化”, 变化 mang nghĩa “biến đổi”.'),
    (3, 530, 'biểu diễn', '表 (biểu): bày tỏ, mặt ngoài; cái đồng hồ. 演 (diễn): trình diễn.', 'Động từ', 'Trong cách nói “今晚宾馆有表演”, 表演 mang nghĩa “biểu diễn”.'),
    (3, 531, 'biệt đích', '别 (biệt): khác; chia tách; chớ, đừng. 的 (đích): của; trợ từ định ngữ.', 'Đại từ', 'Trong cách nói “还有别的办法过河吗”, 别的 mang nghĩa “cái khác, khác”.'),
    (3, 532, 'biệt nhân', '别 (biệt): khác; chia tách; chớ, đừng. 人 (nhân): người.', 'Đại từ', 'Trong cách nói “我的笔记本被别人拿走了”, 别人 mang nghĩa “người khác”.'),
    (3, 533, 'tân quán', '宾 (tân): khách, tân khách. 馆 (quán): toà nhà lớn (quán, viện, sảnh).', 'Danh từ', 'Trong cách nói “今晚宾馆有表演”, 宾馆 mang nghĩa “khách sạn”.'),
    (3, 534, 'băng', '冰 (băng): băng, nước đá.', 'Danh từ', 'Trong cách nói “水变成冰的时候”, 冰 mang nghĩa “băng, nước đá”.'),
    (3, 535, 'băng kích lăng', '冰 (băng): băng, nước đá. 激 (kích): mạnh, dữ dội. 凌 (lăng): băng giá; vượt lên.', 'Danh từ', 'Trong cách nói “冰激凌在冰箱里”, 冰激凌 mang nghĩa “kem”.'),
    (3, 536, 'băng sương', '冰 (băng): băng, nước đá. 箱 (sương): cái hòm, thùng.', 'Danh từ', 'Trong cách nói “冰激凌在冰箱里”, 冰箱 mang nghĩa “tủ lạnh”.'),
    (3, 537, 'bệnh nhân', '病 (bệnh): bệnh, ốm đau. 人 (nhân): người.', 'Danh từ', 'Trong cách nói “隔壁的病人正在休息”, 病人 mang nghĩa “người bệnh”.'),
    (3, 538, 'bất đãn', '不 (bất): không (phủ định). 但 (đãn): nhưng, chỉ, song.', 'Liên từ', 'Trong cách nói “他不但认识我”, 不但 mang nghĩa “không những”.'),
    (3, 539, 'bất kiến', '不 (bất): không (phủ định). 见 (kiến): thấy, gặp.', 'Động từ', 'Trong cách nói “不久就不见了”, 不见 mang nghĩa “không thấy, biến mất”.'),
    (3, 540, 'bất dụng', '不 (bất): không (phủ định). 用 (dụng): dùng; cần.', 'Phó từ', 'Trong cách nói “妈妈不用着急”, 不用 mang nghĩa “không cần”.'),
    (3, 541, 'bất đồng', '不 (bất): không (phủ định). 同 (đồng): cùng, giống nhau.', 'Cụm từ', 'Trong cách nói “你和以前有点儿不同”, 不同 mang nghĩa “khác nhau”.'),
    (3, 542, 'bất cửu', '不 (bất): không (phủ định). 久 (cửu): lâu, lâu dài.', 'Tính từ', 'Trong cách nói “他出院后不久就回办公室上班了”, 不久 mang nghĩa “không lâu”.'),
    (3, 543, 'bất hành', '不 (bất): không (phủ định). 行 (hành): đi; được.', 'Động từ, Tính từ', 'Trong cách nói “这样办不行”, 不行 mang nghĩa “không được”.'),
    (3, 544, 'tài', '才 (tài): vừa mới; tài năng.', 'Phó từ', 'Trong cách nói “身体才会好起来”, 才 mang nghĩa “mới, mãi mới”.'),
    (3, 545, 'thái đơn', '菜 (thái): rau; món ăn. 单 (đơn): đơn, lẻ; tờ/bảng.', 'Danh từ', 'Trong cách nói “服务员把菜单放在客人面前”, 菜单 mang nghĩa “thực đơn”.'),
    (3, 546, 'tham gia', '参 (tham): tham dự, chen vào. 加 (gia): thêm, cộng vào.', 'Động từ', 'Trong cách nói “每班出一名学生参加比赛”, 参加 mang nghĩa “tham gia”.'),
    (3, 547, 'thảo', '草 (thảo): cỏ; sơ sài.', 'Danh từ', 'Trong cách nói “草地上的草差不多有十厘米高”, 草 mang nghĩa “cỏ”.'),
    (3, 548, 'thảo địa', '草 (thảo): cỏ; sơ sài. 地 (địa): đất, mặt đất; nơi.', 'Danh từ', 'Trong cách nói “草地上的草差不多有十厘米高”, 草地 mang nghĩa “bãi cỏ”.'),
    (3, 549, 'tằng', '层 (tằng): tầng, lớp.', 'Lượng từ', 'Trong cách nói “三层没电”, 层 mang nghĩa “tầng, lớp”.'),
    (3, 550, 'tra', '查 (tra): tra cứu, điều tra, kiểm tra.', 'Động từ', 'Trong cách nói “我坐在床上查这个词的意思”, 查 mang nghĩa “tra cứu, kiểm tra”.'),
    (3, 551, 'sai', '差 (sai): kém, thiếu; sai lệch.', 'Tính từ, Động từ', 'Trong cách nói “他比我差两分”, 差 mang nghĩa “kém”.'),
    (3, 552, 'sai bất đa', '差 (sai): kém, thiếu; sai lệch. 不 (bất): không (phủ định). 多 (đa): nhiều.', 'Tính từ, Phó từ', 'Trong cách nói “草地上的草差不多有十厘米高”, 差不多 mang nghĩa “gần như, xấp xỉ”.'),
    (3, 553, 'thường', '尝 (thường): nếm thử; từng (đã từng).', 'Động từ', 'Trong cách nói “尝一下”, 尝 mang nghĩa “nếm thử”.'),
    (3, 554, 'thường', '常 (thường): thường, hay; bình thường.', 'Phó từ', 'Trong cách nói “过去我们常回老家过节”, 常 mang nghĩa “thường”.'),
    (3, 555, 'thường kiến', '常 (thường): thường, hay; bình thường. 见 (kiến): thấy, gặp.', 'Cụm từ', 'Trong cách nói “词典里有很多常见的词和常用的句子”, 常见 mang nghĩa “thường gặp”.'),
    (3, 556, 'thường dụng', '常 (thường): thường, hay; bình thường. 用 (dụng): dùng; cần.', 'Cụm từ', 'Trong cách nói “词典里有很多常见的词和常用的句子”, 常用 mang nghĩa “thường dùng”.'),
    (3, 557, 'thường thường', '常 (thường): thường, hay; bình thường.', 'Phó từ', 'Trong cách nói “请尝尝我们常常做的鱼”, 常常 mang nghĩa “thường xuyên”.'),
    (3, 558, 'sấn sam', '衬 (sấn): lót trong; làm nền tôn lên. 衫 (sam): áo (mỏng, dài).', 'Danh từ', 'Trong cách nói “我常常穿这件蓝衬衫去上班”, 衬衫 mang nghĩa “áo sơ mi”.'),
    (3, 559, 'thành tích', '成 (thành): thành, nên, trở thành. 绩 (tích): thành tích; se sợi.', 'Danh từ', 'Trong cách nói “这次成绩比较差”, 成绩 mang nghĩa “thành tích, kết quả học tập”.'),
    (3, 560, 'thành thị', '城 (thành): thành, tường thành; thành phố. 市 (thị): chợ; thành phố.', 'Danh từ', 'Trong cách nói “这位名人住在城市的南边”, 城市 mang nghĩa “thành phố”.'),
    (3, 561, 'trì đáo', '迟 (trì): chậm, trễ. 到 (đáo): đến, tới.', 'Động từ', 'Trong cách nói “晚了会迟到”, 迟到 mang nghĩa “đến muộn”.'),
    (3, 562, 'xuất phát', '出 (xuất): ra, đi ra. 发 (phát): phát ra, khởi; tóc (fà).', 'Động từ', 'Trong cách nói “马上出发吧”, 出发 mang nghĩa “xuất phát”.'),
    (3, 563, 'xuất sinh', '出 (xuất): ra, đi ra. 生 (sinh): sinh ra, nảy sinh; sống.', 'Động từ', 'Trong cách nói “我出生在南方”, 出生 mang nghĩa “ra đời”.'),
    (3, 564, 'xuất viện', '出 (xuất): ra, đi ra. 院 (viện): viện, sân; toà nhà công.', 'Động từ', 'Trong cách nói “他出院后不久就回办公室上班了”, 出院 mang nghĩa “xuất viện”.'),
    (3, 565, 'sơ trung', '初 (sơ): ban đầu, lúc đầu. 中 (trung): giữa, trung tâm; trung học.', 'Danh từ', 'Trong cách nói “在北方读完初中”, 初中 mang nghĩa “trung học cơ sở”.'),
    (3, 566, 'trừ liễu', '除 (trừ): trừ, bỏ đi, ngoại trừ. 了 (liễu): thông suốt, xong; (trợ từ: le).', 'Giới từ', 'Trong cách nói “除了坐船”, 除了 mang nghĩa “ngoài, ngoại trừ”.'),
    (3, 567, 'thuyền', '船 (thuyền): thuyền, tàu.', 'Danh từ', 'Trong cách nói “除了坐船”, 船 mang nghĩa “thuyền, tàu”.'),
    (3, 568, 'xuân thiên', '春 (xuân): mùa xuân. 天 (thiên): trời, bầu trời; ngày.', 'Danh từ', 'Trong cách nói “春天来了”, 春天 mang nghĩa “mùa xuân”.'),
    (3, 569, 'từ điển', '词 (từ): từ, lời, ngôn từ. 典 (điển): sách chuẩn, điển tịch.', 'Danh từ', 'Trong cách nói “词典里有很多常见的词和常用的句子”, 词典 mang nghĩa “từ điển”.'),
    (3, 570, 'thông minh', '聪 (thông): tai nghe nhạy, thông minh. 明 (minh): sáng, rõ ràng, thông suốt.', 'Tính từ', 'Trong cách nói “这个小孩儿很聪明”, 聪明 mang nghĩa “thông minh”.'),
    (3, 571, 'đả tảo', '打 (đả): đánh, làm, gọi (điện). 扫 (tảo): quét.', 'Động từ', 'Trong cách nói “该把院子打扫干净了”, 打扫 mang nghĩa “quét dọn”.'),
    (3, 572, 'đả toán', '打 (đả): đánh, làm, gọi (điện). 算 (toán): tính toán, coi như.', 'Động từ, Danh từ', 'Trong cách nói “我打算拿回去换”, 打算 mang nghĩa “dự định”.'),
    (3, 573, 'đại khái', '大 (đại): to, lớn. 概 (khái): khái quát, đại thể.', 'Tính từ, Phó từ', 'Trong cách nói “大熊猫大概在睡觉”, 大概 mang nghĩa “khoảng, có lẽ”.'),
    (3, 574, 'đại nhân', '大 (đại): to, lớn. 人 (nhân): người.', 'Danh từ', 'Trong cách nói “大人也能穿”, 大人 mang nghĩa “người lớn”.'),
    (3, 575, 'đại tiểu', '大 (đại): to, lớn. 小 (tiểu): nhỏ, bé.', 'Danh từ', 'Trong cách nói “这两个蛋糕大小不一样”, 大小 mang nghĩa “kích cỡ”.'),
    (3, 576, 'đại hùng miêu', '大 (đại): to, lớn. 熊 (hùng): con gấu. 猫 (miêu): con mèo.', 'Danh từ', 'Trong cách nói “大熊猫大概在睡觉”, 大熊猫 mang nghĩa “gấu trúc lớn”.'),
    (3, 577, 'đại y', '大 (đại): to, lớn. 衣 (y): áo, quần áo.', 'Danh từ', 'Trong cách nói “穿上大衣再出去吧”, 大衣 mang nghĩa “áo khoác dài”.'),
    (3, 578, 'đới', '带 (đới): mang theo; dây, đai.', 'Động từ', 'Trong cách nói “休假需要带多少行李”, 带 mang nghĩa “mang theo, dẫn theo”.'),
    (3, 579, 'đảm tâm', '担 (đảm): gánh, gánh vác, đảm đương. 心 (tâm): tim, lòng, tâm.', 'Động từ', 'Trong cách nói “不用担心”, 担心 mang nghĩa “lo lắng”.'),
    (3, 580, 'đản cao', '蛋 (đản): trứng. 糕 (cao): bánh (từ bột gạo).', 'Danh từ', 'Trong cách nói “这两个蛋糕大小不一样”, 蛋糕 mang nghĩa “bánh ngọt, bánh kem”.'),
    (3, 581, 'đương nhiên', '当 (đương): đáng, đảm nhận; ngay lúc. 然 (nhiên): như vậy; đúng vậy.', 'Phó từ', 'Trong cách nói “当然可以带朋友来”, 当然 mang nghĩa “đương nhiên”.'),
    (3, 582, 'đáo xứ', '到 (đáo): đến, tới. 处 (xứ): nơi, chỗ; xử lý.', 'Phó từ', 'Trong cách nói “我到处找我的卡”, 到处 mang nghĩa “khắp nơi”.'),
    (3, 583, 'đắc', '得 (đắc): được, đạt được; (trợ từ bổ ngữ).', 'Động từ', 'Dùng như động từ khi nói về kết quả hoặc số điểm đạt được.'),
    (3, 584, 'đắc đáo', '得 (đắc): được, đạt được; (trợ từ bổ ngữ). 到 (đáo): đến, tới.', 'Động từ', 'Trong cách nói “只要努力就有机会得到好成绩”, 得到 mang nghĩa “nhận được”.'),
    (3, 585, 'đắc phân', '得 (đắc): được, đạt được; (trợ từ bổ ngữ). 分 (phân): phút; chia ra.', 'Động từ, Danh từ', 'Trong cách nói “我们队又得分了”, 得分 mang nghĩa “ghi điểm”.'),
    (3, 586, 'đích thoại', '的 (đích): của; trợ từ định ngữ. 话 (thoại): lời nói, câu nói.', 'Trợ từ', 'Trong cách nói “明天天气晴的话”, 的话 mang nghĩa “nếu… (đặt cuối vế điều kiện)”.'),
    (3, 587, 'đắc', '得 (đắc): được, đạt được; (trợ từ bổ ngữ).', 'Động từ', 'Đặt trước động từ để nói một việc buộc phải làm.'),
    (3, 588, 'đăng', '灯 (đăng): đèn, ngọn đèn.', 'Danh từ', 'Trong cách nói “请打开灯”, 灯 mang nghĩa “đèn”.'),
    (3, 589, 'địa', '地 (địa): đất, mặt đất; nơi.', 'Danh từ', 'Dùng như danh từ chỉ mặt đất, nền nhà.'),
    (3, 590, 'địa điểm', '地 (địa): đất, mặt đất; nơi. 点 (điểm): giờ; chấm điểm.', 'Danh từ', 'Trong cách nói “请在地图上找出见面的地点”, 地点 mang nghĩa “địa điểm”.'),
    (3, 591, 'địa phương', '地 (địa): đất, mặt đất; nơi. 方 (phương): phương, vuông; cách thức.', 'Danh từ', 'Trong cách nói “这个地方停电了”, 地方 mang nghĩa “nơi, chỗ”.'),
    (3, 592, 'địa đồ', '地 (địa): đất, mặt đất; nơi. 图 (đồ): tranh, bản đồ, hình vẽ.', 'Danh từ', 'Trong cách nói “请在地图上找出见面的地点”, 地图 mang nghĩa “bản đồ”.'),
    (3, 593, 'điện', '电 (điện): điện; điện lực.', 'Danh từ', 'Trong cách nói “三层没电”, 电 mang nghĩa “điện”.'),
    (3, 594, 'điện thê', '电 (điện): điện; điện lực. 梯 (thê): cái thang, bậc thang.', 'Danh từ', 'Trong cách nói “电梯不能用”, 电梯 mang nghĩa “thang máy”.'),
    (3, 595, 'điện tử thư', '电 (điện): điện; điện lực. 子 (tử): (hậu tố danh từ). 书 (thư): sách, viết.', 'Danh từ', 'Trong cách nói “电子书存在手机里”, 电子书 mang nghĩa “sách điện tử”.'),
    (3, 596, 'đâu', '丢 (đâu): làm mất.', 'Động từ', 'Trong cách nói “不容易丢”, 丢 mang nghĩa “làm mất”.'),
    (3, 597, 'đông', '东 (đông): phía đông.', 'Danh từ', 'Trong cách nói “我向东走”, 东 mang nghĩa “đông (phương hướng)”.'),
    (3, 598, 'đông bắc', '东 (đông): phía đông. 北 (bắc): hướng Bắc.', 'Danh từ', 'Trong cách nói “再向东北走”, 东北 mang nghĩa “đông bắc”.'),
    (3, 599, 'đông phương', '东 (đông): phía đông. 方 (phương): phương, vuông; cách thức.', 'Danh từ', 'Trong cách nói “太阳从东方升起”, 东方 mang nghĩa “phương Đông”.'),
    (3, 600, 'đông nam', '东 (đông): phía đông. 南 (nam): hướng Nam.', 'Danh từ', 'Trong cách nói “河向东南流去”, 东南 mang nghĩa “đông nam”.'),
    (3, 601, 'đông thiên', '冬 (đông): mùa đông. 天 (thiên): trời, bầu trời; ngày.', 'Danh từ', 'Trong cách nói “北方的冬天比较冷”, 冬天 mang nghĩa “mùa đông”.'),
    (3, 602, 'đổng đắc', '懂 (đổng): hiểu, thông hiểu. 得 (đắc): được, đạt được; (trợ từ bổ ngữ).', 'Động từ', 'Trong cách nói “在动物园工作的人懂得怎样保护动物”, 懂得 mang nghĩa “hiểu, biết”.'),
    (3, 603, 'động vật', '动 (động): chuyển động, làm; cử động. 物 (vật): vật, đồ vật, sinh vật.', 'Danh từ', 'Trong cách nói “在动物园工作的人懂得怎样保护动物”, 动物 mang nghĩa “động vật”.'),
    (3, 604, 'động vật viên', '动 (động): chuyển động, làm; cử động. 物 (vật): vật, đồ vật, sinh vật. 园 (viên): vườn, khu vườn.', 'Danh từ', 'Trong cách nói “在动物园工作的人懂得怎样保护动物”, 动物园 mang nghĩa “sở thú”.'),
    (3, 605, 'đoản', '短 (đoản): ngắn.', 'Tính từ', 'Trong cách nói “哪条路最短”, 短 mang nghĩa “ngắn”.'),
    (3, 606, 'đoản khố', '短 (đoản): ngắn. 裤 (khố): quần.', 'Danh từ', 'Trong cách nói “这条短裤太短”, 短裤 mang nghĩa “quần ngắn”.'),
    (3, 607, 'đoạn', '段 (đoạn): đoạn, khúc, quãng.', 'Lượng từ', 'Trong cách nói “这段对话很短”, 段 mang nghĩa “đoạn”.'),
    (3, 608, 'đoàn luyện', '锻 (đoàn): rèn (kim loại). 炼 (luyện): luyện, tôi (kim loại).', 'Động từ', 'Trong cách nói “我们去公园锻炼”, 锻炼 mang nghĩa “rèn luyện, tập thể dục”.'),
    (3, 609, 'đối thoại', '对 (đối): đúng; đối với, đối diện. 话 (thoại): lời nói, câu nói.', 'Động từ', 'Trong cách nói “这段对话很短”, 对话 mang nghĩa “đối thoại”.'),
    (3, 610, 'ngạ', '饿 (ngạ): đói, đói bụng.', 'Tính từ', 'Trong cách nói “我饿了”, 饿 mang nghĩa “đói”.'),
    (3, 611, 'nhi thả', '而 (nhi): mà, và (nối ý). 且 (thả): vả lại, hơn nữa.', 'Liên từ', 'Trong cách nói “而且很容易懂”, 而且 mang nghĩa “hơn nữa”.'),
    (3, 612, 'nhĩ đoá', '耳 (nhĩ): tai, lỗ tai. 朵 (đoá): đoá, cụm (lượng từ hoa).', 'Danh từ', 'Trong cách nói “耳朵会疼”, 耳朵 mang nghĩa “tai”.'),
    (3, 613, 'nhĩ cơ', '耳 (nhĩ): tai, lỗ tai. 机 (cơ): máy móc; cơ hội.', 'Danh từ', 'Trong cách nói “耳机戴得太久”, 耳机 mang nghĩa “tai nghe”.'),
    (3, 614, 'phát', '发 (phát): phát ra, khởi; tóc (fà).', 'Động từ', 'Trong cách nói “他发烧了”, 发 mang nghĩa “gửi, phát”.'),
    (3, 615, 'phát thiêu', '发 (phát): phát ra, khởi; tóc (fà). 烧 (thiêu): đốt, nướng; sốt.', 'Động từ', 'Trong cách nói “他发烧了”, 发烧 mang nghĩa “bị sốt”.'),
    (3, 616, 'phát sinh', '发 (phát): phát ra, khởi; tóc (fà). 生 (sinh): sinh ra, nảy sinh; sống.', 'Động từ', 'Trong cách nói “这里发生了什么事情”, 发生 mang nghĩa “xảy ra”.'),
    (3, 617, 'phát hiện', '发 (phát): phát ra, khởi; tóc (fà). 现 (hiện): hiện ra; hiện tại.', 'Động từ', 'Trong cách nói “才发现名字被写错了”, 发现 mang nghĩa “phát hiện”.'),
    (3, 618, 'phát triển', '发 (phát): phát ra, khởi; tóc (fà). 展 (triển): mở rộng.', 'Động từ', 'Trong cách nói “高铁的发展让旅行更方便了”, 发展 mang nghĩa “phát triển”.'),
    (3, 619, 'phương tiện', '方 (phương): phương, vuông; cách thức. 便 (tiện): tiện lợi.', 'Tính từ', 'Trong cách nói “高铁的发展让旅行更方便了”, 方便 mang nghĩa “thuận tiện”.'),
    (3, 620, 'phương tiện diện', '方 (phương): phương, vuông; cách thức. 便 (tiện): tiện lợi. 面 (diện): mặt, bề mặt.', 'Danh từ', 'Trong cách nói “可以吃一碗方便面吗”, 方便面 mang nghĩa “mì ăn liền”.'),
    (3, 621, 'phương pháp', '方 (phương): phương, vuông; cách thức. 法 (pháp): phép, cách thức, luật.', 'Danh từ', 'Trong cách nói “再选合适的方法”, 方法 mang nghĩa “phương pháp”.'),
    (3, 622, 'phương hướng', '方 (phương): phương, vuông; cách thức. 向 (hướng): hướng về, về phía.', 'Danh từ', 'Trong cách nói “方向找对了”, 方向 mang nghĩa “phương hướng”.'),
    (3, 623, 'phòng tử', '房 (phòng): phòng, nhà. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “学校附近的房子有一个小花园”, 房子 mang nghĩa “nhà, căn nhà”.'),
    (3, 624, 'phóng', '放 (phóng): đặt để; thả; phát ra.', 'Động từ', 'Trong cách nói “我在冰箱里放了冰激凌”, 放 mang nghĩa “đặt, để”.'),
    (3, 625, 'phóng giả', '放 (phóng): đặt để; thả; phát ra. 假 (giả): kỳ nghỉ; nghỉ phép.', 'Động từ', 'Trong cách nói “星期日学校放假”, 放假 mang nghĩa “được nghỉ, nghỉ lễ”.'),
    (3, 626, 'phóng tâm', '放 (phóng): đặt để; thả; phát ra. 心 (tâm): tim, lòng, tâm.', 'Động từ', 'Trong cách nói “放心”, 放心 mang nghĩa “yên tâm”.'),
    (3, 627, 'phóng học', '放 (phóng): đặt để; thả; phát ra. 学 (học): học.', 'Động từ', 'Trong cách nói “放学后在房子附近等我”, 放学 mang nghĩa “tan trường”.'),
    (3, 628, 'phân khai', '分 (phân): phút; chia ra. 开 (khai): mở, khai mở; lái xe.', 'Động từ', 'Trong cách nói “别分开走”, 分开 mang nghĩa “tách ra, chia ra”.'),
    (3, 629, 'phong', '风 (phong): gió.', 'Danh từ', 'Trong cách nói “风又起了”, 风 mang nghĩa “gió”.'),
    (3, 630, 'phong', '封 (phong): niêm phong; bức (thư).', 'Lượng từ', 'Đặt sau số đếm và trước 信 hoặc 邮件 để đếm thư.'),
    (3, 631, 'phu thê', '夫 (phu): người đàn ông, chồng. 妻 (thê): vợ.', 'Danh từ', 'Trong cách nói “这封信是那对夫妻写给邻居的”, 夫妻 mang nghĩa “vợ chồng”.'),
    (3, 632, 'phục vụ', '服 (phục): mặc; phục tùng; (trong 衣服). 务 (vụ): công việc, nhiệm vụ; chuyên lo.', 'Động từ', 'Trong cách nói “他们夫妻服务很热情”, 服务 mang nghĩa “phục vụ”.'),
    (3, 633, 'phụ cận', '附 (phụ): kề, gắn vào, phụ thuộc. 近 (cận): gần.', 'Danh từ', 'Trong cách nói “学校附近的房子有一个小花园”, 附近 mang nghĩa “vùng lân cận”.'),
    (3, 634, 'phục tập', '复 (phục): lặp lại, quay lại; trả lời. 习 (tập): luyện tập, quen.', 'Động từ', 'Trong cách nói “开学以后我们经常一起复习”, 复习 mang nghĩa “ôn tập”.'),
    (3, 635, 'cai', '该 (cai): nên, đáng; cái đó.', 'Động từ', 'Trong cách nói “你该复习了”, 该 mang nghĩa “nên, đến lượt”.'),
    (3, 636, 'can tịnh', '干 (can): khô. 净 (tịnh): sạch, trong.', 'Tính từ', 'Trong cách nói “把地扫干净”, 干净 mang nghĩa “sạch sẽ”.'),
    (3, 637, 'cảm hứng thú', '感 (cảm): cảm thấy, cảm động. 兴 (hứng): hứng thú. 趣 (thú): thú vị, hứng thú.', 'Cụm từ', 'Trong cách nói “我对历史感兴趣”, 感兴趣 mang nghĩa “thấy hứng thú”.'),
    (3, 638, 'cảm đáo', '感 (cảm): cảm thấy, cảm động. 到 (đáo): đến, tới.', 'Động từ', 'Trong cách nói “学起来感到很开心”, 感到 mang nghĩa “cảm thấy”.'),
    (3, 639, 'cảm mạo', '感 (cảm): cảm thấy, cảm động. 冒 (mạo): xông ra, bốc lên; liều.', 'Danh từ, Động từ', 'Trong cách nói “我刚感冒”, 感冒 mang nghĩa “cảm lạnh”.'),
    (3, 640, 'cán', '干 (cán): làm việc.', 'Động từ', 'Trong cách nói “你干什么工作”, 干 mang nghĩa “làm, làm việc”.'),
    (3, 641, 'cương', '刚 (cương): vừa mới; cứng rắn.', 'Phó từ', 'Trong cách nói “我刚干完活就开始刮风了”, 刚 mang nghĩa “vừa mới”.'),
    (3, 642, 'cương tài', '刚 (cương): vừa mới; cứng rắn. 才 (tài): vừa mới; tài năng.', 'Danh từ', 'Trong cách nói “刚才经理说”, 刚才 mang nghĩa “lúc nãy”.'),
    (3, 643, 'cương cương', '刚 (cương): vừa mới; cứng rắn.', 'Phó từ', 'Trong cách nói “他刚刚下高铁”, 刚刚 mang nghĩa “vừa mới đây”.'),
    (3, 644, 'cao thiết', '高 (cao): cao. 铁 (thiết): sắt, thép.', 'Danh từ', 'Trong cách nói “高铁的发展让旅行更方便了”, 高铁 mang nghĩa “tàu cao tốc”.'),
    (3, 645, 'căn cứ', '根 (căn): gốc, rễ; cội nguồn. 据 (cứ): dựa vào, căn cứ; chiếm.', 'Động từ, Giới từ', 'Trong cách nói “根据名单”, 根据 mang nghĩa “căn cứ vào”.'),
    (3, 646, 'cánh', '更 (cánh): càng, hơn nữa; thay đổi.', 'Phó từ', 'Trong cách nói “高铁的发展让旅行更方便了”, 更 mang nghĩa “hơn, càng”.'),
    (3, 647, 'công cân', '公 (công): chung, công cộng. 斤 (cân): cân (nửa kg); cái rìu.', 'Lượng từ', 'Trong cách nói “刚才我根据价格选了两公斤苹果”, 公斤 mang nghĩa “kilôgam”.'),
    (3, 648, 'công viên', '公 (công): chung, công cộng. 园 (viên): vườn, khu vườn.', 'Danh từ', 'Trong cách nói “男孩儿和女孩儿在公园里踢球”, 公园 mang nghĩa “công viên”.'),
    (3, 649, 'công tác nhật', '工 (công): công việc; thợ. 作 (tác): làm, tạo ra. 日 (nhật): ngày; mặt trời.', 'Danh từ', 'Trong cách nói “工作日我买一公斤苹果”, 工作日 mang nghĩa “ngày làm việc”.'),
    (3, 650, 'cố sự', '故 (cố): cũ, xưa; cớ sự. 事 (sự): việc, sự việc.', 'Danh từ', 'Trong cách nói “请给孩子讲一个故事”, 故事 mang nghĩa “câu chuyện”.'),
    (3, 651, 'quát', '刮 (quát): cào, gọt; (gió) thổi.', 'Động từ', 'Trong cách nói “外面在刮风”, 刮 mang nghĩa “thổi (gió)”.'),
    (3, 652, 'quan', '关 (quan): đóng (cửa); liên quan.', 'Động từ', 'Trong cách nói “请关窗”, 关 mang nghĩa “đóng, tắt”.'),
    (3, 653, 'quan cơ', '关 (quan): đóng (cửa); liên quan. 机 (cơ): máy móc; cơ hội.', 'Động từ', 'Trong cách nói “开会前请关机”, 关机 mang nghĩa “tắt máy”.'),
    (3, 654, 'quan hệ', '关 (quan): đóng (cửa); liên quan. 系 (hệ): buộc, cột; hệ thống; quan hệ.', 'Danh từ', 'Trong cách nói “家人的关系也很好”, 关系 mang nghĩa “quan hệ”.'),
    (3, 655, 'quan tâm', '关 (quan): đóng (cửa); liên quan. 心 (tâm): tim, lòng, tâm.', 'Động từ', 'Trong cách nói “她关心家人的健康”, 关心 mang nghĩa “quan tâm”.'),
    (3, 656, 'quan vu', '关 (quan): đóng (cửa); liên quan. 于 (vu): ở, tại; đối với.', 'Giới từ', 'Trong cách nói “关于这个国家的文化”, 关于 mang nghĩa “về, liên quan đến”.'),
    (3, 657, 'quan chú', '关 (quan): đóng (cửa); liên quan. 注 (chú): rót, dồn, chú vào.', 'Động từ', 'Trong cách nói “我一直很关注”, 关注 mang nghĩa “chú ý, theo dõi”.'),
    (3, 658, 'quốc gia', '国 (quốc): nước, quốc gia. 家 (gia): nhà, gia đình.', 'Danh từ', 'Trong cách nói “你想去哪个国家”, 国家 mang nghĩa “quốc gia”.'),
    (3, 659, 'quá tiết', '过 (quá): qua, vượt qua, trải qua. 节 (tiết): đốt, đoạn; dịp lễ.', 'Động từ', 'Trong cách nói “过去我们常回老家过节”, 过节 mang nghĩa “đón lễ, ăn lễ”.'),
    (3, 660, 'quá khứ', '过 (quá): qua, vượt qua, trải qua. 去 (khứ): đi, đi đến.', 'Danh từ', 'Dùng như danh từ chỉ thời gian trước đây.'),
    (3, 661, 'hải', '海 (hải): biển.', 'Danh từ', 'Trong cách nói “我第一次看见海”, 海 mang nghĩa “biển”.'),
    (3, 662, 'hại phạ', '害 (hại): hại, tổn hại. 怕 (phạ): sợ.', 'Động từ', 'Trong cách nói “既高兴又有点儿害怕”, 害怕 mang nghĩa “sợ hãi”.'),
    (3, 663, 'hảo đa', '好 (hảo): tốt, đẹp, hay. 多 (đa): nhiều.', 'Số từ', 'Trong cách nói “今天来了好多游客”, 好多 mang nghĩa “rất nhiều”.'),
    (3, 664, 'hảo cửu', '好 (hảo): tốt, đẹp, hay. 久 (cửu): lâu, lâu dài.', 'Tính từ', 'Trong cách nói “好久没有见她了”, 好久 mang nghĩa “rất lâu”.'),
    (3, 665, 'hảo tượng', '好 (hảo): tốt, đẹp, hay. 像 (tượng): giống, tựa như; hình tượng.', 'Động từ, Phó từ', 'Trong cách nói “好像比昨天还多”, 好像 mang nghĩa “hình như, giống như”.'),
    (3, 666, 'hiệu mã', '号 (hiệu): số hiệu; hô gọi; ngày. 码 (mã): mã, số hiệu.', 'Danh từ', 'Trong cách nói “她的号码好像换了”, 号码 mang nghĩa “số, dãy số”.'),
    (3, 667, 'hà', '河 (hà): sông.', 'Danh từ', 'Trong cách nói “早上在河边练太极拳很凉快”, 河 mang nghĩa “sông”.'),
    (3, 668, 'hợp thích', '合 (hợp): hợp, khớp lại. 适 (thích): phù hợp.', 'Tính từ', 'Trong cách nói “再选合适的方法”, 合适 mang nghĩa “phù hợp”.'),
    (3, 669, 'hắc bản', '黑 (hắc): đen, màu đen; tối. 板 (bản): tấm ván, tấm bảng.', 'Danh từ', 'Trong cách nói “请把电话号码写在黑板上”, 黑板 mang nghĩa “bảng đen”.'),
    (3, 670, 'hồng lục đăng', '红 (hồng): màu đỏ; hồng. 绿 (lục): màu xanh lá cây. 灯 (đăng): đèn, ngọn đèn.', 'Danh từ', 'Trong cách nói “过马路先看红绿灯”, 红绿灯 mang nghĩa “đèn giao thông”.'),
    (3, 671, 'hậu lai', '后 (hậu): sau, phía sau. 来 (lai): đến, tới.', 'Danh từ', 'Trong cách nói “后来他成了画家”, 后来 mang nghĩa “sau đó, về sau”.'),
    (3, 672, 'hậu niên', '后 (hậu): sau, phía sau. 年 (niên): năm.', 'Danh từ', 'Trong cách nói “后年还要办画展”, 后年 mang nghĩa “năm sau nữa”.'),
    (3, 673, 'hậu thiên', '后 (hậu): sau, phía sau. 天 (thiên): trời, bầu trời; ngày.', 'Danh từ', 'Trong cách nói “后天出国”, 后天 mang nghĩa “ngày kia”.'),
    (3, 674, 'hộ chiếu', '护 (hộ): bảo vệ, che chở. 照 (chiếu): soi, chiếu; chụp (ảnh).', 'Danh từ', 'Trong cách nói “记得检查护照”, 护照 mang nghĩa “hộ chiếu”.'),
    (3, 675, 'hoa viên', '花 (hoa): hoa; tiêu xài; hoa mắt. 园 (viên): vườn, khu vườn.', 'Danh từ', 'Trong cách nói “学校附近的房子有一个小花园”, 花园 mang nghĩa “vườn hoa”.'),
    (3, 676, 'hoạ gia', '画 (hoạ): vẽ; tranh, bức hoạ. 家 (gia): nhà, gia đình.', 'Danh từ', 'Trong cách nói “后来他成了画家”, 画家 mang nghĩa “họa sĩ”.'),
    (3, 677, 'hoan nghênh', '欢 (hoan): vui mừng, hân hoan. 迎 (nghênh): nghênh đón, ra đón.', 'Động từ', 'Trong cách nói “这位司机受到游客的欢迎”, 欢迎 mang nghĩa “hoan nghênh, chào đón”.'),
    (3, 678, 'hoàn', '还 (hoàn): vẫn, còn; tạm được.', 'Động từ', 'Dùng trước đồ vật được trả hoặc trước 给 và tên người nhận.'),
    (3, 679, 'hoàn cảnh', '环 (hoàn): vòng, vây quanh. 境 (cảnh): biên giới, vùng; cảnh ngộ.', 'Danh từ', 'Trong cách nói “这里的环境很安静”, 环境 mang nghĩa “môi trường”.'),
    (3, 680, 'hoán', '换 (hoán): đổi, thay.', 'Động từ', 'Trong cách nói “换一条吧”, 换 mang nghĩa “đổi, thay”.'),
    (3, 681, 'hoàng sắc', '黄 (hoàng): màu vàng. 色 (sắc): màu, sắc; sắc thái.', 'Danh từ', 'Trong cách nói “请用黄色的笔写下你的回答”, 黄色 mang nghĩa “màu vàng”.'),
    (3, 682, 'hồi đáp', '回 (hồi): quay lại, trở về. 答 (đáp): đáp, trả lời.', 'Động từ', 'Trong cách nói “请用黄色的笔写下你的回答”, 回答 mang nghĩa “trả lời”.'),
    (3, 683, 'hội', '会 (hội): biết; họp; chốc lát.', 'Danh từ', 'Dùng như danh từ trong các cụm như 有个会 khi nói về một cuộc họp.'),
    (3, 684, 'hội nghị', '会 (hội): biết; họp; chốc lát. 议 (nghị): bàn bạc, nghị luận.', 'Danh từ', 'Trong cách nói “会议结束后再开机”, 会议 mang nghĩa “hội nghị, cuộc họp”.'),
    (3, 685, 'hoặc', '或 (hoặc): có lẽ; một trong số; hoặc.', 'Liên từ', 'Trong cách nói “你可以坐汽车或地铁”, 或 mang nghĩa “hoặc”.'),
    (3, 686, 'hoặc giả', '或 (hoặc): có lẽ; một trong số; hoặc. 者 (giả): (người/cái) ... ; kẻ làm gì.', 'Liên từ', 'Trong cách nói “周末我们打网球或者羽毛球”, 或者 mang nghĩa “hoặc là”.'),
    (3, 687, 'kê', '鸡 (kê): con gà.', 'Danh từ', 'Trong cách nói “奶奶养的鸡几乎每天都下蛋”, 鸡 mang nghĩa “gà”.'),
    (3, 688, 'kỷ hồ', '几 (kỷ): mấy, bao nhiêu. 乎 (hồ): trợ từ (ư, vậy).', 'Phó từ', 'Trong cách nói “奶奶养的鸡几乎每天都下蛋”, 几乎 mang nghĩa “hầu như”.'),
    (3, 689, 'cơ hội', '机 (cơ): máy móc; cơ hội. 会 (hội): biết; họp; chốc lát.', 'Danh từ', 'Trong cách nói “我几乎没有机会去农场看鸡”, 机会 mang nghĩa “cơ hội”.'),
    (3, 690, 'cực', '极 (cực): cực, tột cùng, rất.', 'Phó từ', 'Trong cách nói “他却开心极了”, 极 mang nghĩa “cực kỳ”.'),
    (3, 691, 'cấp', '急 (cấp): gấp, vội; nóng lòng.', 'Tính từ, Động từ', 'Trong cách nói “我急着赶车”, 急 mang nghĩa “gấp, sốt ruột”.'),
    (3, 692, 'ký', '记 (ký): ghi, nhớ, ghi chép.', 'Động từ', 'Trong cách nói “这条街的名字好记”, 记 mang nghĩa “ghi, nhớ”.'),
    (3, 693, 'quý', '季 (quý): mùa; em út.', 'Danh từ', 'Trong cách nói “一年有四季”, 季 mang nghĩa “mùa, quý”.'),
    (3, 694, 'quý tiết', '季 (quý): mùa; em út. 节 (tiết): đốt, đoạn; dịp lễ.', 'Danh từ', 'Trong cách nói “你最喜欢哪个季节”, 季节 mang nghĩa “mùa trong năm”.'),
    (3, 695, 'gia', '加 (gia): thêm, cộng vào.', 'Động từ', 'Trong cách nói “请加水”, 加 mang nghĩa “thêm, cộng”.'),
    (3, 696, 'giả kỳ', '假 (giả): kỳ nghỉ; nghỉ phép. 期 (kỳ): kỳ hạn, thời kỳ.', 'Danh từ', 'Trong cách nói “假期里我也坚持每天练习汉语”, 假期 mang nghĩa “kỳ nghỉ”.'),
    (3, 697, 'kiên trì', '坚 (kiên): cứng, vững chắc. 持 (trì): cầm, nắm giữ.', 'Động từ', 'Trong cách nói “假期里我也坚持每天练习汉语”, 坚持 mang nghĩa “kiên trì”.'),
    (3, 698, 'kiểm tra', '检 (kiểm): xem xét, soát; kiểm tra. 查 (tra): tra cứu, điều tra, kiểm tra.', 'Động từ', 'Trong cách nói “记得检查护照”, 检查 mang nghĩa “kiểm tra”.'),
    (3, 699, 'giản đơn', '简 (giản): đơn giản, gọn; thẻ tre. 单 (đơn): đơn, lẻ; tờ/bảng.', 'Tính từ', 'Trong cách nói “很简单”, 简单 mang nghĩa “đơn giản”.'),
    (3, 700, 'kiểm phiếu', '检 (kiểm): xem xét, soát; kiểm tra. 票 (phiếu): vé, phiếu.', 'Động từ', 'Trong cách nói “检票后在车上见面吧”, 检票 mang nghĩa “soát vé”.'),
    (3, 701, 'kiện khang', '健 (kiện): khoẻ, cường tráng. 康 (khang): an khang, khoẻ mạnh.', 'Tính từ', 'Trong cách nói “为了你的健康”, 健康 mang nghĩa “khỏe mạnh”.'),
    (3, 702, 'kiến diện', '见 (kiến): thấy, gặp. 面 (diện): mặt, bề mặt.', 'Động từ', 'Trong cách nói “检票后在车上见面吧”, 见面 mang nghĩa “gặp mặt”.'),
    (3, 703, 'giảng', '讲 (giảng): giảng giải, nói.', 'Động từ', 'Trong cách nói “请给孩子讲一个故事”, 讲 mang nghĩa “nói, kể, giảng”.'),
    (3, 704, 'giác', '角 (giác): góc; hào.', 'Lượng từ', 'Một 角 bằng một phần mười nhân dân tệ.'),
    (3, 705, 'cước', '脚 (cước): bàn chân.', 'Danh từ', 'Trong cách nói “你的脚还疼吗”, 脚 mang nghĩa “bàn chân”.'),
    (3, 706, 'tiếp', '接 (tiếp): đón, nhận, nối tiếp.', 'Động từ', 'Trong cách nói “我去街口接你”, 接 mang nghĩa “đón”.'),
    (3, 707, 'nhai', '街 (nhai): phố, đường phố.', 'Danh từ', 'Trong cách nói “这条街的名字好记”, 街 mang nghĩa “phố”.'),
    (3, 708, 'tiết', '节 (tiết): đốt, đoạn; dịp lễ.', 'Lượng từ, Danh từ', 'Trong cách nói “过去我们常回老家过节”, 节 mang nghĩa “tiết (học)”.'),
    (3, 709, 'kết hôn', '结 (kết): buộc, thắt, kết lại. 婚 (hôn): cưới hỏi, hôn nhân.', 'Động từ', 'Trong cách nói “我们去看结婚的照片”, 结婚 mang nghĩa “kết hôn”.'),
    (3, 710, 'tiết mục', '节 (tiết): đốt, đoạn; dịp lễ. 目 (mục): mắt; mục.', 'Danh từ', 'Trong cách nói “节日的晚会上有很多精彩的节目”, 节目 mang nghĩa “chương trình”.'),
    (3, 711, 'tiết nhật', '节 (tiết): đốt, đoạn; dịp lễ. 日 (nhật): ngày; mặt trời.', 'Danh từ', 'Trong cách nói “节日的晚会上有很多精彩的节目”, 节日 mang nghĩa “ngày lễ”.'),
    (3, 712, 'kết thúc', '结 (kết): buộc, thắt, kết lại. 束 (thúc): bó, buộc lại; bó (lượng từ).', 'Động từ', 'Trong cách nói “会议结束后再开机”, 结束 mang nghĩa “kết thúc”.'),
    (3, 713, 'giải quyết', '解 (giải): mổ xẻ, gỡ, giải thích. 决 (quyết): quyết định, dứt khoát.', 'Động từ', 'Trong cách nói “这对姐妹一起解决了那道难题”, 解决 mang nghĩa “giải quyết”.'),
    (3, 714, 'tỉ muội', '姐 (tỉ): chị, chị gái. 妹 (muội): em gái.', 'Danh từ', 'Trong cách nói “这对姐妹一起解决了那道难题”, 姐妹 mang nghĩa “chị em gái”.'),
    (3, 715, 'tá', '借 (tá): mượn, cho mượn, nhờ.', 'Động từ', 'Trong cách nói “下节课我想借你的笔记”, 借 mang nghĩa “mượn”.'),
    (3, 716, 'cân', '斤 (cân): cân (nửa kg); cái rìu.', 'Lượng từ', 'Đặt sau số để chỉ khối lượng. Ở Trung Quốc đại lục, một 斤 bằng 500 gam.'),
    (3, 717, 'kinh quá', '经 (kinh): trải qua; sợi dọc; kinh điển. 过 (quá): qua, vượt qua, trải qua.', 'Động từ, Danh từ', 'Trong cách nói “经过银行时”, 经过 mang nghĩa “đi qua”.'),
    (3, 718, 'kinh lý', '经 (kinh): trải qua; sợi dọc; kinh điển. 理 (lý): sắp xếp; lẽ phải, đạo lý.', 'Danh từ', 'Trong cách nói “刚才经理说”, 经理 mang nghĩa “người quản lý”.'),
    (3, 719, 'cửu', '久 (cửu): lâu, lâu dài.', 'Tính từ', 'Trong cách nói “这瓶酒放了很久了”, 久 mang nghĩa “lâu”.'),
    (3, 720, 'tửu', '酒 (tửu): rượu.', 'Danh từ', 'Trong cách nói “这瓶酒放了很久了”, 酒 mang nghĩa “rượu”.'),
    (3, 721, 'cựu', '旧 (cựu): cũ, xưa.', 'Tính từ', 'Trong cách nói “用这个旧本子写两句话吧”, 旧 mang nghĩa “cũ”.'),
    (3, 722, 'cú', '句 (cú): câu.', 'Lượng từ', 'Trong cách nói “用这个旧本子写两句话吧”, 句 mang nghĩa “câu (lượng từ)”.'),
    (3, 723, 'cú tử', '句 (cú): câu. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “词典里有很多常见的词和常用的句子”, 句子 mang nghĩa “câu văn, câu nói”.'),
    (3, 724, 'quyết định', '决 (quyết): quyết định, dứt khoát. 定 (định): định, ổn định, chắc chắn.', 'Động từ, Danh từ', 'Trong cách nói “我们决定周五开会”, 决定 mang nghĩa “quyết định”.'),
    (3, 725, 'tạp', '卡 (tạp): thẻ (card); mắc kẹt.', 'Danh từ', 'Trong cách nói “我到处找我的卡”, 卡 mang nghĩa “thẻ”.'),
    (3, 726, 'khai hoa', '开 (khai): mở, khai mở; lái xe. 花 (hoa): hoa; tiêu xài; hoa mắt.', 'Động từ', 'Trong cách nói “树都开花了”, 开花 mang nghĩa “nở hoa”.'),
    (3, 727, 'khai hội', '开 (khai): mở, khai mở; lái xe. 会 (hội): biết; họp; chốc lát.', 'Động từ', 'Trong cách nói “我们决定周五开会”, 开会 mang nghĩa “họp”.'),
    (3, 728, 'khai cơ', '开 (khai): mở, khai mở; lái xe. 机 (cơ): máy móc; cơ hội.', 'Động từ', 'Trong cách nói “开机后就能用了”, 开机 mang nghĩa “bật máy”.'),
    (3, 729, 'khai tâm', '开 (khai): mở, khai mở; lái xe. 心 (tâm): tim, lòng, tâm.', 'Tính từ', 'Trong cách nói “他却开心极了”, 开心 mang nghĩa “vui vẻ”.'),
    (3, 730, 'khán lai', '看 (khán): nhìn, xem, coi. 来 (lai): đến, tới.', 'Động từ', 'Trong cách nói “看来今天要下雨”, 看来 mang nghĩa “xem ra”.'),
    (3, 731, 'khả', '可 (khả): có thể, được; đáng.', 'Liên từ', 'Đặt trước vế sau để nêu ý trái với vế trước.'),
    (3, 732, 'khát', '渴 (khát): khát nước; khao khát.', 'Tính từ', 'Trong cách nói “我又渴又饿”, 渴 mang nghĩa “khát”.'),
    (3, 733, 'khả ái', '可 (khả): có thể, được; đáng. 爱 (ái): yêu, yêu thương; thích.', 'Tính từ', 'Trong cách nói “这些小猫真可爱”, 可爱 mang nghĩa “đáng yêu”.'),
    (3, 734, 'khả thị', '可 (khả): có thể, được; đáng. 是 (thị): là, đúng, phải.', 'Liên từ', 'Trong cách nói “可是杯子里没有水”, 可是 mang nghĩa “nhưng mà”.'),
    (3, 735, 'khắc', '刻 (khắc): khắc (đơn vị 15 phút); chạm khắc.', 'Lượng từ', 'Trong cách nói giờ, 一刻 là mười lăm phút.'),
    (3, 736, 'khoá bản', '课 (khoá): bài học, tiết học. 本 (bản): gốc; quyển (sách).', 'Danh từ', 'Trong cách nói “读课文时请把课本翻到第六页”, 课本 mang nghĩa “sách giáo khoa”.'),
    (3, 737, 'khách nhân', '客 (khách): khách, người ghé thăm. 人 (nhân): người.', 'Danh từ', 'Trong cách nói “这位客人订了一万张票”, 客人 mang nghĩa “khách”.'),
    (3, 738, 'khoá văn', '课 (khoá): bài học, tiết học. 文 (văn): văn, chữ viết, văn vẻ.', 'Danh từ', 'Trong cách nói “读课文时请把课本翻到第六页”, 课文 mang nghĩa “bài khóa”.'),
    (3, 739, 'không điều', '空 (không): trống rỗng; không khí, bầu trời. 调 (điều): điều chỉnh, pha trộn (cũng đọc diào).', 'Danh từ', 'Trong cách nói “空调坏了”, 空调 mang nghĩa “máy điều hòa”.'),
    (3, 740, 'khốc', '哭 (khốc): khóc.', 'Động từ', 'Trong cách nói “宝宝热得哭了”, 哭 mang nghĩa “khóc”.'),
    (3, 741, 'khoái tử', '筷 (khoái): đũa (que tre gắp đồ ăn). 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “请给我一双筷子和一瓶矿泉水”, 筷子 mang nghĩa “đũa”.'),
    (3, 742, 'khoáng tuyền thuỷ', '矿 (khoáng): khoáng sản. 泉 (tuyền): suối. 水 (thuỷ): nước.', 'Danh từ', 'Trong cách nói “请给我一双筷子和一瓶矿泉水”, 矿泉水 mang nghĩa “nước khoáng”.'),
    (3, 743, 'lai tự', '来 (lai): đến, tới. 自 (tự): tự, mình; từ.', 'Động từ', 'Trong cách nói “这位老人来自西南”, 来自 mang nghĩa “đến từ”.'),
    (3, 744, 'lam', '蓝 (lam): màu xanh lam.', 'Tính từ', 'Trong cách nói “我常常穿这件蓝衬衫去上班”, 蓝 mang nghĩa “xanh lam”.'),
    (3, 745, 'lão', '老 (lão): già, lớn tuổi; kính ngữ.', 'Tính từ, Tiền tố', 'Trong cách nói “这匹马已经老了”, 老 mang nghĩa “già”.'),
    (3, 746, 'lão nhân', '老 (lão): già, lớn tuổi; kính ngữ. 人 (nhân): người.', 'Danh từ', 'Trong cách nói “马路对面的路边有位老人”, 老人 mang nghĩa “người cao tuổi”.'),
    (3, 747, 'ly khai', '离 (ly): rời, lìa, cách xa. 开 (khai): mở, khai mở; lái xe.', 'Động từ', 'Trong cách nói “已经离开家乡很多年了”, 离开 mang nghĩa “rời khỏi”.'),
    (3, 748, 'lễ vật', '礼 (lễ): lễ nghi; quà tặng. 物 (vật): vật, đồ vật, sinh vật.', 'Danh từ', 'Trong cách nói “她笑着收下礼物”, 礼物 mang nghĩa “quà tặng”.'),
    (3, 749, 'lịch sử', '历 (lịch): trải qua, từng. 史 (sử): sử, lịch sử.', 'Danh từ', 'Trong cách nói “我对历史感兴趣”, 历史 mang nghĩa “lịch sử”.'),
    (3, 750, 'liễm', '脸 (liễm): mặt, khuôn mặt.', 'Danh từ', 'Trong cách nói “天气热得她的脸都红了”, 脸 mang nghĩa “khuôn mặt”.'),
    (3, 751, 'luyện', '练 (luyện): rèn luyện, tập.', 'Động từ', 'Trong cách nói “早上在河边练太极拳很凉快”, 练 mang nghĩa “luyện”.'),
    (3, 752, 'luyện tập', '练 (luyện): rèn luyện, tập. 习 (tập): luyện tập, quen.', 'Động từ, Danh từ', 'Trong cách nói “假期里我也坚持每天练习汉语”, 练习 mang nghĩa “luyện tập”.'),
    (3, 753, 'lương khoái', '凉 (lương): mát. 快 (khoái): nhanh; vui sướng.', 'Tính từ', 'Trong cách nói “早上在河边练太极拳很凉快”, 凉快 mang nghĩa “mát mẻ”.'),
    (3, 754, 'lượng', '辆 (lượng): chiếc (đếm xe cộ).', 'Lượng từ', 'Trong cách nói “路边停着三辆自行车”, 辆 mang nghĩa “chiếc (lượng từ cho xe)”.'),
    (3, 755, 'liêu', '聊 (liêu): tán gẫu, nói chuyện phiếm.', 'Động từ', 'Trong cách nói “我们坐下聊了一会儿”, 聊 mang nghĩa “trò chuyện”.'),
    (3, 756, 'liêu thiên nhi', '聊 (liêu): tán gẫu, nói chuyện phiếm. 天 (thiên): trời, bầu trời; ngày. 儿 (nhi): con trẻ; âm đuôi ''r''.', 'Động từ', 'Trong cách nói “留学生常在这里聊天儿”, 聊天儿 mang nghĩa “tán gẫu”.'),
    (3, 757, 'liễu giải', '了 (liễu): thông suốt, xong; (trợ từ: le). 解 (giải): mổ xẻ, gỡ, giải thích.', 'Động từ', 'Trong cách nói “我更了解她了”, 了解 mang nghĩa “hiểu, tìm hiểu”.'),
    (3, 758, 'lân cư', '邻 (lân): kề bên, lân cận. 居 (cư): ở, cư trú.', 'Danh từ', 'Trong cách nói “这封信是那对夫妻写给邻居的”, 邻居 mang nghĩa “hàng xóm”.'),
    (3, 759, 'lưu học', '留 (lưu): ở lại, lưu lại, giữ lại. 学 (học): học.', 'Động từ', 'Trong cách nói “留学生常在这里聊天儿”, 留学 mang nghĩa “du học”.'),
    (3, 760, 'lưu học sinh', '留 (lưu): ở lại, lưu lại, giữ lại. 学 (học): học. 生 (sinh): sinh ra, nảy sinh; sống.', 'Danh từ', 'Trong cách nói “几个留学生坐在楼梯上聊音乐”, 留学生 mang nghĩa “du học sinh”.'),
    (3, 761, 'lâu thê', '楼 (lâu): toà nhà, lầu, tầng. 梯 (thê): cái thang, bậc thang.', 'Danh từ', 'Trong cách nói “我们走楼梯下去”, 楼梯 mang nghĩa “cầu thang”.'),
    (3, 762, 'lộ biên', '路 (lộ): đường, con đường, lối đi. 边 (biên): bên, cạnh, rìa.', 'Danh từ', 'Trong cách nói “路边停着三辆自行车”, 路边 mang nghĩa “ven đường”.'),
    (3, 763, 'lộ khẩu', '路 (lộ): đường, con đường, lối đi. 口 (khẩu): miệng; cửa, lối ra vào.', 'Danh từ', 'Trong cách nói “走到路口就能看见”, 路口 mang nghĩa “giao lộ”.'),
    (3, 764, 'mã', '马 (mã): con ngựa.', 'Danh từ', 'Trong cách nói “这匹马已经老了”, 马 mang nghĩa “ngựa”.'),
    (3, 765, 'mã lộ', '马 (mã): con ngựa. 路 (lộ): đường, con đường, lối đi.', 'Danh từ', 'Trong cách nói “过马路先看红绿灯”, 马路 mang nghĩa “đường phố”.'),
    (3, 766, 'mã thượng', '马 (mã): con ngựa. 上 (thượng): trên; lên.', 'Phó từ', 'Trong cách nói “马上出发吧”, 马上 mang nghĩa “ngay lập tức”.'),
    (3, 767, 'mãn ý', '满 (mãn): đầy, tràn đầy. 意 (ý): ý nghĩ, ý muốn.', 'Động từ', 'Trong cách nói “他对新工作很满意”, 满意 mang nghĩa “hài lòng”.'),
    (3, 768, 'mao', '毛 (mao): lông; hào.', 'Lượng từ', 'Dùng trong khẩu ngữ với giá trị bằng 角, tức một phần mười nhân dân tệ.'),
    (3, 769, 'mễ', '米 (mễ): gạo; mét.', 'Lượng từ', 'Đặt sau số để nói chiều dài tính theo mét.'),
    (3, 770, 'diện tiền', '面 (diện): mặt, bề mặt. 前 (tiền): phía trước; trước đây.', 'Danh từ', 'Trong cách nói “服务员把菜单放在客人面前”, 面前 mang nghĩa “trước mặt”.'),
    (3, 771, 'minh bạch', '明 (minh): sáng, rõ ràng, thông suốt. 白 (bạch): trắng; rõ ràng.', 'Tính từ, Động từ', 'Trong cách nói “我终于明白了”, 明白 mang nghĩa “hiểu rõ”.'),
    (3, 772, 'danh đơn', '名 (danh): tên gọi, danh tiếng. 单 (đơn): đơn, lẻ; tờ/bảng.', 'Danh từ', 'Trong cách nói “根据名单”, 名单 mang nghĩa “danh sách”.'),
    (3, 773, 'danh nhân', '名 (danh): tên gọi, danh tiếng. 人 (nhân): người.', 'Danh từ', 'Trong cách nói “这位名人住在城市的南边”, 名人 mang nghĩa “người nổi tiếng”.'),
    (3, 774, 'nam', '南 (nam): hướng Nam.', 'Danh từ', 'Trong cách nói “这位名人住在城市的南边”, 南 mang nghĩa “nam (phương hướng)”.'),
    (3, 775, 'nan', '难 (nan): khó, gian nan.', 'Tính từ', 'Trong cách nói “往南走不难”, 难 mang nghĩa “khó”.'),
    (3, 776, 'nam phương', '南 (nam): hướng Nam. 方 (phương): phương, vuông; cách thức.', 'Danh từ', 'Trong cách nói “我出生在南方”, 南方 mang nghĩa “miền Nam”.'),
    (3, 777, 'nan quá', '难 (nan): khó, gian nan. 过 (quá): qua, vượt qua, trải qua.', 'Tính từ', 'Trong cách nói “她很难过”, 难过 mang nghĩa “buồn”.'),
    (3, 778, 'nan khán', '难 (nan): khó, gian nan. 看 (khán): nhìn, xem, coi.', 'Tính từ', 'Trong cách nói “这个男人认为黑色上衣并不难看”, 难看 mang nghĩa “xấu, khó coi”.'),
    (3, 779, 'nam nhân', '男 (nam): nam giới, con trai. 人 (nhân): người.', 'Danh từ', 'Trong cách nói “那个年轻男人说话很难听”, 男人 mang nghĩa “đàn ông”.'),
    (3, 780, 'nam sinh', '男 (nam): nam giới, con trai. 生 (sinh): sinh ra, nảy sinh; sống.', 'Danh từ', 'Trong cách nói “七个男生”, 男生 mang nghĩa “nam sinh”.'),
    (3, 781, 'nan đề', '难 (nan): khó, gian nan. 题 (đề): đề bài, câu hỏi.', 'Danh từ', 'Trong cách nói “这对姐妹一起解决了那道难题”, 难题 mang nghĩa “bài toán khó, vấn đề nan giải”.'),
    (3, 782, 'nan thính', '难 (nan): khó, gian nan. 听 (thính): nghe.', 'Tính từ', 'Trong cách nói “那个年轻男人说话很难听”, 难听 mang nghĩa “khó nghe”.'),
    (3, 783, 'niên cấp', '年 (niên): năm. 级 (cấp): cấp bậc, bậc, lớp.', 'Danh từ', 'Trong cách nói “年轻的数学老师努力帮每个年级解决难题”, 年级 mang nghĩa “khối lớp”.'),
    (3, 784, 'niên khinh', '年 (niên): năm. 轻 (khinh): nhẹ nhàng, trẻ.', 'Tính từ', 'Trong cách nói “那个年轻男人说话很难听”, 年轻 mang nghĩa “trẻ tuổi”.'),
    (3, 785, 'ngưu', '牛 (ngưu): con bò, con trâu.', 'Danh từ', 'Trong cách nói “三年级的女生正在画一头牛”, 牛 mang nghĩa “bò”.'),
    (3, 786, 'nỗ lực', '努 (nỗ): dùng sức, gắng sức. 力 (lực): sức mạnh, lực.', 'Động từ, Tính từ', 'Trong cách nói “我还得努力”, 努力 mang nghĩa “nỗ lực”.'),
    (3, 787, 'nữ nhân', '女 (nữ): nữ, phụ nữ, con gái. 人 (nhân): người.', 'Danh từ', 'Trong cách nói “那个女人怕高”, 女人 mang nghĩa “phụ nữ”.'),
    (3, 788, 'nữ sinh', '女 (nữ): nữ, phụ nữ, con gái. 生 (sinh): sinh ra, nảy sinh; sống.', 'Danh từ', 'Trong cách nói “三年级的女生正在画一头牛”, 女生 mang nghĩa “nữ sinh”.'),
    (3, 789, 'ba', '爬 (ba): bò, trèo, leo.', 'Động từ', 'Trong cách nói “难的是爬这座山”, 爬 mang nghĩa “bò, trèo”.'),
    (3, 790, 'phạ', '怕 (phạ): sợ.', 'Động từ', 'Trong cách nói “那个女人怕高”, 怕 mang nghĩa “sợ”.'),
    (3, 791, 'phách chiếu', '拍 (phách): vỗ; chụp ảnh. 照 (chiếu): soi, chiếu; chụp (ảnh).', 'Động từ', 'Trong cách nói “休假时想去拍照”, 拍照 mang nghĩa “chụp ảnh”.'),
    (3, 792, 'bàn tử', '盘 (bàn): đĩa, mâm; cuộn. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “再洗这些盘子”, 盘子 mang nghĩa “đĩa”.'),
    (3, 793, 'bàn', '胖 (bàn): béo, mập.', 'Tính từ', 'Trong cách nói “也不怕胖”, 胖 mang nghĩa “béo, mập”.'),
    (3, 794, 'bia tửu', '啤 (bia): bia (chữ phiên âm). 酒 (tửu): rượu.', 'Danh từ', 'Trong cách nói “平时他把啤酒的瓶子和盘子放在这里”, 啤酒 mang nghĩa “bia”.'),
    (3, 795, 'bình thời', '平 (bình): bằng phẳng, yên ổn. 时 (thời): thời gian, giờ, khi.', 'Danh từ', 'Trong cách nói “我平时很少喝啤酒”, 平时 mang nghĩa “thường ngày”.'),
    (3, 796, 'bình tử', '瓶 (bình): cái bình, cái chai. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “把盘子和瓶子放在一起”, 瓶子 mang nghĩa “chai, lọ”.'),
    (3, 797, 'kỵ', '骑 (kỵ): cưỡi, đi (xe/ngựa).', 'Động từ', 'Trong cách nói “我总是骑自行车去看他”, 骑 mang nghĩa “cưỡi, đi xe đạp hoặc xe máy”.'),
    (3, 798, 'kỳ quái', '奇 (kỳ): lạ, hiếm; kỳ lạ. 怪 (quái): quái lạ; trách.', 'Tính từ', 'Trong cách nói “真奇怪”, 奇怪 mang nghĩa “kỳ lạ”.'),
    (3, 799, 'kỳ thực', '其 (kỳ): cái đó, của nó. 实 (thực): thật, thực; chắc đặc.', 'Phó từ', 'Trong cách nói “其实他没有胖”, 其实 mang nghĩa “thực ra”.'),
    (3, 800, 'kỳ tha', '其 (kỳ): cái đó, của nó. 他 (tha): anh ấy; cái khác.', 'Đại từ', 'Trong cách nói “只是衣服比其他人的宽”, 其他 mang nghĩa “khác, còn lại”.'),
    (3, 801, 'khởi', '起 (khởi): đứng dậy, nổi lên, khởi đầu.', 'Động từ', 'Trong cách nói “风又起了”, 起 mang nghĩa “dậy, nổi lên”.'),
    (3, 802, 'khởi phi', '起 (khởi): đứng dậy, nổi lên, khởi đầu. 飞 (phi): bay.', 'Động từ', 'Trong cách nói “飞机要起飞了”, 起飞 mang nghĩa “cất cánh”.'),
    (3, 803, 'khí xa', '汽 (khí): hơi nước, hơi. 车 (xa): xe, xe cộ.', 'Danh từ', 'Trong cách nói “你可以坐汽车或地铁”, 汽车 mang nghĩa “ô tô”.'),
    (3, 804, 'duyên bút', '铅 (duyên): chì. 笔 (bút): bút, cây bút.', 'Danh từ', 'Trong cách nói “前年买的铅笔”, 铅笔 mang nghĩa “bút chì”.'),
    (3, 805, 'tiền niên', '前 (tiền): phía trước; trước đây. 年 (niên): năm.', 'Danh từ', 'Trong cách nói “前年买的铅笔”, 前年 mang nghĩa “năm kia”.'),
    (3, 806, 'tiền thiên', '前 (tiền): phía trước; trước đây. 天 (thiên): trời, bầu trời; ngày.', 'Danh từ', 'Trong cách nói “我前天还在用”, 前天 mang nghĩa “hôm kia”.'),
    (3, 807, 'thanh sở', '清 (thanh): trong, trong sạch. 楚 (sở): rõ ràng; nước Sở.', 'Tính từ, Động từ', 'Trong cách nói “请假时要把原因说清楚”, 清楚 mang nghĩa “rõ ràng”.'),
    (3, 808, 'thỉnh giả', '请 (thỉnh): mời, xin (lịch sự). 假 (giả): kỳ nghỉ; nghỉ phép.', 'Động từ', 'Trong cách nói “请假时要把原因说清楚”, 请假 mang nghĩa “xin nghỉ”.'),
    (3, 809, 'thỉnh khách', '请 (thỉnh): mời, xin (lịch sự). 客 (khách): khách, người ghé thăm.', 'Động từ', 'Trong cách nói “秋天我想请客”, 请客 mang nghĩa “mời khách, đãi khách”.'),
    (3, 810, 'thu thiên', '秋 (thu): mùa thu. 天 (thiên): trời, bầu trời; ngày.', 'Danh từ', 'Trong cách nói “秋天我想请客”, 秋天 mang nghĩa “mùa thu”.'),
    (3, 811, 'cầu trường', '球 (cầu): quả bóng; quả cầu. 场 (trường): bãi, sân, nơi rộng.', 'Danh từ', 'Trong cách nói “秋天球场开放”, 球场 mang nghĩa “sân bóng”.'),
    (3, 812, 'quần tử', '裙 (quần): váy. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “她穿着裙子热情地欢迎客人”, 裙子 mang nghĩa “váy”.'),
    (3, 813, 'nhiên hậu', '然 (nhiên): như vậy; đúng vậy. 后 (hậu): sau, phía sau.', 'Liên từ', 'Trong cách nói “然后给家人打电话”, 然后 mang nghĩa “sau đó”.'),
    (3, 814, 'nhiệt tình', '热 (nhiệt): nóng, nhiệt. 情 (tình): tình cảm, cảm xúc.', 'Tính từ', 'Trong cách nói “她穿着裙子热情地欢迎客人”, 热情 mang nghĩa “nhiệt tình”.'),
    (3, 815, 'nhận đắc', '认 (nhận): nhận ra, nhận biết; thừa nhận. 得 (đắc): được, đạt được; (trợ từ bổ ngữ).', 'Động từ', 'Trong cách nói “我认得他”, 认得 mang nghĩa “nhận ra, biết”.'),
    (3, 816, 'nhận vi', '认 (nhận): nhận ra, nhận biết; thừa nhận. 为 (vi): làm; là.', 'Động từ', 'Trong cách nói “这个男人认为黑色上衣并不难看”, 认为 mang nghĩa “cho rằng”.'),
    (3, 817, 'nhận chân', '认 (nhận): nhận ra, nhận biết; thừa nhận. 真 (chân): thật, chân thật.', 'Tính từ', 'Trong cách nói “也认为他工作很认真”, 认真 mang nghĩa “nghiêm túc, chăm chú”.'),
    (3, 818, 'dung dị', '容 (dung): chứa đựng; bao dung; dung mạo. 易 (dị): dễ; thay đổi.', 'Tính từ', 'Trong cách nói “不容易丢”, 容易 mang nghĩa “dễ dàng”.'),
    (3, 819, 'như quả', '如 (như): như, giống như; nếu. 果 (quả): quả, trái cây; kết quả.', 'Liên từ', 'Trong cách nói “如果你累了”, 如果 mang nghĩa “nếu”.'),
    (3, 820, 'tản', '伞 (tản): cái dù, ô che.', 'Danh từ', 'Trong cách nói “可我没带伞”, 伞 mang nghĩa “ô, dù”.'),
    (3, 821, 'tảo', '扫 (tảo): quét.', 'Động từ', 'Trong cách nói “把地扫干净”, 扫 mang nghĩa “quét”.'),
    (3, 822, 'sa phát', '沙 (sa): cát. 发 (phát): phát ra, khởi; tóc (fà).', 'Danh từ', 'Trong cách nói “就躺在沙发上休息”, 沙发 mang nghĩa “ghế sô pha”.'),
    (3, 823, 'sơn', '山 (sơn): núi.', 'Danh từ', 'Trong cách nói “难的是爬这座山”, 山 mang nghĩa “núi”.'),
    (3, 824, 'thượng y', '上 (thượng): trên; lên. 衣 (y): áo, quần áo.', 'Danh từ', 'Trong cách nói “这件女式上衣颜色真漂亮”, 上衣 mang nghĩa “áo (mặc phần thân trên)”.'),
    (3, 825, 'thược tử', '勺 (thược): thìa. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “勺子就在你身边的小桌上”, 勺子 mang nghĩa “thìa”.'),
    (3, 826, 'thân biên', '身 (thân): thân thể, mình. 边 (biên): bên, cạnh, rìa.', 'Danh từ', 'Trong cách nói “勺子就在你身边的小桌上”, 身边 mang nghĩa “bên cạnh mình”.'),
    (3, 827, 'thân cao', '身 (thân): thân thể, mình. 高 (cao): cao.', 'Danh từ', 'Trong cách nói “他的身高和声音都变了”, 身高 mang nghĩa “chiều cao”.'),
    (3, 828, 'thanh', '声 (thanh): tiếng, âm thanh.', 'Danh từ, Lượng từ', 'Đứng sau số đếm để đếm tiếng kêu hoặc âm thanh.'),
    (3, 829, 'sinh hoạt', '生 (sinh): sinh ra, nảy sinh; sống. 活 (hoạt): sống; linh hoạt.', 'Danh từ, Động từ', 'Trong cách nói “生活中有人说错话”, 生活 mang nghĩa “cuộc sống”.'),
    (3, 830, 'sinh khí', '生 (sinh): sinh ra, nảy sinh; sống. 气 (khí): hơi, khí; giận.', 'Động từ', 'Trong cách nói “请别马上生气”, 生气 mang nghĩa “tức giận”.'),
    (3, 831, 'thanh âm', '声 (thanh): tiếng, âm thanh. 音 (âm): âm thanh, tiếng.', 'Danh từ', 'Trong cách nói “他的身高和声音都变了”, 声音 mang nghĩa “âm thanh, giọng”.'),
    (3, 832, 'thị', '市 (thị): chợ; thành phố.', 'Danh từ', 'Trong cách nói “这位名人住在城市的南边”, 市 mang nghĩa “thành phố”.'),
    (3, 833, 'thí', '试 (thí): thử, kiểm tra.', 'Động từ', 'Trong cách nói “你试一下”, 试 mang nghĩa “thử”.'),
    (3, 834, 'thất', '室 (thất): phòng, gian phòng.', 'Danh từ', 'Trong cách nói “快从教室出来”, 室 mang nghĩa “phòng”.'),
    (3, 835, 'thế giới', '世 (thế): đời, thời, thế gian. 界 (giới): ranh giới, phạm vi.', 'Danh từ', 'Trong cách nói “我想去看看外面的世界”, 世界 mang nghĩa “thế giới”.'),
    (3, 836, 'thu', '收 (thu): thu, nhận, gom.', 'Động từ', 'Trong cách nói “她笑着收下礼物”, 收 mang nghĩa “thu, nhận”.'),
    (3, 837, 'thu đáo', '收 (thu): thu, nhận, gom. 到 (đáo): đến, tới.', 'Động từ', 'Trong cách nói “我收到叔叔的来信”, 收到 mang nghĩa “nhận được”.'),
    (3, 838, 'thụ', '受 (thụ): nhận, chịu.', 'Động từ', 'Trong cách nói “他的画很受大家喜爱”, 受 mang nghĩa “chịu, nhận”.'),
    (3, 839, 'sấu', '瘦 (sấu): gầy, ốm.', 'Tính từ', 'Trong cách nói “他比去年瘦了”, 瘦 mang nghĩa “gầy”.'),
    (3, 840, 'thụ đáo', '受 (thụ): nhận, chịu. 到 (đáo): đến, tới.', 'Động từ', 'Trong cách nói “这位司机受到游客的欢迎”, 受到 mang nghĩa “chịu, nhận được”.'),
    (3, 841, 'thúc thúc', '叔 (thúc): chú; em trai cha.', 'Danh từ', 'Trong cách nói “我收到叔叔的来信”, 叔叔 mang nghĩa “chú (em trai của bố)”.'),
    (3, 842, 'thụ', '树 (thụ): cây, cây cối; trồng.', 'Danh từ', 'Trong cách nói “树都开花了”, 树 mang nghĩa “cây”.'),
    (3, 843, 'số học', '数 (số): số; đếm. 学 (học): học.', 'Danh từ', 'Trong cách nói “她教数学”, 数学 mang nghĩa “toán học”.'),
    (3, 844, 'loát', '刷 (loát): chải, quét; bàn chải.', 'Động từ', 'Trong cách nói “刷完牙后”, 刷 mang nghĩa “chải, đánh bằng bàn chải”.'),
    (3, 845, 'song', '双 (song): đôi, cặp; chẵn.', 'Lượng từ', 'Trong cách nói “这双鞋舒服吗”, 双 mang nghĩa “đôi (lượng từ)”.'),
    (3, 846, 'thuỷ bình', '水 (thuỷ): nước. 平 (bình): bằng phẳng, yên ổn.', 'Danh từ', 'Trong cách nói “想提高数学水平”, 水平 mang nghĩa “trình độ”.'),
    (3, 847, 'ty cơ', '司 (ty): cai quản, điều hành; cơ quan. 机 (cơ): máy móc; cơ hội.', 'Danh từ', 'Trong cách nói “这位司机受到游客的欢迎”, 司机 mang nghĩa “tài xế”.'),
    (3, 848, 'tứ quý', '四 (tứ): bốn, số 4. 季 (quý): mùa; em út.', 'Danh từ', 'Trong cách nói “一年有四季”, 四季 mang nghĩa “bốn mùa”.'),
    (3, 849, 'thái dương', '太 (thái): quá, rất; to lớn. 阳 (dương): dương, mặt trời (đối với 阴).', 'Danh từ', 'Trong cách nói “太阳从东方升起”, 太阳 mang nghĩa “mặt trời”.'),
    (3, 850, 'đường', '糖 (đường): đường, kẹo.', 'Danh từ', 'Trong cách nói “再加一点儿糖”, 糖 mang nghĩa “đường”.'),
    (3, 851, 'đặc biệt', '特 (đặc): đặc biệt, riêng. 别 (biệt): khác; chia tách; chớ, đừng.', 'Tính từ, Phó từ', 'Trong cách nói “体育馆里今天有一场特别的体育比赛”, 特别 mang nghĩa “đặc biệt”.'),
    (3, 852, 'đề cao', '提 (đề): nâng, xách, nêu ra. 高 (cao): cao.', 'Động từ', 'Trong cách nói “想提高数学水平”, 提高 mang nghĩa “nâng cao”.'),
    (3, 853, 'thể dục', '体 (thể): thân thể, cơ thể. 育 (dục): nuôi dưỡng, dạy dỗ.', 'Danh từ', 'Trong cách nói “我们市有个很大的体育馆”, 体育 mang nghĩa “thể dục thể thao”.'),
    (3, 854, 'thể dục quán', '体 (thể): thân thể, cơ thể. 育 (dục): nuôi dưỡng, dạy dỗ. 馆 (quán): toà nhà lớn (quán, viện, sảnh).', 'Danh từ', 'Trong cách nói “我们市有个很大的体育馆”, 体育馆 mang nghĩa “nhà thi đấu”.'),
    (3, 855, 'điềm', '甜 (điềm): ngọt; êm ái.', 'Tính từ', 'Trong cách nói “奶茶没有你说的那么甜”, 甜 mang nghĩa “ngọt”.'),
    (3, 856, 'khiêu', '跳 (khiêu): nhảy, bật lên.', 'Động từ', 'Trong cách nói “这只羊跳得挺高”, 跳 mang nghĩa “nhảy”.'),
    (3, 857, 'thính thuyết', '听 (thính): nghe. 说 (thuyết): nói, nói chuyện.', 'Động từ', 'Trong cách nói “听说这个西瓜挺甜”, 听说 mang nghĩa “nghe nói”.'),
    (3, 858, 'đĩnh', '挺 (đĩnh): thẳng; khá.', 'Phó từ', 'Trong cách nói “这只羊跳得挺高”, 挺 mang nghĩa “khá, rất”.'),
    (3, 859, 'đồng sự', '同 (đồng): cùng, giống nhau. 事 (sự): việc, sự việc.', 'Danh từ', 'Trong cách nói “我给你介绍一下新同事”, 同事 mang nghĩa “đồng nghiệp”.'),
    (3, 860, 'đồng ý', '同 (đồng): cùng, giống nhau. 意 (ý): ý nghĩ, ý muốn.', 'Động từ', 'Trong cách nói “同事也同意买一个”, 同意 mang nghĩa “đồng ý”.'),
    (3, 861, 'đầu phát', '头 (đầu): đầu; cái đầu; đứng đầu. 发 (phát): phát ra, khởi; tóc (fà).', 'Danh từ', 'Trong cách nói “她的头发很长”, 头发 mang nghĩa “tóc”.'),
    (3, 862, 'đột nhiên', '突 (đột): đột ngột, vọt ra. 然 (nhiên): như vậy; đúng vậy.', 'Tính từ', 'Trong cách nói “儿子突然打电话来”, 突然 mang nghĩa “đột nhiên”.'),
    (3, 863, 'đồ thư quán', '图 (đồ): tranh, bản đồ, hình vẽ. 书 (thư): sách, viết. 馆 (quán): toà nhà lớn (quán, viện, sảnh).', 'Danh từ', 'Trong cách nói “外地的朋友突然来图书馆”, 图书馆 mang nghĩa “thư viện”.'),
    (3, 864, 'thoái', '腿 (thoái): chân, cẳng chân.', 'Danh từ', 'Trong cách nói “快到腿上了”, 腿 mang nghĩa “chân (phần từ hông đến cổ chân)”.'),
    (3, 865, 'ngoại địa', '外 (ngoại): ngoài, bên ngoài. 地 (địa): đất, mặt đất; nơi.', 'Danh từ', 'Trong cách nói “我在外地的图书馆学外语”, 外地 mang nghĩa “nơi khác, tỉnh khác”.'),
    (3, 866, 'ngoại mại', '外 (ngoại): ngoài, bên ngoài. 卖 (mại): bán.', 'Động từ, Danh từ', 'Trong cách nói “中午点外卖”, 外卖 mang nghĩa “đồ ăn mang đi hoặc giao tận nơi”.'),
    (3, 867, 'ngoại ngữ', '外 (ngoại): ngoài, bên ngoài. 语 (ngữ): lời nói, ngôn ngữ.', 'Danh từ', 'Trong cách nói “我在外地的图书馆学外语”, 外语 mang nghĩa “ngoại ngữ”.'),
    (3, 868, 'hoàn thành', '完 (hoàn): xong, trọn vẹn, hoàn tất. 成 (thành): thành, nên, trở thành.', 'Động từ', 'Trong cách nói “我正好可以完成作业”, 完成 mang nghĩa “hoàn thành”.'),
    (3, 869, 'oản', '碗 (oản): cái bát.', 'Danh từ', 'Trong cách nói “先吃饭再洗碗”, 碗 mang nghĩa “bát, chén”.'),
    (3, 870, 'vãn điểm', '晚 (vãn): muộn, tối; buổi tối. 点 (điểm): giờ; chấm điểm.', 'Động từ', 'Trong cách nói “火车晚点了”, 晚点 mang nghĩa “trễ giờ (tàu, xe, máy bay)”.'),
    (3, 871, 'vãn hội', '晚 (vãn): muộn, tối; buổi tối. 会 (hội): biết; họp; chốc lát.', 'Danh từ', 'Trong cách nói “节日的晚会上有很多精彩的节目”, 晚会 mang nghĩa “buổi liên hoan buổi tối”.'),
    (3, 872, 'võng cầu', '网 (võng): lưới; mạng internet. 球 (cầu): quả bóng; quả cầu.', 'Danh từ', 'Trong cách nói “晚会的网站上写着网球比赛的时间”, 网球 mang nghĩa “quần vợt”.'),
    (3, 873, 'võng trạm', '网 (võng): lưới; mạng internet. 站 (trạm): đứng; trạm, bến.', 'Danh từ', 'Trong cách nói “我忘记了这个网站的名字”, 网站 mang nghĩa “trang web”.'),
    (3, 874, 'vong ký', '忘 (vong): quên. 记 (ký): ghi, nhớ, ghi chép.', 'Động từ', 'Trong cách nói “我忘记了这个网站的名字”, 忘记 mang nghĩa “quên”.'),
    (3, 875, 'vị', '为 (vị): vì, cho.', 'Giới từ', 'Trong cách nói “为了你的健康”, 为 mang nghĩa “vì, cho”.'),
    (3, 876, 'vị liễu', '为 (vị): vì, cho. 了 (liễu): thông suốt, xong; (trợ từ: le).', 'Giới từ', 'Trong cách nói “为了你的健康”, 为了 mang nghĩa “để, nhằm”.'),
    (3, 877, 'vệ sinh gian', '卫 (vệ): bảo vệ. 生 (sinh): sinh ra, nảy sinh; sống. 间 (gian): gian, phòng; khoảng giữa.', 'Danh từ', 'Trong cách nói “卫生间在屋子的西边”, 卫生间 mang nghĩa “nhà vệ sinh”.'),
    (3, 878, 'văn hoá', '文 (văn): văn, chữ viết, văn vẻ. 化 (hoá): biến đổi, giáo hoá.', 'Danh từ', 'Trong cách nói “关于这个国家的文化”, 文化 mang nghĩa “văn hóa”.'),
    (3, 879, 'ốc tử', '屋 (ốc): nhà, gian phòng. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “红色的花在屋子后面”, 屋子 mang nghĩa “phòng, căn nhà”.'),
    (3, 880, 'tây', '西 (tây): phía tây.', 'Danh từ', 'Trong cách nói “卫生间在屋子的西边”, 西 mang nghĩa “tây”.'),
    (3, 881, 'tây bắc', '西 (tây): phía tây. 北 (bắc): hướng Bắc.', 'Danh từ', 'Trong cách nói “他喜爱西北文化”, 西北 mang nghĩa “tây bắc”.'),
    (3, 882, 'tây phương', '西 (tây): phía tây. 方 (phương): phương, vuông; cách thức.', 'Danh từ', 'Trong cách nói “西北地区和西方国家的饮食习惯不同”, 西方 mang nghĩa “phương Tây”.'),
    (3, 883, 'tây qua', '西 (tây): phía tây. 瓜 (qua): quả dưa, quả bầu bí.', 'Danh từ', 'Trong cách nói “夏天吃完西瓜”, 西瓜 mang nghĩa “dưa hấu”.'),
    (3, 884, 'tây nam', '西 (tây): phía tây. 南 (nam): hướng Nam.', 'Danh từ', 'Trong cách nói “这位老人来自西南”, 西南 mang nghĩa “tây nam”.'),
    (3, 885, 'tập quán', '习 (tập): luyện tập, quen. 惯 (quán): quen, thành nếp.', 'Động từ, Danh từ', 'Trong cách nói “养成好习惯”, 习惯 mang nghĩa “thói quen”.'),
    (3, 886, 'hỉ ái', '喜 (hỉ): vui mừng, thích. 爱 (ái): yêu, yêu thương; thích.', 'Động từ', 'Trong cách nói “他的画很受大家喜爱”, 喜爱 mang nghĩa “yêu thích”.'),
    (3, 887, 'tẩy y cơ', '洗 (tẩy): rửa, giặt, tắm rửa. 衣 (y): áo, quần áo. 机 (cơ): máy móc; cơ hội.', 'Danh từ', 'Trong cách nói “先把衣服放进洗衣机”, 洗衣机 mang nghĩa “máy giặt”.'),
    (3, 888, 'tẩy táo', '洗 (tẩy): rửa, giặt, tắm rửa. 澡 (táo): tắm gội.', 'Động từ', 'Trong cách nói “游泳后就去洗澡”, 洗澡 mang nghĩa “tắm”.'),
    (3, 889, 'hạ thiên', '夏 (hạ): mùa hè. 天 (thiên): trời, bầu trời; ngày.', 'Danh từ', 'Trong cách nói “我喜爱夏天”, 夏天 mang nghĩa “mùa hè”.'),
    (3, 890, 'tiên', '先 (tiên): trước, đầu tiên.', 'Phó từ', 'Trong cách nói “我先去吃早饭”, 先 mang nghĩa “trước, trước tiên”.'),
    (3, 891, 'hương tiêu', '香 (hương): thơm, hương thơm. 蕉 (tiêu): cây chuối.', 'Danh từ', 'Trong cách nói “我相信箱子里还有香蕉”, 香蕉 mang nghĩa “chuối”.'),
    (3, 892, 'tương tín', '相 (tương): lẫn nhau. 信 (tín): tin tưởng; thư tín.', 'Động từ', 'Trong cách nói “我相信箱子里还有香蕉”, 相信 mang nghĩa “tin tưởng”.'),
    (3, 893, 'sương tử', '箱 (sương): cái hòm, thùng. 子 (tử): (hậu tố danh từ).', 'Danh từ', 'Trong cách nói “我相信箱子里还有香蕉”, 箱子 mang nghĩa “hòm, va li”.'),
    (3, 894, 'hướng', '向 (hướng): hướng về, về phía.', 'Động từ, Giới từ', 'Trong cách nói “从这里向东走”, 向 mang nghĩa “hướng về”.'),
    (3, 895, 'tượng', '像 (tượng): giống, tựa như; hình tượng.', 'Động từ', 'Trong cách nói “这台相机看起来很像我的”, 像 mang nghĩa “giống như”.'),
    (3, 896, 'tướng cơ', '相 (tướng): hình ảnh. 机 (cơ): máy móc; cơ hội.', 'Danh từ', 'Trong cách nói “这台相机看起来很像我的”, 相机 mang nghĩa “máy ảnh”.'),
    (3, 897, 'tiểu khu', '小 (tiểu): nhỏ, bé. 区 (khu): khu vực.', 'Danh từ', 'Trong cách nói “小区门口车多”, 小区 mang nghĩa “khu dân cư”.'),
    (3, 898, 'tiểu tâm', '小 (tiểu): nhỏ, bé. 心 (tâm): tim, lòng, tâm.', 'Động từ, Tính từ', 'Trong cách nói “出门小心”, 小心 mang nghĩa “cẩn thận”.'),
    (3, 899, 'hiệu viên', '校 (hiệu): trường học. 园 (viên): vườn, khu vườn.', 'Danh từ', 'Trong cách nói “小区的花园很像校园”, 校园 mang nghĩa “khuôn viên trường”.'),
    (3, 900, 'hiệu trưởng', '校 (hiệu): trường học. 长 (trưởng): lớn lên; người đứng đầu.', 'Danh từ', 'Trong cách nói “校长带我们参观校园”, 校长 mang nghĩa “hiệu trưởng”.'),
    (3, 901, 'hài', '鞋 (hài): giày, dép.', 'Danh từ', 'Trong cách nói “您先试一下鞋”, 鞋 mang nghĩa “giày”.'),
    (3, 902, 'tâm lý', '心 (tâm): tim, lòng, tâm. 里 (lý): bên trong; làng, dặm.', 'Danh từ', 'Trong cách nói “我心里很高兴”, 心里 mang nghĩa “trong lòng”.'),
    (3, 903, 'tân niên', '新 (tân): mới, mới mẻ. 年 (niên): năm.', 'Danh từ', 'Trong cách nói “新年我们吃新鲜水果”, 新年 mang nghĩa “năm mới”.'),
    (3, 904, 'tân văn', '新 (tân): mới, mới mẻ. 闻 (văn): nghe; ngửi; tin.', 'Danh từ', 'Trong cách nói “你看看报纸上有什么新闻”, 新闻 mang nghĩa “tin tức”.'),
    (3, 905, 'tân tiên', '新 (tân): mới, mới mẻ. 鲜 (tiên): tươi; tươi ngon; tươi đẹp.', 'Tính từ', 'Trong cách nói “新年我们吃新鲜水果”, 新鲜 mang nghĩa “tươi, mới mẻ”.'),
    (3, 906, 'tín', '信 (tín): tin tưởng; thư tín.', 'Động từ, Danh từ', 'Trong cách nói “明天我把信带来”, 信 mang nghĩa “thư”.'),
    (3, 907, 'tín dụng tạp', '信 (tín): tin tưởng; thư tín. 用 (dụng): dùng; cần. 卡 (tạp): thẻ (card); mắc kẹt.', 'Danh từ', 'Trong cách nói “用信用卡买礼物”, 信用卡 mang nghĩa “thẻ tín dụng”.'),
    (3, 908, 'hành', '行 (hành): đi; được.', 'Động từ, Tính từ', 'Có thể đứng một mình để bày tỏ sự đồng ý.'),
    (3, 909, 'hành lý', '行 (hành): đi; được. 李 (lý): cây mận; họ Lý; hành lý.', 'Danh từ', 'Trong cách nói “我来帮你拿行李”, 行李 mang nghĩa “hành lý”.'),
    (3, 910, 'hứng thú', '兴 (hứng): hứng thú. 趣 (thú): thú vị, hứng thú.', 'Danh từ', 'Trong cách nói “我对摄影有兴趣”, 兴趣 mang nghĩa “hứng thú”.'),
    (3, 911, 'hưu giả', '休 (hưu): nghỉ, ngừng. 假 (giả): kỳ nghỉ; nghỉ phép.', 'Động từ', 'Trong cách nói “休假需要带多少行李”, 休假 mang nghĩa “nghỉ phép”.'),
    (3, 912, 'nhu yếu', '需 (nhu): cần, cần đến. 要 (yếu): cần, muốn; quan trọng.', 'Động từ, Danh từ', 'Trong cách nói “休假需要带多少行李”, 需要 mang nghĩa “cần”.'),
    (3, 913, 'tuyển', '选 (tuyển): chọn, tuyển.', 'Động từ', 'Trong cách nói “这个学期你想选哪门课”, 选 mang nghĩa “chọn”.'),
    (3, 914, 'tuyển trạch', '选 (tuyển): chọn, tuyển. 择 (trạch): lựa, chọn lọc.', 'Động từ', 'Trong cách nói “可以选择软一点儿的”, 选择 mang nghĩa “lựa chọn”.'),
    (3, 915, 'học kỳ', '学 (học): học. 期 (kỳ): kỳ hạn, thời kỳ.', 'Danh từ', 'Trong cách nói “这个学期你想选哪门课”, 学期 mang nghĩa “học kỳ”.'),
    (3, 916, 'nha', '牙 (nha): răng.', 'Danh từ', 'Trong cách nói “看孩子刷牙”, 牙 mang nghĩa “răng”.'),
    (3, 917, 'nha loát', '牙 (nha): răng. 刷 (loát): chải, quét; bàn chải.', 'Danh từ', 'Trong cách nói “买牙刷时”, 牙刷 mang nghĩa “bàn chải đánh răng”.'),
    (3, 918, 'dương', '羊 (dương): con dê, con cừu.', 'Danh từ', 'Trong cách nói “这只羊跳得挺高”, 羊 mang nghĩa “dê, cừu”.'),
    (3, 919, 'dưỡng', '养 (dưỡng): nuôi, trồng.', 'Động từ', 'Trong cách nói “奶奶养的鸡几乎每天都下蛋”, 养 mang nghĩa “nuôi”.'),
    (3, 920, 'yếu cầu', '要 (yếu): cần, muốn; quan trọng. 求 (cầu): cầu xin, tìm cầu.', 'Động từ, Danh từ', 'Trong cách nói “要求我们别吓着它们”, 要求 mang nghĩa “yêu cầu”.'),
    (3, 921, 'hiệt', '页 (hiệt): trang.', 'Lượng từ', 'Trong cách nói “读课文时请把课本翻到第六页”, 页 mang nghĩa “trang”.'),
    (3, 922, 'nhất định', '一 (nhất): một, số một. 定 (định): định, ổn định, chắc chắn.', 'Tính từ, Phó từ', 'Trong cách nói “你一定能做完”, 一定 mang nghĩa “nhất định”.'),
    (3, 923, 'nhất cộng', '一 (nhất): một, số một. 共 (cộng): cùng, chung; cộng lại.', 'Phó từ', 'Trong cách nói “作业一共三页”, 一共 mang nghĩa “tổng cộng”.'),
    (3, 924, 'nhất khối nhi', '一 (nhất): một, số một. 块 (khối): cục, miếng, đồng. 儿 (nhi): con trẻ; âm đuôi ''r''.', 'Danh từ, Phó từ', 'Trong cách nói “下课以后一块儿走吧”, 一块儿 mang nghĩa “cùng nhau”.'),
    (3, 925, 'nhất dạng', '一 (nhất): một, số một. 样 (dạng): dáng vẻ, kiểu, loại.', 'Tính từ', 'Trong cách nói “我的个子跟哥哥一样高”, 一样 mang nghĩa “giống nhau”.'),
    (3, 926, 'dĩ hậu', '以 (dĩ): lấy, dùng; theo. 后 (hậu): sau, phía sau.', 'Danh từ', 'Trong cách nói “开学以后我们经常一起复习”, 以后 mang nghĩa “sau đó, về sau”.'),
    (3, 927, 'dĩ tiền', '以 (dĩ): lấy, dùng; theo. 前 (tiền): phía trước; trước đây.', 'Danh từ', 'Trong cách nói “花钱以前”, 以前 mang nghĩa “trước đây”.'),
    (3, 928, 'dĩ thượng', '以 (dĩ): lấy, dùng; theo. 上 (thượng): trên; lên.', 'Danh từ', 'Trong cách nói “十二岁以上的人都能参加”, 以上 mang nghĩa “từ mức đó trở lên”.'),
    (3, 929, 'dĩ ngoại', '以 (dĩ): lấy, dùng; theo. 外 (ngoại): ngoài, bên ngoài.', 'Danh từ', 'Trong cách nói “除了以下三种饮料以外”, 以外 mang nghĩa “ngoài phạm vi”.'),
    (3, 930, 'dĩ vi', '以 (dĩ): lấy, dùng; theo. 为 (vi): làm; là.', 'Động từ', 'Trong cách nói “我以为你一般都坐公交车”, 以为 mang nghĩa “tưởng rằng”.'),
    (3, 931, 'dĩ hạ', '以 (dĩ): lấy, dùng; theo. 下 (hạ): dưới, xuống.', 'Danh từ', 'Trong cách nói “除了以下三种饮料以外”, 以下 mang nghĩa “từ mức đó trở xuống”.'),
    (3, 932, 'nhất ban', '一 (nhất): một, số một. 般 (ban): loại, kiểu, hạng.', 'Tính từ', 'Trong cách nói “我以为你一般都坐公交车”, 一般 mang nghĩa “thông thường”.'),
    (3, 933, 'nhất biên', '一 (nhất): một, số một. 边 (biên): bên, cạnh, rìa.', 'Phó từ', 'Trong cách nói “她一边听音乐”, 一边 mang nghĩa “một bên”.'),
    (3, 934, 'nhất trực', '一 (nhất): một, số một. 直 (trực): thẳng, ngay thẳng.', 'Phó từ', 'Trong cách nói “别一直看手机”, 一直 mang nghĩa “suốt, liên tục”.'),
    (3, 935, 'âm nhạc', '音 (âm): âm thanh, tiếng. 乐 (nhạc): âm nhạc.', 'Danh từ', 'Trong cách nói “她一边听音乐”, 音乐 mang nghĩa “âm nhạc”.'),
    (3, 936, 'ngân hàng', '银 (ngân): bạc. 行 (hàng): hãng, cơ sở kinh doanh.', 'Danh từ', 'Trong cách nói “经过银行时”, 银行 mang nghĩa “ngân hàng”.'),
    (3, 937, 'ngân hàng tạp', '银 (ngân): bạc. 行 (hàng): hãng, cơ sở kinh doanh. 卡 (tạp): thẻ (card); mắc kẹt.', 'Danh từ', 'Trong cách nói “银行卡放在包里”, 银行卡 mang nghĩa “thẻ ngân hàng”.'),
    (3, 938, 'ẩm liệu', '饮 (ẩm): uống. 料 (liệu): vật liệu, nguyên liệu; liệu trước.', 'Danh từ', 'Trong cách nói “应该可以买饮料”, 饮料 mang nghĩa “đồ uống”.'),
    (3, 939, 'ứng cai', '应 (ứng): nên; đáp lại, ứng phó. 该 (cai): nên, đáng; cái đó.', 'Động từ', 'Trong cách nói “应该可以买饮料”, 应该 mang nghĩa “nên”.'),
    (3, 940, 'ảnh hưởng', '影 (ảnh): bóng, hình bóng. 响 (hưởng): vang, kêu, âm vang.', 'Động từ, Danh từ', 'Trong cách nói “睡得太少会影响学习”, 影响 mang nghĩa “ảnh hưởng”.'),
    (3, 941, 'dụng', '用 (dụng): dùng; cần.', 'Động từ', 'Trong cách nói “用这个旧本子写两句话吧”, 用 mang nghĩa “dùng”.'),
    (3, 942, 'bưu kiện', '邮 (bưu): bưu, gửi thư. 件 (kiện): cái, chiếc; kiện (vật, việc).', 'Danh từ', 'Trong cách nói “一边写邮件”, 邮件 mang nghĩa “thư, thư điện tử”.'),
    (3, 943, 'du khách', '游 (du): bơi; rong chơi, du ngoạn. 客 (khách): khách, người ghé thăm.', 'Danh từ', 'Trong cách nói “这位司机受到游客的欢迎”, 游客 mang nghĩa “du khách”.'),
    (3, 944, 'du hí', '游 (du): bơi; rong chơi, du ngoạn. 戏 (hí): đùa giỡn; tuồng, kịch.', 'Danh từ', 'Trong cách nói “这个游戏好玩儿吗”, 游戏 mang nghĩa “trò chơi”.'),
    (3, 945, 'bưu sương', '邮 (bưu): bưu, gửi thư. 箱 (sương): cái hòm, thùng.', 'Danh từ', 'Trong cách nói “邮箱里有一封和比赛有关的邮件”, 邮箱 mang nghĩa “hộp thư”.'),
    (3, 946, 'hữu quan', '有 (hữu): có, sở hữu. 关 (quan): đóng (cửa); liên quan.', 'Động từ, Giới từ', 'Trong cách nói “邮箱里有一封和比赛有关的邮件”, 有关 mang nghĩa “có liên quan”.'),
    (3, 947, 'hữu danh', '有 (hữu): có, sở hữu. 名 (danh): tên gọi, danh tiếng.', 'Tính từ', 'Trong cách nói “这间室内游泳馆在世界上很有名”, 有名 mang nghĩa “nổi tiếng”.'),
    (3, 948, 'hữu dụng', '有 (hữu): có, sở hữu. 用 (dụng): dùng; cần.', 'Tính từ', 'Trong cách nói “学好一门语言很有用”, 有用 mang nghĩa “hữu ích”.'),
    (3, 949, 'hựu', '又 (hựu): lại, thêm; vừa…vừa….', 'Phó từ', 'Trong cách nói “风又起了”, 又 mang nghĩa “lại, thêm lần nữa”.'),
    (3, 950, 'vũ mao cầu', '羽 (vũ): lông vũ. 毛 (mao): lông; hào. 球 (cầu): quả bóng; quả cầu.', 'Danh từ', 'Trong cách nói “周末我们打网球或者羽毛球”, 羽毛球 mang nghĩa “cầu lông”.'),
    (3, 951, 'ngữ ngôn', '语 (ngữ): lời nói, ngôn ngữ. 言 (ngôn): lời nói.', 'Danh từ', 'Trong cách nói “学好一门语言很有用”, 语言 mang nghĩa “ngôn ngữ”.'),
    (3, 952, 'vũ y', '雨 (vũ): mưa. 衣 (y): áo, quần áo.', 'Danh từ', 'Trong cách nói “下雨时我遇到一个穿雨衣的运动员”, 雨衣 mang nghĩa “áo mưa”.'),
    (3, 953, 'ngộ đáo', '遇 (ngộ): gặp gỡ, đối mặt. 到 (đáo): đến, tới.', 'Động từ', 'Trong cách nói “下雨时我遇到一个穿雨衣的运动员”, 遇到 mang nghĩa “gặp phải”.'),
    (3, 954, 'ngộ kiến', '遇 (ngộ): gặp gỡ, đối mặt. 见 (kiến): thấy, gặp.', 'Động từ', 'Trong cách nói “我遇见了经理”, 遇见 mang nghĩa “gặp, bắt gặp”.'),
    (3, 955, 'viên', '园 (viên): vườn, khu vườn.', 'Danh từ', 'Dùng trong tên gọi nơi trồng cây hoặc khu dành cho một hoạt động, như 花园 và 公园.'),
    (3, 956, 'viên', '员 (viên): người (thành viên, nhân viên).', 'Hậu tố', 'Đứng sau một thành tố khác để chỉ người làm một công việc, như 服务员.'),
    (3, 957, 'nguyện ý', '愿 (nguyện): mong, ước nguyện; bằng lòng. 意 (ý): ý nghĩ, ý muốn.', 'Động từ', 'Trong cách nói “你愿意陪我去看月亮吗”, 愿意 mang nghĩa “sẵn lòng”.'),
    (3, 958, 'việt', '越 (việt): càng, vượt qua.', 'Phó từ', 'Trong cách nói “越往上爬”, 越 mang nghĩa “càng”.'),
    (3, 959, 'nguyệt lượng', '月 (nguyệt): trăng; tháng. 亮 (lượng): sáng, sáng sủa.', 'Danh từ', 'Trong cách nói “你愿意陪我去看月亮吗”, 月亮 mang nghĩa “mặt trăng”.'),
    (3, 960, 'vận động hội', '运 (vận): chở, vận chuyển; vận may. 动 (động): chuyển động, làm; cử động. 会 (hội): biết; họp; chốc lát.', 'Danh từ', 'Trong cách nói “运动会越来越近”, 运动会 mang nghĩa “đại hội thể thao”.'),
    (3, 961, 'vận động viên', '运 (vận): chở, vận chuyển; vận may. 动 (động): chuyển động, làm; cử động. 员 (viên): người (thành viên, nhân viên).', 'Danh từ', 'Trong cách nói “下雨时我遇到一个穿雨衣的运动员”, 运动员 mang nghĩa “vận động viên”.'),
    (3, 962, 'trá môn', '咱 (trá): ta (gộp cả mình). 们 (môn): (đuôi số nhiều).', 'Đại từ', 'Trong cách nói “咱们去训练吧”, 咱们 mang nghĩa “chúng ta”.'),
    (3, 963, 'tang', '脏 (tang): bẩn.', 'Tính từ', 'Trong cách nói “衣服脏了怎么办”, 脏 mang nghĩa “bẩn”.'),
    (3, 964, 'chẩm ma biện', '怎 (chẩm): sao, thế nào. 么 (ma): trợ từ (trong 怎么, 什么). 办 (biện): làm, lo liệu, xử lý.', 'Cụm từ', 'Trong cách nói “衣服脏了怎么办”, 怎么办 mang nghĩa “làm thế nào bây giờ”.'),
    (3, 965, 'chẩm dạng', '怎 (chẩm): sao, thế nào. 样 (dạng): dáng vẻ, kiểu, loại.', 'Đại từ', 'Trong cách nói “在动物园工作的人懂得怎样保护动物”, 怎样 mang nghĩa “thế nào”.'),
    (3, 966, 'trạm', '站 (trạm): đứng; trạm, bến.', 'Động từ', 'Dùng như động từ khi nói về tư thế đứng.'),
    (3, 967, 'trương', '张 (trương): giương ra; tờ (lượng từ).', 'Động từ, Lượng từ', 'Trong cách nói “这位客人订了一万张票”, 张 mang nghĩa “tờ, tấm (lượng từ)”.'),
    (3, 968, 'trưởng', '长 (trưởng): lớn lên.', 'Động từ, Hậu tố', 'Dùng khi người hoặc sinh vật lớn lên. Trong 校长, 长 chỉ người đứng đầu.'),
    (3, 969, 'trước cấp', '着 (trước): dính, chạm tới; (trợ từ tiếp diễn). 急 (cấp): gấp, vội; nóng lòng.', 'Tính từ', 'Trong cách nói “妈妈不用着急”, 着急 mang nghĩa “sốt ruột”.'),
    (3, 970, 'chiếu', '照 (chiếu): soi, chiếu; chụp (ảnh).', 'Động từ', 'Trong cách nói “我怎样才能照到天上的月亮”, 照 mang nghĩa “chụp (ảnh)”.'),
    (3, 971, 'chiếu cố', '照 (chiếu): soi, chiếu; chụp (ảnh). 顾 (cố): ngoái nhìn, trông nom.', 'Động từ', 'Trong cách nói “已经会照顾弟弟了”, 照顾 mang nghĩa “chăm sóc”.'),
    (3, 972, 'chiếu phiến', '照 (chiếu): soi, chiếu; chụp (ảnh). 片 (phiến): tấm, mảnh, lát.', 'Danh từ', 'Trong cách nói “请站在这张照片旁边”, 照片 mang nghĩa “bức ảnh”.'),
    (3, 973, 'chiếu tướng', '照 (chiếu): soi, chiếu; chụp (ảnh). 相 (tướng): hình ảnh.', 'Động từ', 'Trong cách nói “照相时只能站在中间吗”, 照相 mang nghĩa “chụp ảnh”.'),
    (3, 974, 'trực đáo', '直 (trực): thẳng, ngay thẳng. 到 (đáo): đến, tới.', 'Động từ', 'Trong cách nói “直到今天”, 直到 mang nghĩa “cho đến khi”.'),
    (3, 975, 'chỉ', '只 (chỉ): chỉ, chỉ có.', 'Phó từ', 'Đặt trước động từ để giới hạn hành động hoặc đối tượng.'),
    (3, 976, 'chỉ', '纸 (chỉ): giấy.', 'Danh từ', 'Trong cách nói “我写了半页纸”, 纸 mang nghĩa “giấy”.'),
    (3, 977, 'chỉ năng', '只 (chỉ): chỉ, chỉ có. 能 (năng): có thể, được; năng lực.', 'Cụm từ', 'Trong cách nói “照相时只能站在中间吗”, 只能 mang nghĩa “chỉ có thể”.'),
    (3, 978, 'chỉ thị', '只 (chỉ): chỉ, chỉ có. 是 (thị): là, đúng, phải.', 'Phó từ, Liên từ', 'Trong cách nói “只是有点儿累”, 只是 mang nghĩa “chỉ là”.'),
    (3, 979, 'chỉ yếu', '只 (chỉ): chỉ, chỉ có. 要 (yếu): cần, muốn; quan trọng.', 'Liên từ', 'Thường đi với 就 để diễn đạt điều kiện đủ.'),
    (3, 980, 'chỉ hữu', '只 (chỉ): chỉ, chỉ có. 有 (hữu): có, sở hữu.', 'Liên từ', 'Thường đi với 才 để nêu điều kiện cần.'),
    (3, 981, 'trung', '中 (trung): giữa, trung tâm; trung học.', 'Danh từ', 'Trong cách nói “生活中有人说错话”, 中 mang nghĩa “trong, giữa”.'),
    (3, 982, 'trung gian', '中 (trung): giữa, trung tâm; trung học. 间 (gian): gian, phòng; khoảng giữa.', 'Danh từ', 'Trong cách nói “照相时只能站在中间吗”, 中间 mang nghĩa “ở giữa”.'),
    (3, 983, 'chung vu', '终 (chung): kết thúc, cuối cùng. 于 (vu): ở, tại; đối với.', 'Phó từ', 'Trong cách nói “我终于明白了”, 终于 mang nghĩa “cuối cùng cũng”.'),
    (3, 984, 'chủng', '种 (chủng): loại, kiểu, giống.', 'Lượng từ', 'Trong cách nói “你吃过这种鱼吗”, 种 mang nghĩa “loại (lượng từ)”.'),
    (3, 985, 'trọng yếu', '重 (trọng): nặng, hệ trọng. 要 (yếu): cần, muốn; quan trọng.', 'Tính từ', 'Trong cách nói “对我很重要”, 重要 mang nghĩa “quan trọng”.'),
    (3, 986, 'chu mạt', '周 (chu): vòng quanh, chu kỳ; tuần. 末 (mạt): ngọn, cuối, phần chót.', 'Danh từ', 'Trong cách nói “周末我们打网球或者羽毛球”, 周末 mang nghĩa “cuối tuần”.'),
    (3, 987, 'chủ yếu', '主 (chủ): chủ, người đứng đầu. 要 (yếu): cần, muốn; quan trọng.', 'Tính từ', 'Trong cách nói “这两种药的主要作用是什么”, 主要 mang nghĩa “chủ yếu”.'),
    (3, 988, 'chú ý', '注 (chú): rót, dồn, chú vào. 意 (ý): ý nghĩ, ý muốn.', 'Động từ', 'Trong cách nói “只有注意休息”, 注意 mang nghĩa “chú ý”.'),
    (3, 989, 'trú viện', '住 (trú): ở, cư trú. 院 (viện): viện, sân; toà nhà công.', 'Động từ', 'Trong cách nói “他住院时”, 住院 mang nghĩa “nằm viện”.'),
    (3, 990, 'tự điển', '字 (tự): chữ, văn tự. 典 (điển): sách chuẩn, điển tịch.', 'Danh từ', 'Trong cách nói “字典在书架中间”, 字典 mang nghĩa “từ điển chữ Hán”.'),
    (3, 991, 'tự hành xa', '自 (tự): tự, mình; từ. 行 (hành): đi; được. 车 (xa): xe, xe cộ.', 'Danh từ', 'Trong cách nói “路边停着三辆自行车”, 自行车 mang nghĩa “xe đạp”.'),
    (3, 992, 'tử', '子 (tử): (hậu tố danh từ).', 'Hậu tố', 'Gắn sau một số gốc từ để tạo danh từ, thường đọc thanh nhẹ.'),
    (3, 993, 'tổng', '总 (tổng): tổng, tất cả, luôn luôn.', 'Phó từ', 'Trong cách nói “最好别总低头看手机”, 总 mang nghĩa “tổng, toàn bộ”.'),
    (3, 994, 'tổng thị', '总 (tổng): tổng, tất cả, luôn luôn. 是 (thị): là, đúng, phải.', 'Phó từ', 'Trong cách nói “朋友总是来看他”, 总是 mang nghĩa “luôn luôn”.'),
    (3, 995, 'chuỷ', '嘴 (chuỷ): cái miệng, mỏ.', 'Danh từ', 'Trong cách nói “最近我的嘴有点儿疼”, 嘴 mang nghĩa “miệng”.'),
    (3, 996, 'tối hảo', '最 (tối): nhất, cực nhất. 好 (hảo): tốt, đẹp, hay.', 'Phó từ', 'Trong cách nói “嘴里有东西最好别说话”, 最好 mang nghĩa “tốt nhất”.'),
    (3, 997, 'tối hậu', '最 (tối): nhất, cực nhất. 后 (hậu): sau, phía sau.', 'Danh từ', 'Trong cách nói “直到最后他才说”, 最后 mang nghĩa “cuối cùng”.'),
    (3, 998, 'tối cận', '最 (tối): nhất, cực nhất. 近 (cận): gần.', 'Danh từ', 'Trong cách nói “最近我的嘴有点儿疼”, 最近 mang nghĩa “gần đây”.'),
    (3, 999, 'tố khách', '做 (tố): làm, chế biến. 客 (khách): khách, người ghé thăm.', 'Động từ', 'Trong cách nói “去做客时”, 做客 mang nghĩa “đến làm khách”.'),
    (3, 1000, 'tác nghiệp', '作 (tác): làm, tạo ra. 业 (nghiệp): nghề, nghiệp, sự nghiệp.', 'Danh từ', 'Trong cách nói “作业一共三页”, 作业 mang nghĩa “bài tập về nhà”.')
) AS d(level, entry_number, reading, breakdown, word_type, usage_note)
WHERE v.syllabus = '3.0-2025' AND v.level = d.level AND v.entry_number = d.entry_number;

